    // Fragmentation guard — with many open bins, mid-sized fragments
    // spread waste; mildly tax placements that leave such fragments.
    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        if fitting_bins_count > 0 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 && item_size > bin_capacity / 3 {
