    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-perfect fills (small post_residual)
    let tight_fit = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
