    // Global pressure: many open bins with high mean residual -> consolidate
    if open_bins_count > 1 {
        score += 0.02 * open_bins_count as f64 * (mean_residual - post_residual as f64);
    }

    // Slight preference for fuller bins overall
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64 * 10.0;

    score
}

