        // (existing bins are nearly full) or many bins already exist.
        let mut new_bin_score = 55.0;
        new_bin_score -= 0.6 * mean_residual;
        new_bin_score -= 1.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
