        new_bin_score *= 1.0 - 0.4 * progress;
        score = score.max(new_bin_score);
        score = new_bin_score + (post_residual as f64 - score.abs()) * 0.0;
    }

    // Global pressure: many open bins with slack -> discourage leaving more slack.
    if open_bins_count > 3 {
        score += 0.15 * (post_residual as f64 - mean_residual).abs();
    }

    score
}

