}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity-fraction buckets.
    let item_class = item_size / 10; // 0..10 (1..100 sizes)
    let post_class = post_residual / 10;

    // Reward near-perfect fits: post_residual in small residue class.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 300.0; // near-perfect
    } else if post_residual <= 15 {
        score -= 80.0;
    }

    // Penalize dead space that no plausible item can fill.
    // Items are >= 1, but useful pairing threshold: dead space below typical small items is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0; // unusable sliver
    }

    // Modulo coupling: does post_residual align with next_item_size?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // exact lookahead fit
        } else if post_residual >= next_item_size {
            // reward leaving room for the next item
            let slack = post_residual - next_item_size;
            score -= 150.0 - (slack as f64).min(150.0);
        } else {
            // next item cannot fit here; penalize proportionally to overflow
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
        // Harmonic alignment: post_residual divisible by next item's decile class
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual as f64 % next_class == 0.0 && post_residual > 0 {
            score -= 25.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 400.0;
    }

    // Class-matching reward: placing item into bin whose residual class complements it.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 40.0;
    }

    // Prefer filling fuller bins (tight packing) via residual fraction.
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 50.0;

    // Early in stream: be slightly more willing to open new bins for large items
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive for large items or when fit is bad elsewhere.
        if item_size > bin_capacity / 2 {
            score -= 60.0 * (1.0 - progress);
        }
        score += 30.0; // mild default penalty so decent fits into open bins win
    }

    // Congestion: many open bins -> favor consolidation into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling: if this bin is much emptier than average, discourage wasting it.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are useless -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward exact match with the lookahead item (k=2 lookahead chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize if post_residual can't fit the next item but is still sizable.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is great.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }
    // Many alternatives: mild penalty for mediocre fits.
    if fitting_bins_count > 3 && post_residual > 20 {
        score += 5.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            // Prefer filling existing bins when reasonable fits exist.
            score += 12.0 + mean_residual * 0.1;
        }
    }

    // Late in the stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: if the next item exactly fills the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect chain: bin fully consumed over two steps
        } else if post_residual > next_item_size {
            // next item fits too: reward proportionally to how tight the chain is
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.35;
        } else {
            // next item won't fit in leftover: penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 8.0 + waste * 0.30;
        }
    }

    // Relative tightness vs mean residual: prefer bins tighter than average.
    let tightness = mean_residual - post_residual as f64;
    score -= tightness * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it neutral-ish, only attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).powi(2);
        score += 12.0 - 20.0 * fragmentation;
        // early in stream, opening bins is cheap; late, discourage
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual (tight fit).
    // Squared penalty for leaving awkward dead space, scaled by item size
    // so big items demand tighter fits.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / (bin_capacity as f64);

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // especially if the chain-fit is tight.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let slack_after_next = post_residual as f64 - nxt;
            // Reward tight two-item chains heavily.
            score -= 18.0 - 0.25 * slack_after_next;
            if slack_after_next <= 5.0 {
                score -= 12.0;
            }
        } else {
            // Leaving a gap the next item cannot use: penalize proportionally.
            let gap = nxt - post_residual as f64;
            if gap <= 10.0 {
                score += 0.8 * gap;
            }
        }
    }

    // Last-chance bin: this is the only bin that fits; avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 30.0 + 0.5 * (item_size as f64);
        // If the resulting residual would be very large, soften the bonus
        // so a fresh bin can win for wasteful placements.
        if pr > 40.0 {
            score += 0.7 * (pr - 40.0);
        }
    }

    // New empty bin candidate: recognize it and price it against reuse.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; becomes cheaper late in the stream
        // when fewer placements remain to amortize it.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 55.0 - 20.0 * progress;
        // If the next item is large and current bins are fragmented, a fresh
        // bin is attractive.
        if next_item_size >= 50 && mean_residual < next_item_size as f64 {
            new_bin_cost -= 15.0;
        }
        // Many open bins with slack: discourage adding more.
        new_bin_cost += 1.5 * open_bins_count as f64;
        score = new_bin_cost + 0.3 * pr;
    }

    // Global state coupling: if mean residual across open bins is high,
    // prefer bins below the mean (consolidate fragmented space).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // Small penalty for using nearly-empty bins early (keep flexibility).
    if bin_residual != bin_capacity && bin_residual as f64 > mean_residual + 30.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, moderate residuals are acceptable; late in the stream,
    // only very small residuals should be rewarded strongly.
    let poly = x * x * (1.0 - progress) + x * x * x * progress;
    score += 8.0 * poly * cap * 0.1;

    // Reward tight fits increasingly with progress (subtract a smooth function).
    let tightness = 1.0 - x;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Penalize opening a new bin (empty candidate) unless residuals are generally poor.
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    let mean_r = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    let residual_pressure = (mean_r / cap).clamp(0.0, 1.0);
    score += is_new_bin * (10.0 + 20.0 * progress) * (1.0 - 0.6 * residual_pressure);

    // Last-chance bonus: if this is the only bin that can fit, strongly favor it.
    if fitting_bins_count == 1 && is_new_bin == 0.0 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: penalize if post_residual is too small for the next item,
    // reward if post_residual exactly matches the next item (perfect chaining).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (pr - ni).abs() < 0.5 {
            score -= 5.0 * (1.0 + progress);
        } else if pr < ni && pr > 0.0 {
            // dead space relative to next item: smooth penalty scaled by progress
            let dead = (ni - pr) / cap;
            score += 4.0 * dead * (1.0 + progress) * (1.0 + x);
        }
    }

    // Mild penalty for spreading across many bins when residuals are healthy.
    score += (open_bins_count as f64).ln() * 0.5 * residual_pressure;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: capacity divided into 10-wide classes.
    let class = post_residual / 10;
    // Dead-space classes: residual < 10 is nearly useless; 10..20 fits small items.
    score += match class {
        0 => -30.0,           // perfect closure (residual 0..9)
        1 => -12.0,           // near-perfect
        2 => 4.0,
        3 => 8.0,
        4 => 12.0,
        5 => 15.0,
        _ => 20.0,
    };

    // Exact-fit bonus via modulo arithmetic on capacity fractions.
    if post_residual == 0 {
        score -= 50.0;
    }
    if bin_capacity % post_residual.max(1) == 0 && post_residual > 0 && post_residual < item_size {
        score -= 6.0; // residual divides capacity: likely reusable by future harmonics
    }

    // Coupling with lookahead item: does next item fit the post-residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + 0.2 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize proportionally to waste
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when mean residual across open bins is small
    // (open bins too full to be useful) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 - 2.0 * mean_residual - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open
        }
    }

    // Mild penalty for proliferating bins when many are open.
    score += 0.3 * open_bins_count as f64;

    // Integer-division threshold: reward leaving residuals in {0,10..19,25,50} harmonics.
    let harmonic = post_residual == 0 || post_residual == 25 || post_residual == 50
        || (10..=19).contains(&post_residual);
    if harmonic {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Anything below the minimum item size (1..100 unknown, assume small threshold ~12)
    // is pure waste; penalize hard as post_residual approaches that zone.
    let dead_zone: f64 = 12.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_zone {
        score += (dead_zone - pr) * 4.0; // escalating penalty for tiny gaps
    }

    // Reward tight fits (post_residual near 0 but still usable).
    if pr == 0.0 {
        score -= 25.0; // perfect closure is ideal
    } else if pr <= 5.0 {
        score -= 10.0; // near-perfect fit
    }

    // Coupling with next item lookahead: if the residual can host the next item,
    // this bin remains valuable; otherwise discount it.
    if next_item_size > 0 {
        if pr >= next_item_size as f64 {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., this call is for the empty bin and mean residual is small).
    if bin_residual == bin_capacity {
        if mean_residual < 8.0 {
            score -= 20.0;
        } else {
            score += 10.0;
        }
    }

    // Slight stream-progression damping: late in the stream, prefer closing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near-exact match of next item into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: fill bin completely over two items
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64); // near-chain bonus
        } else {
            // next item won't fit: penalize leaving a residual that is awkwardly large
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Favor bins whose residual is below mean (tight bins get emptied first)
    score += 2.0 * (mean_residual - post_residual as f64) / 100.0;

    // Penalize large post_residual waste relative to smallest useful item (1..100 interface)
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // nearly full bin: excellent placement
    } else if post_residual > 50 {
        score += 5.0; // leaving big dead space is bad
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 10.0; // default: prefer existing bins
        // but if next item is large and current residuals are tight, opening fresh is fine
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 20.0;
        }
        // late in stream with many open bins, avoid spawning more
        if open_bins_count > 8 {
            score += 12.0;
        }
    }

    // Slight progression bias: early on, be picky; later, pack greedily
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (bin_capacity as f64 - post_residual as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    let t = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - t) * (1.0 - t) * (1.0 - t);

    // Penalize dead space that no plausible future item can use
    if post_residual > 0 {
        let dead = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).max(0.0)
        } else {
            post_residual as f64
        };
        score += 0.8 * dead;
    }

    // Perfect lookahead fit: strong reward if next item exactly fills post_residual
    if next_item_size == post_residual && post_residual > 0 {
        score -= 25.0;
    }
    // Next item still fits comfortably: mild reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: keep new bins slightly unattractive unless
    // no good fit exists (high mean residual / tight fits elsewhere)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64).ln() + 1.0;
        score += 12.0 + 10.0 * (1.0 - progress) - 2.0 * mean_residual / pressure;
        // If item is large, opening a fresh bin is more acceptable
        score -= 0.15 * item_size as f64;
    }

    // Prefer bins with below-average residual (fill fuller bins first)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: quadratic in normalized post-residual (dead space penalty)
    let mut score = pr_norm * pr_norm * cap;

    // Smooth non-linear coupling with stream progress:
    // early on tolerate residual waste; later, penalize it more strongly.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Interaction: post_residual x item_size — prefer bins where the item
    // fills a large fraction of remaining space (smooth cubic term).
    let fill_ratio = item_norm / (1.0 + pr_norm);
    score -= 30.0 * fill_ratio * fill_ratio * fill_ratio * (0.5 + progress);

    // Smooth penalty when post-residual is awkwardly small (dead space),
    // modeled with a smooth bump around mid-range residuals.
    let bump = (pr_norm * std::f64::consts::PI).sin();
    score -= 8.0 * bump * bump * pr_norm;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    let next_norm = next_item_size as f64 / cap;
    if next_item_size > 0 {
        let room = pr_norm - next_norm;
        if room >= 0.0 {
            score -= 12.0 * room * (1.0 - room) * 4.0 * room.max(0.0).min(1.0);
        } else {
            score += 6.0 * (-room) * (-room);
        }
    }

    // Mild preference toward consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Nudge toward bins with residuals below the mean (tighter packing).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
