        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 12.0; // near-chain fit
            } else {
                score -= (gap as f64) * 0.15; // milder reward for loose fits
            }
        } else {
            // next item won't fit: penalize proportional to overflow class
            let over = next_item_size - post_residual;
            let over_class = over / 20; // harmonic bucket of overflow
            score += 4.0 + (over_class as f64) * 3.0;
        }
    } else {
        // Last item: prefer closing bins entirely
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless residue would be terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current item is large or all open bins would leave big dead space.
    if bin_residual == bin_capacity {
        // neutral baseline for the fresh bin; make it competitive
        score = (bin_capacity - item_size) as f64 * 0.9;
        if item_size >= 50 {
            score -= 10.0; // big items are fine in a fresh bin
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 6.0; // fresh bin can host the pair
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits: must open
        }
    }

    // Mild global pressure: many open bins with high mean residual -> favor
    // filling existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (mean_residual - frac * bin_capacity as f64) * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small for typical future items are "dead space".
    // Penalize post_residuals in the unusable small-gap band heavily.
    if post_residual > 0 {
        let dead_threshold = 10.0_f64.max(next_item_size as f64 * 0.5);
        if (post_residual as f64) < dead_threshold {
            score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
        }
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits proportionally to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // --- Open bins pressure ---
    // Many open bins: prefer consolidating into existing ones (penalize new bins).
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        // Opening a new bin is only attractive if residuals of open bins are tiny
        // (mean_residual low) or nothing fits well.
        let spread_pressure = (mean_residual - item_size as f64).abs();
        score += 30.0 + 0.8 * open_bins_count as f64 + spread_pressure * 0.3;
    } else {
        // Slight reward for using an existing bin when bins are numerous.
        score -= 0.15 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && !new_bin {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 20.0 * next_fit;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement: mild penalty unless gap is dead anyway.
        score += 8.0;
    }

    // Early in stream: keep bins flexible (avoid creating tiny gaps too soon).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && (post_residual as f64) < 20.0 {
        score += 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal leftover space (best-fit core).
    score = post_residual as f64;

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect match: post_residual exactly equals next item size -> strongly reward.
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item can fit in this bin afterwards: reward closeness to exact match.
            score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
            if diff < 0.5 {
                score -= 40.0; // exact 2-item completion bonus
            }
        } else {
            // Next item won't fit here: penalize proportionally to how close we came
            // (near-miss dead space is worse than comfortably large residual).
            let miss = nxt - post_residual as f64;
            score += 5.0 + 10.0 * (miss / 100.0);
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter",
    // filling them first consolidates space.
    let resid = post_residual as f64;
    if mean_residual > 0.0 {
        score += 8.0 * ((mean_residual - resid) / bin_capacity as f64).max(-1.0).min(1.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize unless it offers a superior
    // structured fit (e.g. perfect 2-item match with the lookahead).
    if bin_residual == bin_capacity {
        let mut newbin_score = 60.0 + resid; // default reluctance to open new bins
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let diff = (resid - nxt).abs();
            if resid >= nxt {
                newbin_score -= 45.0 * (1.0 - diff / bin_capacity as f64);
                if diff < 0.5 {
                    newbin_score -= 35.0; // empty bin enables exact pair completion
                }
            }
        }
        // As stream matures and many bins are open, be more open to new bins
        // to avoid fragmenting old ones.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        newbin_score -= 20.0 * progress;
        score = newbin_score;
    }

    // Small penalty for leaving residual in the awkward 1..10 dead zone.
    if post_residual >= 1 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small dead space unless it's a near-exact fit:
    // tiny residuals (< 10) are likely unusable for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // but only if that residual is tight (efficient chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - 0.15 * slack;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post-residual too small for next item: dead space penalty scaled by lookahead
        score += 0.25 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer filling fuller bins: normalize residual by capacity.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio * fill_ratio;

    // Time horizon: early in the stream, be more tolerant of spreading
    // (favor new bins to create future flexibility); late, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * fill_ratio;

    // Global state: many open bins with high mean residual -> consolidate,
    // penalize bins that deviate upward from mean residual (fragmentation).
    if open_bins_count > 2 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
        score += 0.5 * (open_bins_count as f64).ln() * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: it starts fully empty; make it attractive only when
    // no open bin offers a good fit (post_residual large relative to item)
    // or early stream flexibility is valuable.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.6 * bin_capacity as f64;
        let early = progress < 0.3;
        if poor_fit || early {
            score -= 6.0 + 10.0 * (1.0 - progress);
        } else {
            // late stream: strongly discourage opening new bins
            score += 25.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer low post residual, with progress-dependent curvature
    let mut score = x * (1.0 + 2.0 * progress * (1.0 - x));
    score += 0.5 * x * x * (1.0 + progress);

    // Non-linear coupling: waste term that grows with progress
    score += progress * (x * (1.0 - x)) * 4.0;

    // Perfect fit reward (smooth)
    score -= (1.0 - x).powi(2) * 6.0 * (1.0 - progress * 0.5);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = (next_item_size as f64) / cap;
        let gap = (x - nx).abs();
        score += 0.8 * gap * gap;
        if x >= nx {
            score -= 1.5 * nx * (1.0 - progress);
        }
    }

    // Slight penalty for hoarding many open bins early
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: neutral-ish baseline with progress penalty
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (mod 10) are dead-space traps; reward big leftovers.
    let residue_class = post_residual % 10;
    if residue_class != 0 {
        score += (10 - residue_class) as f64 * 0.8; // non-round leftovers penalized
    } else {
        score -= 4.0; // perfectly divisible leftover is reusable
    }

    // Integer-division thresholds on post_residual: classify leftover usability
    let usable = post_residual / 10; // how many 10-sized items still fit
    score -= usable as f64 * 2.5;

    // Penalize leaving a leftover that no plausible small item (<=20) can use
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // dead space
    }

    // Coupling with next item (lookahead): reward exact fit for next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0; // perfect chain fit
        } else if post_residual > next_item_size {
            score -= 3.0;
        } else {
            score += 5.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish score so it wins only when fits are terrible
    if bin_residual == bin_capacity {
        score = (bin_capacity - post_residual) as f64 + 12.0;
        // discourage opening new bins when many bins already fit the item
        if fitting_bins_count > 2 {
            score += 20.0 * (fitting_bins_count as f64 - 2.0).min(4.0);
        }
    }

    // Tight-fit bonus: residual fraction near zero is excellent
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - frac) * 6.0;

    // Slight preference for fuller bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Mean-residual coupling: prefer bins far below mean residual (fill emptier gaps)
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) more heavily than large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward exact and near-exact fits.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If the next item cannot fit the post-residual, the leftover is likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins pressure.
        score += 25.0 + pressure * 8.0;
    } else {
        score -= pressure.min(20.0);
    }

    // Mild preference for bins with below-mean residual (fill emptier bins first
    // keeps tighter bins for tight fits).
    if bin_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step fill
        } else if post_residual >= next_item_size {
            // reward proportional to how well next item fits the leftover
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack.min(30.0);
        } else {
            // next item cannot fit here; penalize large dead space slightly more
            score += 5.0;
        }
        // bonus if chain of both current and next item nearly fills the bin
        if item_size as f64 + next_item_size as f64 >= bin_residual as f64 * 0.95
            && item_size + next_item_size <= bin_residual {
            score -= 25.0;
        }
    }

    // Prefer bins tighter than the mean residual (good fits), avoid spreading into loose bins
    let mean_res_u = mean_residual;
    if (bin_residual as f64) < mean_res_u {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving tiny unusable fragments (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Early in stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0;

    // New-bin candidate should be mildly unattractive unless nothing else fits well
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // chain fit bonus: next item leaves again a tight residual
            let chain_post = post_residual - next_item_size;
            if chain_post < 10 {
                score -= 8.0;
            }
        } else {
            score += 6.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    } else {
        // last item: prefer zero waste outright
        score -= 10.0 * if post_residual == 0 { 1.0 } else { 0.0 };
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, unless the item fits
    // terribly everywhere (large item, few fitting bins, high mean residual waste)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let desperation = (item_size as f64 / 100.0) * (1.0 - progress);
        score += 20.0 - 18.0 * desperation;
        // opening new bins is cheaper late in stream when many bins are open
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0) * 0.2;
    }

    // Global balance: prefer bins whose residual deviates from mean residual
    // (keep a diverse residual portfolio for future items)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for fuller bins overall
    score += 0.1 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post_residual), with a convex penalty
    // on wasted space that strengthens as the stream progresses.
    let mut score = pr;

    // Smooth non-linear coupling: quadratic dead-space penalty modulated by progress.
    let waste_penalty = (pr_norm * pr_norm) * cap * (0.5 + 1.5 * progress);
    score += waste_penalty;

    // Cubic interaction term: small residuals are great, large residuals get
    // increasingly punished via smooth polynomial growth.
    score += 40.0 * pr_norm * pr_norm * pr_norm * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - pr_norm);
    }

    // Lookahead coupling: reward bins whose post_residual can still hold the
    // next item (smooth ramp), penalize near-miss dead space otherwise.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let usable = (pr / (n + 1.0)).ln().max(0.0);
            score -= 8.0 * usable.min(3.0);
        } else {
            let gap = (n - pr) / cap;
            score += 25.0 * gap * (0.5 + progress);
        }
    }

    // Mild pressure against proliferating bins relative to stream position.
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Small bonus for bins already tighter than average (smooth sigmoid-like term).
    let avg = mean_residual / cap;
    let tightness = 1.0 / (1.0 + (pr_norm - avg).exp());
    score -= 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity split into 10 classes of size 10.
    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward placements whose post-residual falls into a "usable" harmonic class.
    // Classes 0 (perfect fit) and 1 (tiny dead space) are excellent.
    match post_class {
        0 => { score -= 25.0; }                       // perfect fit
        1 => { score -= 15.0; }                       // near-perfect
        2 => { score -= 5.0; }                        // decent
        3 | 4 => { score += 4.0; }                    // mediocre dead space
        _ => { score += 10.0; }                       // large unusable remainder
    }

    // Modulo coupling: does post_residual pair well with the lookahead item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // The next item can exactly fill or complement this bin's remainder.
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 20.0;                        // chains a perfect fit
            } else if gap <= 5 {
                score -= 10.0;
            } else {
                score -= 2.0;
            }
        } else {
            // Next item cannot use this residual: penalize by the overflow amount.
            let overflow = next_item_size - post_residual;
            score += (overflow as f64) * 0.5;
        }
    } else {
        // Last item: strongly prefer closing bins out.
        score -= 30.0;
    }

    // Integer-division threshold on residual: residuals divisible by 10 are
    // "harmonically aligned" with the class grid and easier to fill later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible (post_residual would be huge).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + (post_residual as f64) * 0.1;
    }

    // New-bin candidate: opening a fresh bin is attractive when existing bins
    // fit poorly. Penalize the new bin when good fits exist, reward it when
    // the stream is early or mean residual is large and fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - (post_residual as f64)).abs();
        score += 18.0 * progress
            + if post_class <= 2 { 30.0 } else { 0.0 }   // item would waste a fresh bin
            - if post_class >= 4 { 8.0 } else { 0.0 };   // big item: fresh bin OK
        let _ = fragmentation;
    }

    // Mild pressure to consolidate into fewer bins as open-bin count grows.
    score += (open_bins_count as f64) * 0.05;

    score
}

