        let pair_slack = bin_residual - pair;
        if pair_slack <= 6 {
            score -= 110.0;
        } else if pair_slack <= 20 {
            score -= 40.0;
        } else {
            score -= 15.0;
        }
    }

    // NEW: three-item chain check when residual can absorb current+next with room for a small item.
    let chain = pair.saturating_add(next_item_size.min(20));
    if chain > pair && bin_residual >= chain && bin_residual - chain <= 12 {
        score -= 60.0;
