        score += open_bins_count as f64 * 1.2;
    }

    // Mean-residual coupling, tightened band.
    if (bin_residual as f64) > mean_residual + 15.0 {
        score += 28.0;
    } else if (bin_residual as f64) < mean_residual - 15.0 {
        score -= 18.0;
