    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 160.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual as f64 % next_class == 0.0 && post_residual > 0 {
            score -= 25.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 400.0;
    }

    // Class-matching reward: residual class complements the item.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 40.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 50.0;

    // Two-item lookahead: reward residuals fitting current+next tightly.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 90.0;
