            score -= 30.0;
        }
    }

    // NEW: three-item horizon — if post_residual can still host the next item
    // exactly, this placement preserves a future tight fit; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next == 0 {
            score -= 60.0;
        } else if after_next <= 10 {
            score -= 35.0;
        }
    }

    // NEW: waste-aware new-bin arbitration. Compare the waste created by
    // placing here (post_residual that likely becomes dead) against the cost
    // of a fresh bin (bin_capacity - item_size of guaranteed leftover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 60.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 120.0;
        }
        // NEW: opening is justified when the item is large relative to
        // capacity (fresh bin keeps a workable residual for complements).
        if item_size >= bin_capacity * 3 / 4 {
            score -= 45.0;
        }
        score += 30.0 + 40.0 * progress;
    } else {
        // NEW: if placing here leaves a residual that is a known dead zone
        // (smaller than next item and smaller than 10), a fresh bin may be
        // better late in the stream when consolidation pressure is high.
        let dead_here = next_item_size > 0
            && post_residual < next_item_size
            && post_residual < 10;
