    // NEW: squandered-pocket guard — placing a small item into a large
    // residual and leaving a mid-sized fragment (too small for common
    // classes 30+) destroys a big pocket. Penalize when the remaining
    // residual can't hold a medium item but was big enough to.
    if bin_residual >= 60 && post_residual > 0 && post_residual < 30 && item_size < next_item_size {
        score += 22.0;
    }

    // NEW: fragment-merging bonus — if post_residual exactly equals a
    // plausible item size (multiple of 10 within 10..=60), the leftover
    // remains perfectly reusable; reward this consolidation outcome.
    if post_residual >= 10 && post_residual <= 60 && post_residual % 10 == 0 {
        score -= 28.0;
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 68.0 * (1.0 - progress);
        }
