    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // NEW: fillability-aware dead-space gradient. Instead of a flat waste
    // penalty, tax the post_residual by how far it sits from the nearest
    // "reachable" size — a multiple of 10 (item classes) or 25 (harmonic
    // complements). This continuously shapes placements toward residuals
    // that any future item class can absorb, attacking the diagnosed
    // dead-space weakness directly rather than in discrete bands.
    if post_residual > 0 && post_residual < bin_capacity {
        let dist_to_class = {
            let m = post_residual % 10;
            let d10 = m.min(10 - m) as f64;
            let m25 = post_residual % 25;
            let d25 = m25.min(25 - m25) as f64;
            d10.min(d25)
        };
