        // tax more heavily as the residual shrinks.
        let smallness = 1.0 - (post_residual as f64 / 60.0).min(1.0);
        score += dist_to_class * (1.4 + 2.6 * smallness);
        // Reward residuals that are exactly reachable by an item class.
        if dist_to_class == 0.0 && post_residual >= 10 {
            score -= 20.0;
        }
    }

    // NEW: squeeze-aware selection — when several bins fit, prefer the one
    // whose placement keeps the *global* residual structure compact: reward
    // placements that consume below-average residual bins (the tightest
    // ones) proportionally to how tight they are.
    if fitting_bins_count > 1 {
        let tightness = (mean_residual - bin_residual as f64) / bin_capacity as f64;
        if tightness > 0.0 {
            score -= (tightness * 220.0).min(45.0);
        }
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 68.0 * (1.0 - progress);
