    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 55.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Three-item chain check — current + next + a small filler (1..=10)
    // exactly fills this bin's residual; an exceptionally strong plan.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let chain = bin_residual - item_size - next_item_size;
        if chain >= 1 && chain <= 10 {
            score -= 85.0;
        }
    }

    // Two-step exactness — after placing the current item, check whether
    // post_residual can absorb next_item_size AND a mid-class filler exactly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 15 && after_next <= 45 && after_next % 5 == 0 {
            score -= 34.0;
        }
        // Chain-dead detection: remainder too small for any plausible class
        // after the next item lands here — a guaranteed waste pocket.
        if after_next > 0 && after_next < 10 {
            score += 24.0;
        }
    }

    // Residual-fragmentation tax — when many open bins exist, leaving a
    // mid-sized residual (fragment) spreads waste across bins; consolidate.
    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // NEW (gen 9): dead-space ratio shaping — the diagnosed weakness is
    // suboptimal residual/dead space. Directly tax the fraction of the bin
    // that will be wasted after this placement, with a quadratic curve so
    // large dead pockets get punished disproportionately.
    if post_residual > 0 {
        let dead_frac = post_residual as f64 / bin_capacity as f64;
        if dead_frac < 0.10 {
            score -= 20.0 * (1.0 - dead_frac * 10.0); // near-full bonus
        } else if dead_frac > 0.55 {
            score += 45.0 * ((dead_frac - 0.55) / 0.45).powi(2) * 10.0;
        }
    }

    // NEW (gen 9): residual class-fill probability — estimate how likely the
    // leftover can still host a future item given the item-class histogram
    // implied by the current item and next item sizes. Residuals below both
    // observed classes are near-dead; tax them proportionally.
    if post_residual > 0 {
        let min_class = item_class.min(next_item_size / 10).max(1) * 10;
        if post_residual < min_class {
            score += 30.0 + (min_class - post_residual) as f64 * 2.0;
        }
    }

    // NEW (gen 9): tight-fit cascade — reward placements where the current
    // item consumes nearly all of the bin's residual (waste ratio under 5%),
    // scaled by how full the bin already was. This sharpens best-fit
    // discrimination among close competitors.
    if bin_residual >= item_size && bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.85 {
            score -= 40.0 * (fill_ratio - 0.85) / 0.15;
        } else if fill_ratio < 0.4 && bin_residual < bin_capacity / 2 {
            score += 22.0; // small item into a mid pocket: likely fragmentation
        }
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 68.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        // When open bins exist but every fit is poor (large item, tiny residuals),
        // opening fresh is cheaper than shattering a usable residual.
        if fitting_bins_count > 0 && item_size > bin_capacity / 3 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 42.0 * (1.0 - progress);
            }
        }
        // Protect big pockets late in the stream.
        if fitting_bins_count > 0 && progress > 0.4 && item_size <= bin_capacity / 3 {
            if mean_residual < item_size as f64 * 1.5 {
                score -= 27.0 * progress;
            }
        }
        // If the next item is large and no open bin could hold it after
        // this placement, opening a fresh bin now preserves flexibility.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            if post_residual < next_item_size {
                score -= 32.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin discipline.
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Mid-stream fresh-bin restraint.
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        // Endgame fresh-bin economy.
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 75.0;
        }
        // NEW (gen 9): new-bin dead-space forecast — a fresh bin opened for a
        // small item while mean residual is large wastes the pooled residual;
        // scale the penalty with the gap between mean residual and item size.
        if fitting_bins_count > 0 && item_size < bin_capacity / 3 {
            let pooled_waste = (mean_residual - item_size as f64).max(0.0);
            if pooled_waste > 15.0 {
                score += (pooled_waste - 15.0).min(60.0);
            }
        }
