            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
                score -= 95.0;
            }
        }
        // Dead-pocket escape — when the best available fit would leave a
        // residual too small for any plausible item (<= 9), a fresh bin with a
        // full residual is strictly better than shattering the pocket.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 9 {
            score -= 88.0 * (1.0 - progress).max(0.2);
