        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // NEW: post-residual reusability vs. mean coupling — a leftover close to
    // the stream's mean residual is statistically most likely to be reused
    // later; reward closeness, punish outliers among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 20.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
