    if remaining_frac < 0.2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= (6.0 * (1.0 - remaining_frac * 5.0).max(0.0)) * (1.0 - (slack as f64 / 30.0).min(1.0));
    }

    // NEW: residual fragmentation guard — when many bins are open, avoid
    // placements that leave a residual just above a common item class
    // boundary (e.g., 11..=19, 21..=29), which tend to strand waste.
    if open_bins_count > 3 && post_residual >= 11 {
        let band = post_residual % 10;
        if band >= 1 && band <= 9 && post_residual < 60 {
            score += 6.0;
        }
    }

    score
}

