    // item plus a second copy of a small filler class (10..=20), the bin
    // keeps consolidating; reward proportional to remaining tile count.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 10 && after <= 20 && after % 5 == 0 {
            score -= 24.0;
        }
    }

    score
