        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // NEW: mid-band tightness gradient — among competing bins leaving
    // residuals in the 6..=14 band, prefer the one closest to the next
    // item size (a one-step fill) and tax residuals that overshoot it
    // by only a hair (near-miss pockets that will never be filled).
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= 6 && post_residual <= 14 {
        let overshoot = post_residual as i64 - next_item_size as i64;
        if overshoot >= 1 && overshoot <= 5 {
            score += 20.0;
        } else if overshoot >= -2 {
            score -= 24.0;
        }
    }

    // NEW: early-stream consolidation pressure — in the first quarter of
    // the stream, keeping residual space unified matters most; tax placements
    // that split a large pocket into two medium fragments.
    if progress < 0.25 && post_residual > 0 && post_residual < bin_residual / 2 && bin_residual > bin_capacity / 2 {
        score += 12.0 * (1.0 - progress * 4.0).max(0.0);
    }

    score
}

