    // among close competitors, scaled by stream urgency.
    if post_residual > 0 && post_residual <= 30 && fitting_bins_count > 1 {
        let urgency = (1.0 - progress).max(0.25);
        score -= 5.0 * (30.0 - post_residual as f64) * urgency;
    }

    // NEW MUTATION: Inter-item dead-space arbitration — when the mean
    // residual is low (bins are tight), aggressively avoid leaving any
    // post_residual below next_item_size + 5 (a stranded sliver); when
    // mean residual is high, allow slivers since bins are plentiful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size + 5 {
        if mean_residual < 0.35 * bin_capacity as f64 {
            score += 26.0 + (next_item_size + 5 - post_residual) as f64 * 3.5;
        } else {
            score -= 8.0;
        }
    }

    // NEW MUTATION: Fresh-bin opportunity-cost gate — opening a new bin is
    // only worth it when the best existing fit would waste more than the
    // fresh bin's expected future fill; approximate future fill by the
    // stream's mean item occupancy implied by mean_residual and cap the
    // fresh-bin bonus accordingly.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let expected_fill = (bin_capacity as f64 - mean_residual).max(1.0);
        let best_existing_waste = post_residual.max(0) as f64;
        if best_existing_waste > expected_fill * 0.6 {
            score -= 40.0;
        } else if best_existing_waste < expected_fill * 0.15 {
            score += 30.0;
        }
    }

    // NEW MUTATION: Perfect-complement sweep — if post_residual exactly
    // matches the complement of any plausible small item class (10/20/30),
    // the leftover is guaranteed reusable; reward with lookahead weighting.
    if post_residual > 0 && post_residual <= 40 && post_residual % 10 == 0 {
        score -= 24.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
