            }
        }
        // If the next item is large and no open bin could hold it after
        // this placement, opening a fresh bin now preserves flexibility.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            if post_residual < next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin discipline — opening a new bin late wastes
        // capacity unless the item is big; penalize small-item new bins late.
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Mid-stream fresh-bin restraint — between 25% and 60% progress,
        // small items should almost never open fresh bins while any fit exists.
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        // Endgame fresh-bin economy — in the final 15% of the stream,
        // opening a fresh bin for a small item is almost pure waste.
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        // Pair-fit gate — if this fresh bin can absorb BOTH the current
        // and the next item exactly, opening it is a genuine plan, not waste.
        if pair > 0 && bin_residual >= pair {
            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
                score -= 98.0;
            }
        }
        // Dead-pocket escape — when the best available fit would leave a
        // residual too small for any plausible item (<= 9), a fresh bin
        // with a full residual is strictly better than shattering the pocket.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 9 {
            score -= 90.0 * (1.0 - progress).max(0.2);
        }
        // Next-item dead-pocket escape — if the current fit would leave a
        // residual just below next_item_size (unusable by the immediate
        // successor), a fresh bin preserves that space for the successor.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score -= 62.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin exact-pair plan — opening a bin whose capacity is
        // exactly current + next (or within 2) is a perfect two-item plan.
        if next_item_size > 0 {
            let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
            if diff >= 0 && diff <= 2 {
                score -= 112.0;
            }
        }
        // Oversized-item fresh-bin sharpening — items above 60% of capacity
        // almost never share a bin; when any open bin would be shattered to
        // a near-dead pocket (< 15 left), prefer the fresh bin aggressively.
        if fitting_bins_count > 0 && item_size * 5 > bin_capacity * 3 {
            if post_residual > 0 && post_residual < 15 {
                score -= 52.0;
            }
        }
        // Fresh-bin tileability — if the fresh bin's capacity can be
        // tiled by the next item repeated k>=2 times after this placement,
        // opening it now is a multi-item consolidation plan.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let after = bin_capacity - item_size;
            if after % next_item_size == 0 && after / next_item_size >= 2 {
                score -= 44.0;
            }
        }
        // NEW: fresh-bin mid-band escape — when every existing fit leaves
        // a residual in the hard-to-fill 10..=19 band, a fresh bin keeps
        // one clean pocket instead of one more fragment.
        if fitting_bins_count > 0 && post_residual >= 10 && post_residual <= 19 {
            score -= 40.0 * (1.0 - progress).max(0.3);
        }
        // NEW: fresh-bin exact-complement plan — item plus a class-multiple
        // filler exactly tiles the fresh capacity (e.g. 100 = 40 + 60).
        if item_size > 0 && bin_capacity % 10 == 0 && item_size < bin_capacity {
            let rem = bin_capacity - item_size;
            if rem % 10 == 0 && rem >= 20 {
                score -= 26.0;
            }
        }
        score += 30.0 + 40.0 * progress;
    }

    // Waste-floor shaping for regular placements — when several bins fit,
    // a placement leaving a residual of 10..=19 is a near-dead pocket for
    // most distributions; tax it progressively.
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 19 {
        score += 20.0 + (19 - post_residual as i32) as f64 * 3.0;
    }

    // Sub-next dead-band sharpening — when multiple bins fit, a placement
    // whose residual sits within 8 units below next_item_size is unusable
    // by the immediate successor; tax proportionally to closeness.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 8 {
            score += 14.0 + (8 - gap as i32) as f64 * 4.0;
        }
    }

    // Congestion: many open bins -> favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals from being consumed by small items late in stream.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Late-stream exactness boost — perfect/near-perfect fits matter more
    // when few items remain.
    let remaining_frac = 1.0 - progress;
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Divisibility-aware waste penalty — leftover that no multiple of any
    // plausible item class fills is taxed mildly.
    if post_residual > 0 && post_residual < bin_capacity {
        let cls = (post_residual / 10).max(1);
        if post_residual % (cls * 10) != 0 && post_residual < 50 {
            score += 11.0;
        }
    }

    // Exact-fill lookahead sweep — reward placements where the residual
    // after this item can be tiled exactly by the next item repeated k
    // times (k >= 1) with zero leftover.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // Post-residual reusability vs. mean coupling — a leftover close to
    // the stream's mean residual is statistically most likely to be reused
    // later; reward closeness, punish outliers among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 22.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
    }

    // Dead-zone gradient refinement — residuals in the 20..=34 band are
    // only fillable by mid-class items; when the next item is small
    // (<= 10), such residuals are likely to survive untapped.
