        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 330.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Dead-space penalty: smooth, magnitude-aware version.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            let unfillable = (next_item_size - post_residual) as f64;
            score += 40.0 + unfillable * 3.0;
        }
        if post_residual < 10 {
            score += 110.0;
        }
