    // stream remains and several bins fit, escalate the reward for
    // placements leaving post_residual within 6 of the next item size;
    // chained near-exact handoffs early compound into fewer total bins.
    if progress < 0.5 && fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
