    // item twice, prefer leaving that big pocket intact unless the fit is
    // near-exact; protects consolidation capacity mid-stream.
    if next_item_size > 0 && bin_residual >= 2 * next_item_size && item_size < next_item_size {
        if post_residual > next_item_size + 15 {
            score += 18.0 * (1.0 - progress);
        }
    }

    score
}

