    // exist (multiple fitting bins), so unique fits stay untouched.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting — in the final third of the
    // stream, prefer placements that leave a residual exactly reusable by
    // the next item even at the cost of a slightly larger current fit;
    // chains of exact handoffs eliminate trailing waste bins.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // NEW: Zero-waste sweep — when the current item alone nearly fills the
    // bin (post_residual <= 5) and multiple bins compete, escalate the
    // reward with progress so late-stream near-perfect fits dominate any
    // consolidation heuristic and the last bins close tightly.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual <= 5 {
        score -= 30.0 + 45.0 * progress;
    }

    // NEW: Fragment-sink bonus — a placement that drains a small pocket
    // (bin_residual <= 15) into a near-zero leftover recycles otherwise
    // stranded space; reward it so tiny residuals get consumed instead of
    // surviving as waste bins.
    if bin_residual >= item_size && bin_residual <= 20 && post_residual <= 6 {
        score -= 48.0;
    }

    // NEW: Big-item pocket guard — when the item is large (> half capacity)
    // and this bin is the only one that can hold it, protect the choice
    // from consolidation taxes that would otherwise push toward a fresh bin.
    if fitting_bins_count == 1 && item_size > bin_capacity / 2 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
