    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // MUTATION: Dead-space gradient sweep — among competing bins, apply a
    // continuous mild penalty proportional to post_residual beyond the
    // next-item slack, so the tightest bin wins even when no discrete
    // tier fires; this directly attacks residual dead space.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size + 10 {
