    }

    // MUTATION: Perfect-close momentum — when this placement closes the
    // bin exactly and more items remain, reward extra strongly late in
    // the stream, since closed bins cannot accumulate dead space.
    if post_residual == 0 {
        score -= 60.0 * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
