        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Dead-space budget coupling.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Near-perfect-fit gradient sharpening.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    // Dual-lookahead consolidation.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // Waste-gap interpolation.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual < 60 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 14.0;
        } else if m >= 7 {
            score += 6.0 + (m - 7) as f64 * 3.0;
        }
    }

    // Triple-chain consolidation.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 0 && (after_pair == next_item_size || after_pair % 10 == 0) {
            score -= 46.0;
        }
    }

    // Combined fine-grained residual + lookahead.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Class-aware dead-zone tax.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket.
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — two-item exact close.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // NEW: Crowded-state best-fit hardening — with many open bins and many
    // fitting candidates, the tightest fit dominates; sharpen the gradient
    // so near-perfect placements beat mediocre ones decisively.
    if fitting_bins_count > 3 && post_residual > 0 && post_residual <= 6 {
        score -= 30.0 + (6 - post_residual as i32) as f64 * 8.0;
    }

    // NEW: Endgame pocket conservation — in the final 10% of the stream,
    // never shatter a residual larger than the next item when a smaller
    // pocket exists; tax placements leaving dead mid-range leftovers.
    if progress > 0.9 && post_residual > 0 && post_residual < 12 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
            score -= 32.0;
        }
    }

    // Pair exactness — residual exactly equals current+next is a jackpot.
    if pair > 0 && bin_residual == pair {
        score -= 266.0;
    }

    // Multi-fill potential — how many additional items of next size could
    // still land in this bin after the current one. More = better consolidation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let multi = post_residual / next_item_size;
        if multi >= 2 {
            score -= 22.0 * (multi.min(4) as f64);
        }
    }

    // Reusability shaping: leftover between ~15% and ~45% of capacity is highly reusable.
    if post_residual > 0 {
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 30.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
    }

    // Exact-complement chain — post_residual can exactly absorb next item
    // plus another known-size chunk; near-perfect plan, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 68.0;
        }
    }

    // Avoid leaving residuals just below the next item size (dead pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax — residuals too small for most item classes
    // (1..=9) are almost guaranteed waste; scale penalty with depth.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
    }

    // Harmonic-fit bonus — post_residual matching common complements of
    // typical item sizes (multiples of 25 or 50) stays fillable.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0) {
        score -= 35.0;
    }

    // Mid-band residual shaping — reward exactly-fillable remainders,
    // punish near-miss remainders just above the next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
    }

    // Fit-quality gradient among competing bins — push selection toward
    // the bin whose placement leaves the smallest post_residual relative
    // to the item's own class.
    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 58.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Three-item chain check — current + next + a small filler (1..=10)
    // exactly fills this bin's residual; an exceptionally strong plan.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let chain = bin_residual - item_size - next_item_size;
        if chain >= 1 && chain <= 10 {
            score -= 88.0;
        }
    }

    // Two-step exactness — after placing the current item, check whether
    // post_residual can absorb next_item_size AND a mid-class filler exactly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 15 && after_next <= 45 && after_next % 5 == 0 {
            score -= 36.0;
        }
        if after_next > 0 && after_next < 10 {
            score += 26.0;
        }
    }

    // Residual-fragmentation tax — when many open bins exist, leaving a
    // mid-sized residual (fragment) spreads waste across bins; consolidate.
    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        // When open bins exist but every fit is poor (large item, tiny residuals),
        // opening fresh is cheaper than shattering a usable residual.
        if fitting_bins_count > 0 && item_size > bin_capacity / 3 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 45.0 * (1.0 - progress);
            }
        }
        // Protect big pockets late in the stream.
        if fitting_bins_count > 0 && progress > 0.4 && item_size <= bin_capacity / 3 {
            if mean_residual < item_size as f64 * 1.5 {
                score -= 27.0 * progress;
            }
        }
        // If the next item is large and no open bin could hold it after
        // this placement, opening a fresh bin now preserves flexibility.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            if post_residual < next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin discipline — opening a new bin late wastes
        // capacity unless the item is big; penalize small-item new bins late.
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Mid-stream fresh-bin restraint — between 25% and 60% progress,
        // small items should almost never open fresh bins while any fit exists.
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        // Endgame fresh-bin economy — in the final 15% of the stream,
        // opening a fresh bin for a small item is almost pure waste.
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        // Pair-fit gate — if this fresh bin can absorb BOTH the current
        // and the next item exactly, opening it is a genuine plan, not waste.
        if pair > 0 && bin_residual >= pair {
            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
                score -= 98.0;
            }
        }
        // Dead-pocket escape — when the best available fit would leave a
        // residual too small for any plausible item (<= 9), a fresh bin
        // with a full residual is strictly better than shattering the pocket.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 9 {
            score -= 90.0 * (1.0 - progress).max(0.2);
        }
        // Next-item dead-pocket escape — if the current fit would leave a
        // residual just below next_item_size (unusable by the immediate
        // successor), a fresh bin preserves that space for the successor.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score -= 62.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin exact-pair plan — opening a bin whose capacity is
        // exactly current + next (or within 2) is a perfect two-item plan.
        if next_item_size > 0 {
            let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
            if diff >= 0 && diff <= 2 {
                score -= 112.0;
            }
        }
        // Oversized-item fresh-bin sharpening — items above 60% of capacity
        // almost never share a bin; when any open bin would be shattered to
        // a near-dead pocket (< 15 left), prefer the fresh bin aggressively.
        if fitting_bins_count > 0 && item_size * 5 > bin_capacity * 3 {
            if post_residual > 0 && post_residual < 15 {
                score -= 52.0;
            }
        }
        // Fresh-bin tileability — if the fresh bin's capacity can be
        // tiled by the next item repeated k>=2 times after this placement,
        // opening it now is a multi-item consolidation plan.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let after = bin_capacity - item_size;
            if after % next_item_size == 0 && after / next_item_size >= 2 {
                score -= 44.0;
            }
        }
        // Fresh-bin fragment-consolidation — when open bins hold many
        // small scattered fragments (low mean residual, many bins), opening
        // one fresh bin for a large item keeps those fragments intact for
        // the many small items that follow, instead of burning the single
        // large pocket that remains.
        if fitting_bins_count > 0 && open_bins_count > 3 && item_size > bin_capacity / 2 {
            if mean_residual < item_size as f64 * 1.2 {
                score -= 40.0 * (1.0 - progress).max(0.25);
            }
        }
        // Fresh-bin mid-fit gate — when an open-bin fit would leave a
        // residual in the awkward 30..=45 band (too big to die, too small
        // to tile reliably) while the fresh bin can hold current+next with
        // slack <= 10, prefer the fresh bin as a deliberate two-item plan.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= 30 && post_residual <= 45 {
            let fresh_slack = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_slack <= 10 {
                score -= 58.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin triple-tile plan — if the fresh bin can hold the
        // current item plus the next item twice with <= 5 slack, opening it
        // is a three-item consolidation that eliminates a whole future bin.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let t3 = bin_capacity - (item_size + 2 * next_item_size);
            if t3 <= 5 {
                score -= 74.0 * (1.0 - progress).max(0.4);
            }
        }
        score += 30.0 + 40.0 * progress;
    }

    // Waste-floor shaping for regular placements — when several bins fit,
    // a placement leaving a residual of 10..=19 is a near-dead pocket for
    // most distributions; tax it progressively (sharpened slope).
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 19 {
        score += 24.0 + (19 - post_residual as i32) as f64 * 4.0;
    }

    // Sub-next dead-band sharpening — when multiple bins fit, a placement
    // whose residual sits within 8 units below next_item_size is unusable
    // by the immediate successor; tax proportionally to closeness.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 8 {
            score += 14.0 + (8 - gap as i32) as f64 * 4.0;
        }
    }

    // Congestion: many open bins -> favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals from being consumed by small items late in stream.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Late-stream exactness boost — perfect/near-perfect fits matter more
    // when few items remain.
    let remaining_frac = 1.0 - progress;
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Divisibility-aware waste penalty — leftover that no multiple of any
    // plausible item class fills is taxed mildly.
    if post_residual > 0 && post_residual < bin_capacity {
        let cls = (post_residual / 10).max(1);
        if post_residual % (cls * 10) != 0 && post_residual < 50 {
            score += 11.0;
        }
    }

    // Exact-fill lookahead sweep — reward placements where the residual
    // after this item can be tiled exactly by the next item repeated k
    // times (k >= 1) with zero leftover.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // Post-residual reusability vs. mean coupling — a leftover close to
    // the stream's mean residual is statistically most likely to be reused
    // later; reward closeness, punish outliers among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 22.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
    }

    // Dead-zone gradient refinement — residuals in the 20..=34 band are
    // only fillable by mid-class items; when the next item is small
    // (<= 10), such residuals are likely to survive untapped.
    if post_residual >= 20 && post_residual <= 34 && next_item_size > 0 && next_item_size <= 10 {
        score += 16.0;
    }

    // Two-bin exact-split plan — when exactly two bins fit and this
    // placement leaves a residual that exactly equals next_item_size, it
    // is a perfect handoff; reward it beyond the generic lookahead bonus.
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0;
    }

    // Residual-value discount for large leftovers consumed by small
    // items — placing a tiny item into a big pocket destroys future
    // packing potential; scale the tax with the destroyed fraction.
    if post_residual > 0 && item_size > 0 && bin_residual > item_size {
        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Dead-space budget coupling — when the mean residual across open bins
    // is already high, leaving yet another mid-range leftover compounds
    // waste; tax placements whose post_residual both exceeds the mean and
    // sits in the hard-to-fill 10..=29 band.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Near-perfect-fit gradient sharpening — among competing bins, a
    // post_residual of exactly 1..=2 is nearly a perfect fill; reward it
    // beyond the flat tier so the tightest bin wins decisively.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    // Dual-lookahead consolidation — when the current item and the
    // next-item pair leave a residual within a small-filler band of
    // zero, prefer this bin strongly.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // Waste-gap interpolation — among competing bins, prefer the bin
    // whose post_residual sits on a reusable band boundary (multiple of
    // 10), taxing residuals stranded mid-band between classes.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual < 60 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 14.0;
        } else if m >= 7 {
            score += 6.0 + (m - 7) as f64 * 3.0;
        }
    }

    // Triple-chain consolidation — when the current item plus the
    // next item leaves a residual exactly tileable by a third plausible
    // chunk (next_item_size again or a class multiple), this bin is a
    // full three-item plan; reward it decisively.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 0 && (after_pair == next_item_size || after_pair % 10 == 0) {
            score -= 46.0;
        }
    }

    // Combined fine-grained residual + lookahead: when many bins fit and
    // this placement leaves a residual that both is small in absolute
    // terms AND can absorb the next item, consolidate decisively here.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Class-aware dead-zone tax — a leftover whose size sits strictly
    // between the next item's class boundary and the next class floor is
    // unlikely to be filled by anything arriving soon; tax it in proportion
    // to how far it overshoots the next item, but only when alternatives
    // exist (multiple fitting bins), so unique fits stay untouched.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting — in the final third of the
    // stream, prefer placements that leave a residual exactly reusable by
    // the next item even at the cost of a slightly larger current fit;
    // chains of exact handoffs eliminate trailing waste bins.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation — when many bins are open,
    // the tightest fit matters more because each leftover fragment is
    // another bin that may never close; sharpen the tight-fit gradient
    // with open_bins_count so crowded states converge to best-fit harder.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket — a post_residual that falls
    // within [next_item_size, next_item_size + 3] is a guaranteed reuse
    // for the immediate successor; reward it progressively beyond the
    // generic slack bonus, strongest when few bins fit (scarce space).
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain — in the final 20% of the stream,
    // small items (<= 12) should preferentially drain the bin with the
    // SMALLEST residual they can fit, preserving large pockets for the
    // remaining medium/large items; tax placements into big pockets.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — if this placement closes the bin exactly
    // AND the next item also fits the residual after being added (i.e. a
    // two-item exact close), reward decisively regardless of bin count.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // NEW (gen 15): mid-band tileability sweep — a post_residual in the
    // 20..=60 range that is an exact multiple of the next item's size
    // will be fully consumed by successors; reward beyond the generic
    // divisibility bonus, scaled by how many next-items it absorbs.
    if next_item_size > 0 && post_residual >= 20 && post_residual <= 60 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 14.0 + 8.0 * k.min(4) as f64;
        }
    }

    // NEW (gen 15): crowding-aware best-fit escalation — when many bins
    // are open AND many fit, tighten the effective waste tolerance: any
    // placement leaving more than ~12 units of slack is taxed harder so
    // the tightest bin wins under pressure, reducing fragment spread.
    if open_bins_count > 5 && fitting_bins_count > 2 && post_residual > 12 {
        score += (post_residual as f64 - 12.0) * 0.9;
    }

    // NEW (gen 15): next-item pocket preservation — when the next item
    // is medium/large (> 25) and this placement would strand a residual
    // in the narrow band just below it (unusable by the successor),
    // tax the placement so a bin that can also host the next item wins.
    if next_item_size > 25 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 12 {
            score += 10.0 + (12 - gap as i32) as f64 * 2.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 1250.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
            score -= 32.0;
        }
    }

    // Pair exactness — residual exactly equals current+next is a jackpot.
    if pair > 0 && bin_residual == pair {
        score -= 266.0;
    }

    // Multi-fill potential — how many additional items of next size could
    // still land in this bin after the current one. More = better consolidation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let multi = post_residual / next_item_size;
        if multi >= 2 {
            score -= 22.0 * (multi.min(4) as f64);
        }
    }

    // Reusability shaping: leftover between ~15% and ~45% of capacity is highly reusable.
    if post_residual > 0 {
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 30.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
    }

    // Exact-complement chain — post_residual can exactly absorb next item
    // plus another known-size chunk; near-perfect plan, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 68.0;
        }
    }

    // Avoid leaving residuals just below the next item size (dead pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax — residuals too small for most item classes
    // (1..=9) are almost guaranteed waste; scale penalty with depth.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
    }

    // Harmonic-fit bonus — post_residual matching common complements of
    // typical item sizes (multiples of 25 or 50) stays fillable.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0) {
        score -= 35.0;
    }

    // Mid-band residual shaping — reward exactly-fillable remainders,
    // punish near-miss remainders just above the next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
    }

    // Fit-quality gradient among competing bins — push selection toward
    // the bin whose placement leaves the smallest post_residual relative
    // to the item's own class.
    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 58.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Three-item chain check — current + next + a small filler (1..=10)
    // exactly fills this bin's residual; an exceptionally strong plan.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let chain = bin_residual - item_size - next_item_size;
        if chain >= 1 && chain <= 10 {
            score -= 88.0;
        }
    }

    // Two-step exactness — after placing the current item, check whether
    // post_residual can absorb next_item_size AND a mid-class filler exactly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 15 && after_next <= 45 && after_next % 5 == 0 {
            score -= 36.0;
        }
        if after_next > 0 && after_next < 10 {
            score += 26.0;
        }
    }

    // Residual-fragmentation tax — when many open bins exist, leaving a
    // mid-sized residual (fragment) spreads waste across bins; consolidate.
    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        // When open bins exist but every fit is poor (large item, tiny residuals),
        // opening fresh is cheaper than shattering a usable residual.
        if fitting_bins_count > 0 && item_size > bin_capacity / 3 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 45.0 * (1.0 - progress);
            }
        }
        // Protect big pockets late in the stream.
        if fitting_bins_count > 0 && progress > 0.4 && item_size <= bin_capacity / 3 {
            if mean_residual < item_size as f64 * 1.5 {
                score -= 27.0 * progress;
            }
        }
        // If the next item is large and no open bin could hold it after
        // this placement, opening a fresh bin now preserves flexibility.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            if post_residual < next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin discipline — opening a new bin late wastes
        // capacity unless the item is big; penalize small-item new bins late.
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Mid-stream fresh-bin restraint — between 25% and 60% progress,
        // small items should almost never open fresh bins while any fit exists.
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        // Endgame fresh-bin economy — in the final 15% of the stream,
        // opening a fresh bin for a small item is almost pure waste.
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        // Pair-fit gate — if this fresh bin can absorb BOTH the current
        // and the next item exactly, opening it is a genuine plan, not waste.
        if pair > 0 && bin_residual >= pair {
            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
                score -= 98.0;
            }
        }
        // Dead-pocket escape — when the best available fit would leave a
        // residual too small for any plausible item (<= 9), a fresh bin
        // with a full residual is strictly better than shattering the pocket.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 9 {
            score -= 90.0 * (1.0 - progress).max(0.2);
        }
        // Next-item dead-pocket escape — if the current fit would leave a
        // residual just below next_item_size (unusable by the immediate
        // successor), a fresh bin preserves that space for the successor.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score -= 62.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin exact-pair plan — opening a bin whose capacity is
        // exactly current + next (or within 2) is a perfect two-item plan.
        if next_item_size > 0 {
            let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
            if diff >= 0 && diff <= 2 {
                score -= 112.0;
            }
        }
        // Oversized-item fresh-bin sharpening — items above 60% of capacity
        // almost never share a bin; when any open bin would be shattered to
        // a near-dead pocket (< 15 left), prefer the fresh bin aggressively.
        if fitting_bins_count > 0 && item_size * 5 > bin_capacity * 3 {
            if post_residual > 0 && post_residual < 15 {
                score -= 52.0;
            }
        }
        // Fresh-bin tileability — if the fresh bin's capacity can be
        // tiled by the next item repeated k>=2 times after this placement,
        // opening it now is a multi-item consolidation plan.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let after = bin_capacity - item_size;
            if after % next_item_size == 0 && after / next_item_size >= 2 {
                score -= 44.0;
            }
        }
        // Fresh-bin fragment-consolidation — when open bins hold many
        // small scattered fragments (low mean residual, many bins), opening
        // one fresh bin for a large item keeps those fragments intact for
        // the many small items that follow, instead of burning the single
        // large pocket that remains.
        if fitting_bins_count > 0 && open_bins_count > 3 && item_size > bin_capacity / 2 {
            if mean_residual < item_size as f64 * 1.2 {
                score -= 40.0 * (1.0 - progress).max(0.25);
            }
        }
        // Fresh-bin mid-fit gate — when an open-bin fit would leave a
        // residual in the awkward 30..=45 band (too big to die, too small
        // to tile reliably) while the fresh bin can hold current+next with
        // slack <= 10, prefer the fresh bin as a deliberate two-item plan.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= 30 && post_residual <= 45 {
            let fresh_slack = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_slack <= 10 {
                score -= 58.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin triple-tile plan — if the fresh bin can hold the
        // current item plus the next item twice with <= 5 slack, opening it
        // is a three-item consolidation that eliminates a whole future bin.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let t3 = bin_capacity - (item_size + 2 * next_item_size);
            if t3 <= 5 {
                score -= 74.0 * (1.0 - progress).max(0.4);
            }
        }
        score += 30.0 + 40.0 * progress;
    }

    // Waste-floor shaping for regular placements — when several bins fit,
    // a placement leaving a residual of 10..=19 is a near-dead pocket for
    // most distributions; tax it progressively (sharpened slope).
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 19 {
        score += 24.0 + (19 - post_residual as i32) as f64 * 4.0;
    }

    // Sub-next dead-band sharpening — when multiple bins fit, a placement
    // whose residual sits within 8 units below next_item_size is unusable
    // by the immediate successor; tax proportionally to closeness.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 8 {
            score += 14.0 + (8 - gap as i32) as f64 * 4.0;
        }
    }

    // Congestion: many open bins -> favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals from being consumed by small items late in stream.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Late-stream exactness boost — perfect/near-perfect fits matter more
    // when few items remain.
    let remaining_frac = 1.0 - progress;
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Divisibility-aware waste penalty — leftover that no multiple of any
    // plausible item class fills is taxed mildly.
    if post_residual > 0 && post_residual < bin_capacity {
        let cls = (post_residual / 10).max(1);
        if post_residual % (cls * 10) != 0 && post_residual < 50 {
            score += 11.0;
        }
    }

    // Exact-fill lookahead sweep — reward placements where the residual
    // after this item can be tiled exactly by the next item repeated k
    // times (k >= 1) with zero leftover.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // Post-residual reusability vs. mean coupling — a leftover close to
    // the stream's mean residual is statistically most likely to be reused
    // later; reward closeness, punish outliers among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 22.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
    }

    // Dead-zone gradient refinement — residuals in the 20..=34 band are
    // only fillable by mid-class items; when the next item is small
    // (<= 10), such residuals are likely to survive untapped.
    if post_residual >= 20 && post_residual <= 34 && next_item_size > 0 && next_item_size <= 10 {
        score += 16.0;
    }

    // Two-bin exact-split plan — when exactly two bins fit and this
    // placement leaves a residual that exactly equals next_item_size, it
    // is a perfect handoff; reward it beyond the generic lookahead bonus.
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0;
    }

    // Residual-value discount for large leftovers consumed by small
    // items — placing a tiny item into a big pocket destroys future
    // packing potential; scale the tax with the destroyed fraction.
    if post_residual > 0 && item_size > 0 && bin_residual > item_size {
        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Dead-space budget coupling — when the mean residual across open bins
    // is already high, leaving yet another mid-range leftover compounds
    // waste; tax placements whose post_residual both exceeds the mean and
    // sits in the hard-to-fill 10..=29 band.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Near-perfect-fit gradient sharpening — among competing bins, a
    // post_residual of exactly 1..=2 is nearly a perfect fill; reward it
    // beyond the flat tier so the tightest bin wins decisively.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    // Dual-lookahead consolidation — when the current item and the
    // next-item pair leave a residual within a small-filler band of
    // zero, prefer this bin strongly.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // Waste-gap interpolation — among competing bins, prefer the bin
    // whose post_residual sits on a reusable band boundary (multiple of
    // 10), taxing residuals stranded mid-band between classes.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual < 60 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 14.0;
        } else if m >= 7 {
            score += 6.0 + (m - 7) as f64 * 3.0;
        }
    }

    // Triple-chain consolidation — when the current item plus the
    // next item leaves a residual exactly tileable by a third plausible
    // chunk (next_item_size again or a class multiple), this bin is a
    // full three-item plan; reward it decisively.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 0 && (after_pair == next_item_size || after_pair % 10 == 0) {
            score -= 46.0;
        }
    }

    // Combined fine-grained residual + lookahead: when many bins fit and
    // this placement leaves a residual that both is small in absolute
    // terms AND can absorb the next item, consolidate decisively here.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Class-aware dead-zone tax — a leftover whose size sits strictly
    // between the next item's class boundary and the next class floor is
    // unlikely to be filled by anything arriving soon; tax it in proportion
    // to how far it overshoots the next item, but only when alternatives
    // exist (multiple fitting bins), so unique fits stay untouched.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting — in the final third of the
    // stream, prefer placements that leave a residual exactly reusable by
    // the next item even at the cost of a slightly larger current fit;
    // chains of exact handoffs eliminate trailing waste bins.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation — when many bins are open,
    // the tightest fit matters more because each leftover fragment is
    // another bin that may never close; sharpen the tight-fit gradient
    // with open_bins_count so crowded states converge to best-fit harder.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket — a post_residual that falls
    // within [next_item_size, next_item_size + 3] is a guaranteed reuse
    // for the immediate successor; reward it progressively beyond the
    // generic slack bonus, strongest when few bins fit (scarce space).
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain — in the final 20% of the stream,
    // small items (<= 12) should preferentially drain the bin with the
    // SMALLEST residual they can fit, preserving large pockets for the
    // remaining medium/large items; tax placements into big pockets.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — if this placement closes the bin exactly
    // AND the next item also fits the residual after being added (i.e. a
    // two-item exact close), reward decisively regardless of bin count.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // NEW: Global waste gradient — a continuous quadratic tax on any
    // nonzero post_residual, scaled by how many competing bins exist.
    // This replaces the flat tier structure with a smooth pressure toward
    // minimal dead space across the whole residual range, complementing
    // the tier bonuses instead of duplicating them.
    if post_residual > 0 && fitting_bins_count > 0 {
        let pr = post_residual as f64;
        let pressure = 1.0 + (open_bins_count as f64).min(12.0) * 0.08;
        score += 0.018 * pr * pr * pressure;
    }

    // NEW: Fresh-bin parity guard — when a fresh bin is being considered
    // against existing fits, tax it by the fraction of capacity that would
    // sit idle after the current item unless the next item can immediately
    // reuse most of it. This directly targets the diagnosed dead-space
    // weakness by making new bins pay for their idle volume up front.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let idle = post_residual.saturating_sub(next_item_size) as f64;
        let idle_frac = idle / bin_capacity as f64;
        if idle_frac > 0.25 {
            score += 55.0 * idle_frac * (1.0 - progress).max(0.3);
        }
    }

    // NEW: Chain-completion discount — when the current item, the next
    // item, and one more copy of the next item together exactly fill this
    // bin (zero slack), this is a perfect three-item closure; reward it
    // beyond the generic tileability bonuses which only approximate it.
    if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
        let t3 = bin_capacity - (item_size + 2 * next_item_size);
        if t3 == 0 {
            score -= 120.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (sharpened top tiers).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 380.0;
    } else if post_residual <= 5 {
        score -= 330.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Dead-space penalty: smooth, magnitude-aware version.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            let unfillable = (next_item_size - post_residual) as f64;
            score += 40.0 + unfillable * 3.0;
        }
        if post_residual < 10 {
            score += 110.0 + 18.0 * (10 - post_residual as i32) as f64;
        }
        // Reusability shaping: mid-range leftovers are highly reusable.
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 28.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
        // Harmonic-fit bonus: multiples of 25/50 stay fillable.
        if post_residual % 25 == 0 {
            score -= 35.0;
        }
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 580.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 200.0;
            } else if slack <= 10 {
                score -= 180.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
            // Multi-fill potential: how many copies of next item still fit.
            let multi = post_residual / next_item_size;
            if multi >= 2 {
                score -= 22.0 * (multi.min(4) as f64);
            }
            // Exact divisibility: residual is a clean multiple of next size.
            if post_residual % next_item_size == 0 {
                score -= 60.0;
            }
            // Near-exact handoff: overshoot of 1..=2 is almost a perfect plan.
            if slack <= 2 {
                score -= 40.0;
            } else if slack <= 9 {
                score += 55.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.2;
            // Near-miss pocket (gap <= 6) is a likely dead pocket.
            let gap = next_item_size - post_residual;
            if gap <= 6 {
                score += 48.0;
            }
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 25.0;
        }
    }

    // Triple lookahead: pocket for the item after next.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 48.0;
        }
        if after_next >= 15 && after_next <= 45 && after_next % 5 == 0 {
            score -= 34.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 440.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 58.0;

    // Two-item lookahead with pair exactness jackpot.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack == 0 {
            score -= 262.0;
        } else if pair_slack <= 8 {
            score -= 100.0;
        } else {
            score -= 30.0;
        }
    }

    // Chain-fit bonus: residual can host item + next + small filler.
    if next_item_size > 0 && bin_residual >= pair {
        let rest = bin_residual - pair;
        if rest >= 1 && rest <= 10 {
            score -= 85.0;
        } else if rest > 10 && rest <= 25 {
            score -= 30.0;
        } else if rest > 0 && (rest == next_item_size || rest % 10 == 0) {
            score -= 46.0;
        }
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let remaining_frac = 1.0 - progress;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        if fitting_bins_count > 0 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 45.0 * (1.0 - progress);
            }
            if item_size > bin_capacity / 3 && progress > 0.6 && mean_residual > (item_size as f64) + 15.0 {
                score -= 55.0 * (1.0 - progress);
            }
            // Dead-pocket escape: best fit would leave <= 9 unusable.
            if post_residual > 0 && post_residual <= 9 {
                score -= 90.0 * (1.0 - progress).max(0.2);
            }
            // Next-item dead-pocket escape.
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
                let gap = next_item_size - post_residual;
                if gap <= 8 {
                    score -= 62.0 * (1.0 - progress).max(0.3);
                }
            }
            // Fragment consolidation: keep scattered fragments intact.
            if open_bins_count > 3 && item_size > bin_capacity / 2 && mean_residual < item_size as f64 * 1.2 {
                score -= 40.0 * (1.0 - progress).max(0.25);
            }
        }
        // Preserve flexibility: large next item wouldn't fit after this placement.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 && post_residual < next_item_size {
            score -= 34.0 * (1.0 - progress);
        }
        // Fresh-bin exact-pair plan: capacity fits current+next tightly.
        if next_item_size > 0 {
            let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
            if diff >= 0 && diff <= 2 {
                score -= 110.0;
            }
        }
        // Fresh-bin tileability: capacity tiles by next item after placement.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let after = bin_capacity - item_size;
            if after % next_item_size == 0 && after / next_item_size >= 2 {
                score -= 46.0;
            }
        }
        // Late-stream fresh-bin discipline.
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        score += 30.0 + 40.0 * progress;
    }

    // Congestion: many open bins -> favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals from being consumed by small items late in stream.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Residual fragmentation guard: tiny slivers accumulate as dead space.
    if post_residual > 0 && post_residual < 6 && progress > 0.3 {
        score += 45.0;
    }

    // Late-stream exactness boost: near-perfect fits matter more late.
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Waste-floor shaping for regular placements — near-dead 10..=19 pockets.
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 19 {
        score += 24.0 + (19 - post_residual as i32) as f64 * 4.0;
    }

    // Sub-next dead-band sharpening when multiple bins fit.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 8 {
            score += 14.0 + (8 - gap as i32) as f64 * 4.0;
        }
    }

    // Fit-quality gradient among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 55.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Fragment-count-aware consolidation: sharpen tight-fit gradient when crowded.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket: guaranteed reuse for the successor.
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Combined fine-grained residual + lookahead consolidation.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Late-stream small-item drain: preserve large pockets for medium/large items.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Late-stream exact handoff chains.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Two-bin exact-split plan: perfect handoff with exactly two candidates.
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0;
    }

    // Residual-value discount: tiny items consuming big pockets destroy potential.
    if post_residual > 0 && item_size > 0 && bin_residual > item_size {
        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Near-perfect-fit gradient: post_residual of 1..=2 wins decisively.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
            score -= 32.0;
        }
    }

    // Pair exactness — residual exactly equals current+next is a jackpot.
    if pair > 0 && bin_residual == pair {
        score -= 266.0;
    }

    // Multi-fill potential — how many additional items of next size could
    // still land in this bin after the current one. More = better consolidation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let multi = post_residual / next_item_size;
        if multi >= 2 {
            score -= 22.0 * (multi.min(4) as f64);
        }
    }

    // Reusability shaping: leftover between ~15% and ~45% of capacity is highly reusable.
    if post_residual > 0 {
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 30.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
    }

    // Exact-complement chain — post_residual can exactly absorb next item
    // plus another known-size chunk; near-perfect plan, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 68.0;
        }
    }

    // Avoid leaving residuals just below the next item size (dead pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax — residuals too small for most item classes
    // (1..=9) are almost guaranteed waste; scale penalty with depth.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
    }

    // Harmonic-fit bonus — post_residual matching common complements of
    // typical item sizes (multiples of 25 or 50) stays fillable.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0) {
        score -= 35.0;
    }

    // Mid-band residual shaping — reward exactly-fillable remainders,
    // punish near-miss remainders just above the next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
    }

    // Fit-quality gradient among competing bins — push selection toward
    // the bin whose placement leaves the smallest post_residual relative
    // to the item's own class.
    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 58.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Three-item chain check — current + next + a small filler (1..=10)
    // exactly fills this bin's residual; an exceptionally strong plan.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let chain = bin_residual - item_size - next_item_size;
        if chain >= 1 && chain <= 10 {
            score -= 88.0;
        }
    }

    // Two-step exactness — after placing the current item, check whether
    // post_residual can absorb next_item_size AND a mid-class filler exactly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 15 && after_next <= 45 && after_next % 5 == 0 {
            score -= 36.0;
        }
        if after_next > 0 && after_next < 10 {
            score += 26.0;
        }
    }

    // Residual-fragmentation tax — when many open bins exist, leaving a
    // mid-sized residual (fragment) spreads waste across bins; consolidate.
    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        // When open bins exist but every fit is poor (large item, tiny residuals),
        // opening fresh is cheaper than shattering a usable residual.
        if fitting_bins_count > 0 && item_size > bin_capacity / 3 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 45.0 * (1.0 - progress);
            }
        }
        // Protect big pockets late in the stream.
        if fitting_bins_count > 0 && progress > 0.4 && item_size <= bin_capacity / 3 {
            if mean_residual < item_size as f64 * 1.5 {
                score -= 27.0 * progress;
            }
        }
        // If the next item is large and no open bin could hold it after
        // this placement, opening a fresh bin now preserves flexibility.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            if post_residual < next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin discipline — opening a new bin late wastes
        // capacity unless the item is big; penalize small-item new bins late.
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Mid-stream fresh-bin restraint — between 25% and 60% progress,
        // small items should almost never open fresh bins while any fit exists.
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        // Endgame fresh-bin economy — in the final 15% of the stream,
        // opening a fresh bin for a small item is almost pure waste.
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        // Pair-fit gate — if this fresh bin can absorb BOTH the current
        // and the next item exactly, opening it is a genuine plan, not waste.
        if pair > 0 && bin_residual >= pair {
            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
                score -= 98.0;
            }
        }
        // Dead-pocket escape — when the best available fit would leave a
        // residual too small for any plausible item (<= 9), a fresh bin
        // with a full residual is strictly better than shattering the pocket.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 9 {
            score -= 90.0 * (1.0 - progress).max(0.2);
        }
        // Next-item dead-pocket escape — if the current fit would leave a
        // residual just below next_item_size (unusable by the immediate
        // successor), a fresh bin preserves that space for the successor.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score -= 62.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin exact-pair plan — opening a bin whose capacity is
        // exactly current + next (or within 2) is a perfect two-item plan.
        if next_item_size > 0 {
            let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
            if diff >= 0 && diff <= 2 {
                score -= 112.0;
            }
        }
        // Oversized-item fresh-bin sharpening — items above 60% of capacity
        // almost never share a bin; when any open bin would be shattered to
        // a near-dead pocket (< 15 left), prefer the fresh bin aggressively.
        if fitting_bins_count > 0 && item_size * 5 > bin_capacity * 3 {
            if post_residual > 0 && post_residual < 15 {
                score -= 52.0;
            }
        }
        // Fresh-bin tileability — if the fresh bin's capacity can be
        // tiled by the next item repeated k>=2 times after this placement,
        // opening it now is a multi-item consolidation plan.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let after = bin_capacity - item_size;
            if after % next_item_size == 0 && after / next_item_size >= 2 {
                score -= 44.0;
            }
        }
        // Fresh-bin fragment-consolidation — when open bins hold many
        // small scattered fragments (low mean residual, many bins), opening
        // one fresh bin for a large item keeps those fragments intact for
        // the many small items that follow, instead of burning the single
        // large pocket that remains.
        if fitting_bins_count > 0 && open_bins_count > 3 && item_size > bin_capacity / 2 {
            if mean_residual < item_size as f64 * 1.2 {
                score -= 40.0 * (1.0 - progress).max(0.25);
            }
        }
        // Fresh-bin mid-fit gate — when an open-bin fit would leave a
        // residual in the awkward 30..=45 band (too big to die, too small
        // to tile reliably) while the fresh bin can hold current+next with
        // slack <= 10, prefer the fresh bin as a deliberate two-item plan.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= 30 && post_residual <= 45 {
            let fresh_slack = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_slack <= 10 {
                score -= 58.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin triple-tile plan — if the fresh bin can hold the
        // current item plus the next item twice with <= 5 slack, opening it
        // is a three-item consolidation that eliminates a whole future bin.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let t3 = bin_capacity - (item_size + 2 * next_item_size);
            if t3 <= 5 {
                score -= 74.0 * (1.0 - progress).max(0.4);
            }
        }
        // NEW: Fresh-bin mean-fit escape — when the average open-bin slack
        // is far below what this item needs (mean_residual < item), every
        // available fit is doomed to shatter; a fresh bin is cheaper than
        // destroying the least-bad pocket. Scaled by stream position.
        if fitting_bins_count > 0 && (mean_residual + 6.0) < item_size as f64 {
            score -= 66.0 * (1.0 - progress).max(0.2);
        }
        score += 30.0 + 40.0 * progress;
    }

    // Waste-floor shaping for regular placements — when several bins fit,
    // a placement leaving a residual of 10..=19 is a near-dead pocket for
    // most distributions; tax it progressively (sharpened slope).
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 19 {
        score += 24.0 + (19 - post_residual as i32) as f64 * 4.0;
    }

    // Sub-next dead-band sharpening — when multiple bins fit, a placement
    // whose residual sits within 8 units below next_item_size is unusable
    // by the immediate successor; tax proportionally to closeness.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 8 {
            score += 14.0 + (8 - gap as i32) as f64 * 4.0;
        }
    }

    // Congestion: many open bins -> favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals from being consumed by small items late in stream.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Late-stream exactness boost — perfect/near-perfect fits matter more
    // when few items remain.
    let remaining_frac = 1.0 - progress;
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Divisibility-aware waste penalty — leftover that no multiple of any
    // plausible item class fills is taxed mildly.
    if post_residual > 0 && post_residual < bin_capacity {
        let cls = (post_residual / 10).max(1);
        if post_residual % (cls * 10) != 0 && post_residual < 50 {
            score += 11.0;
        }
    }

    // Exact-fill lookahead sweep — reward placements where the residual
    // after this item can be tiled exactly by the next item repeated k
    // times (k >= 1) with zero leftover.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // Post-residual reusability vs. mean coupling — a leftover close to
    // the stream's mean residual is statistically most likely to be reused
    // later; reward closeness, punish outliers among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 22.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
    }

    // Dead-zone gradient refinement — residuals in the 20..=34 band are
    // only fillable by mid-class items; when the next item is small
    // (<= 10), such residuals are likely to survive untapped.
    if post_residual >= 20 && post_residual <= 34 && next_item_size > 0 && next_item_size <= 10 {
        score += 16.0;
    }

    // Two-bin exact-split plan — when exactly two bins fit and this
    // placement leaves a residual that exactly equals next_item_size, it
    // is a perfect handoff; reward it beyond the generic lookahead bonus.
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0;
    }

    // Residual-value discount for large leftovers consumed by small
    // items — placing a tiny item into a big pocket destroys future
    // packing potential; scale the tax with the destroyed fraction.
    if post_residual > 0 && item_size > 0 && bin_residual > item_size {
        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Dead-space budget coupling — when the mean residual across open bins
    // is already high, leaving yet another mid-range leftover compounds
    // waste; tax placements whose post_residual both exceeds the mean and
    // sits in the hard-to-fill 10..=29 band.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Near-perfect-fit gradient sharpening — among competing bins, a
    // post_residual of exactly 1..=2 is nearly a perfect fill; reward it
    // beyond the flat tier so the tightest bin wins decisively.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    // Dual-lookahead consolidation — when the current item and the
    // next-item pair leave a residual within a small-filler band of
    // zero, prefer this bin strongly.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // Waste-gap interpolation — among competing bins, prefer the bin
    // whose post_residual sits on a reusable band boundary (multiple of
    // 10), taxing residuals stranded mid-band between classes.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual < 60 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 14.0;
        } else if m >= 7 {
            score += 6.0 + (m - 7) as f64 * 3.0;
        }
    }

    // Triple-chain consolidation — when the current item plus the
    // next item leaves a residual exactly tileable by a third plausible
    // chunk (next_item_size again or a class multiple), this bin is a
    // full three-item plan; reward it decisively.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 0 && (after_pair == next_item_size || after_pair % 10 == 0) {
            score -= 46.0;
        }
    }

    // Combined fine-grained residual + lookahead: when many bins fit and
    // this placement leaves a residual that both is small in absolute
    // terms AND can absorb the next item, consolidate decisively here.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Class-aware dead-zone tax — a leftover whose size sits strictly
    // between the next item's class boundary and the next class floor is
    // unlikely to be filled by anything arriving soon; tax it in proportion
    // to how far it overshoots the next item, but only when alternatives
    // exist (multiple fitting bins), so unique fits stay untouched.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting — in the final third of the
    // stream, prefer placements that leave a residual exactly reusable by
    // the next item even at the cost of a slightly larger current fit;
    // chains of exact handoffs eliminate trailing waste bins.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation — when many bins are open,
    // the tightest fit matters more because each leftover fragment is
    // another bin that may never close; sharpen the tight-fit gradient
    // with open_bins_count so crowded states converge to best-fit harder.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket — a post_residual that falls
    // within [next_item_size, next_item_size + 3] is a guaranteed reuse
    // for the immediate successor; reward it progressively beyond the
    // generic slack bonus, strongest when few bins fit (scarce space).
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain — in the final 20% of the stream,
    // small items (<= 12) should preferentially drain the bin with the
    // SMALLEST residual they can fit, preserving large pockets for the
    // remaining medium/large items; tax placements into big pockets.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — if this placement closes the bin exactly
    // AND the next item also fits the residual after being added (i.e. a
    // two-item exact close), reward decisively regardless of bin count.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // NEW: Dead-space minimization gradient — among competing bins, the
    // single largest source of wasted bins is residual stranded in the
    // 6..=14 dead band; apply a smooth quadratic tax proportional to how
    // deep into the band the leftover lands, sharpening best-fit pressure
    // exactly where the parent leaks bins.
    if fitting_bins_count > 1 && post_residual >= 6 && post_residual <= 14 {
        let depth = 14 - post_residual as i32;
        score += 10.0 + (depth * depth) as f64 * 0.9;
    }

    // NEW: Reuse-window widening — a leftover that can hold the next item
    // plus a small filler (1..=6) is nearly as good as an exact handoff,
    // since small items dominate late tails; reward it when bins compete.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over >= 1 && over <= 6 {
            score -= 30.0 + (6 - over as i32) as f64 * 3.0;
        }
    }

    // NEW: Large-pocket conservation — when the item is small relative to
    // the pocket it consumes and the leftover exceeds the next item by a
    // wide margin, the placement is "borrowing" future space; tax it
    // progressively with the excess so mid-size items stop burning the
    // few remaining large pockets mid-stream.
    if progress > 0.35 && next_item_size > 0 && post_residual > next_item_size + 25 {
        let excess = post_residual - next_item_size - 25;
        score += (excess.min(30) as f64) * 0.8 * progress;
    }

    // NEW: Endgame exact-close priority — in the final quarter of the
    // stream, any placement that closes a bin exactly (post_residual == 0)
    // removes a bin from the open set entirely; reinforce beyond the flat
    // tier with a progress-scaled bonus.
    if post_residual == 0 && progress > 0.75 {
        score -= 90.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
            score -= 32.0;
        }
    }

    // Pair exactness — residual exactly equals current+next is a jackpot.
    if pair > 0 && bin_residual == pair {
        score -= 266.0;
    }

    // Multi-fill potential — how many additional items of next size could
    // still land in this bin after the current one. More = better consolidation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let multi = post_residual / next_item_size;
        if multi >= 2 {
            score -= 22.0 * (multi.min(4) as f64);
        }
    }

    // Reusability shaping: leftover between ~15% and ~45% of capacity is highly reusable.
    if post_residual > 0 {
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 30.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
    }

    // Exact-complement chain — post_residual can exactly absorb next item
    // plus another known-size chunk; near-perfect plan, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 68.0;
        }
    }

    // Avoid leaving residuals just below the next item size (dead pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax — residuals too small for most item classes
    // (1..=9) are almost guaranteed waste; scale penalty with depth.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
    }

    // Harmonic-fit bonus — post_residual matching common complements of
    // typical item sizes (multiples of 25 or 50) stays fillable.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0) {
        score -= 35.0;
    }

    // Mid-band residual shaping — reward exactly-fillable remainders,
    // punish near-miss remainders just above the next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
    }

    // Fit-quality gradient among competing bins — push selection toward
    // the bin whose placement leaves the smallest post_residual relative
    // to the item's own class.
    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 58.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Three-item chain check — current + next + a small filler (1..=10)
    // exactly fills this bin's residual; an exceptionally strong plan.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let chain = bin_residual - item_size - next_item_size;
        if chain >= 1 && chain <= 10 {
            score -= 88.0;
        }
    }

    // Two-step exactness — after placing the current item, check whether
    // post_residual can absorb next_item_size AND a mid-class filler exactly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 15 && after_next <= 45 && after_next % 5 == 0 {
            score -= 36.0;
        }
        if after_next > 0 && after_next < 10 {
            score += 26.0;
        }
    }

    // Residual-fragmentation tax — when many open bins exist, leaving a
    // mid-sized residual (fragment) spreads waste across bins; consolidate.
    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        // When open bins exist but every fit is poor (large item, tiny residuals),
        // opening fresh is cheaper than shattering a usable residual.
        if fitting_bins_count > 0 && item_size > bin_capacity / 3 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 45.0 * (1.0 - progress);
            }
        }
        // Protect big pockets late in the stream.
        if fitting_bins_count > 0 && progress > 0.4 && item_size <= bin_capacity / 3 {
            if mean_residual < item_size as f64 * 1.5 {
                score -= 27.0 * progress;
            }
        }
        // If the next item is large and no open bin could hold it after
        // this placement, opening a fresh bin now preserves flexibility.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            if post_residual < next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin discipline — opening a new bin late wastes
        // capacity unless the item is big; penalize small-item new bins late.
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Mid-stream fresh-bin restraint — between 25% and 60% progress,
        // small items should almost never open fresh bins while any fit exists.
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        // Endgame fresh-bin economy — in the final 15% of the stream,
        // opening a fresh bin for a small item is almost pure waste.
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        // Pair-fit gate — if this fresh bin can absorb BOTH the current
        // and the next item exactly, opening it is a genuine plan, not waste.
        if pair > 0 && bin_residual >= pair {
            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
                score -= 98.0;
            }
        }
        // Dead-pocket escape — when the best available fit would leave a
        // residual too small for any plausible item (<= 9), a fresh bin
        // with a full residual is strictly better than shattering the pocket.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 9 {
            score -= 90.0 * (1.0 - progress).max(0.2);
        }
        // Next-item dead-pocket escape — if the current fit would leave a
        // residual just below next_item_size (unusable by the immediate
        // successor), a fresh bin preserves that space for the successor.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score -= 62.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin exact-pair plan — opening a bin whose capacity is
        // exactly current + next (or within 2) is a perfect two-item plan.
        if next_item_size > 0 {
            let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
            if diff >= 0 && diff <= 2 {
                score -= 112.0;
            }
        }
        // Oversized-item fresh-bin sharpening — items above 60% of capacity
        // almost never share a bin; when any open bin would be shattered to
        // a near-dead pocket (< 15 left), prefer the fresh bin aggressively.
        if fitting_bins_count > 0 && item_size * 5 > bin_capacity * 3 {
            if post_residual > 0 && post_residual < 15 {
                score -= 52.0;
            }
        }
        // Fresh-bin tileability — if the fresh bin's capacity can be
        // tiled by the next item repeated k>=2 times after this placement,
        // opening it now is a multi-item consolidation plan.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let after = bin_capacity - item_size;
            if after % next_item_size == 0 && after / next_item_size >= 2 {
                score -= 44.0;
            }
        }
        // Fresh-bin fragment-consolidation — when open bins hold many
        // small scattered fragments (low mean residual, many bins), opening
        // one fresh bin for a large item keeps those fragments intact for
        // the many small items that follow, instead of burning the single
        // large pocket that remains.
        if fitting_bins_count > 0 && open_bins_count > 3 && item_size > bin_capacity / 2 {
            if mean_residual < item_size as f64 * 1.2 {
                score -= 40.0 * (1.0 - progress).max(0.25);
            }
        }
        // Fresh-bin mid-fit gate — when an open-bin fit would leave a
        // residual in the awkward 30..=45 band (too big to die, too small
        // to tile reliably) while the fresh bin can hold current+next with
        // slack <= 10, prefer the fresh bin as a deliberate two-item plan.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= 30 && post_residual <= 45 {
            let fresh_slack = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_slack <= 10 {
                score -= 58.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin triple-tile plan — if the fresh bin can hold the
        // current item plus the next item twice with <= 5 slack, opening it
        // is a three-item consolidation that eliminates a whole future bin.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let t3 = bin_capacity - (item_size + 2 * next_item_size);
            if t3 <= 5 {
                score -= 74.0 * (1.0 - progress).max(0.4);
            }
        }
        // NEW: Fresh-bin wide-pocket guard — when the item is small and the
        // mean residual across open bins is already generous (>= 2x item),
        // an open bin almost certainly absorbs it; opening fresh would
        // strand the existing pockets. Tax proportionally to slack.
        if fitting_bins_count > 0 && item_size <= bin_capacity / 4 && mean_residual > item_size as f64 * 2.0 {
            score += 30.0 * (mean_residual / (item_size as f64).max(1.0)).min(4.0);
        }
        score += 30.0 + 40.0 * progress;
    }

    // Waste-floor shaping for regular placements — when several bins fit,
    // a placement leaving a residual of 10..=19 is a near-dead pocket for
    // most distributions; tax it progressively (sharpened slope).
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 19 {
        score += 24.0 + (19 - post_residual as i32) as f64 * 4.0;
    }

    // Sub-next dead-band sharpening — when multiple bins fit, a placement
    // whose residual sits within 8 units below next_item_size is unusable
    // by the immediate successor; tax proportionally to closeness.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 8 {
            score += 14.0 + (8 - gap as i32) as f64 * 4.0;
        }
    }

    // Congestion: many open bins -> favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals from being consumed by small items late in stream.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Late-stream exactness boost — perfect/near-perfect fits matter more
    // when few items remain.
    let remaining_frac = 1.0 - progress;
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Divisibility-aware waste penalty — leftover that no multiple of any
    // plausible item class fills is taxed mildly.
    if post_residual > 0 && post_residual < bin_capacity {
        let cls = (post_residual / 10).max(1);
        if post_residual % (cls * 10) != 0 && post_residual < 50 {
            score += 11.0;
        }
    }

    // Exact-fill lookahead sweep — reward placements where the residual
    // after this item can be tiled exactly by the next item repeated k
    // times (k >= 1) with zero leftover.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // Post-residual reusability vs. mean coupling — a leftover close to
    // the stream's mean residual is statistically most likely to be reused
    // later; reward closeness, punish outliers among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 22.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
    }

    // Dead-zone gradient refinement — residuals in the 20..=34 band are
    // only fillable by mid-class items; when the next item is small
    // (<= 10), such residuals are likely to survive untapped.
    if post_residual >= 20 && post_residual <= 34 && next_item_size > 0 && next_item_size <= 10 {
        score += 16.0;
    }

    // Two-bin exact-split plan — when exactly two bins fit and this
    // placement leaves a residual that exactly equals next_item_size, it
    // is a perfect handoff; reward it beyond the generic lookahead bonus.
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0;
    }

    // Residual-value discount for large leftovers consumed by small
    // items — placing a tiny item into a big pocket destroys future
    // packing potential; scale the tax with the destroyed fraction.
    if post_residual > 0 && item_size > 0 && bin_residual > item_size {
        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Dead-space budget coupling — when the mean residual across open bins
    // is already high, leaving yet another mid-range leftover compounds
    // waste; tax placements whose post_residual both exceeds the mean and
    // sits in the hard-to-fill 10..=29 band.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Near-perfect-fit gradient sharpening — among competing bins, a
    // post_residual of exactly 1..=2 is nearly a perfect fill; reward it
    // beyond the flat tier so the tightest bin wins decisively.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    // Dual-lookahead consolidation — when the current item and the
    // next-item pair leave a residual within a small-filler band of
    // zero, prefer this bin strongly.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // Waste-gap interpolation — among competing bins, prefer the bin
    // whose post_residual sits on a reusable band boundary (multiple of
    // 10), taxing residuals stranded mid-band between classes.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual < 60 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 14.0;
        } else if m >= 7 {
            score += 6.0 + (m - 7) as f64 * 3.0;
        }
    }

    // Triple-chain consolidation — when the current item plus the
    // next item leaves a residual exactly tileable by a third plausible
    // chunk (next_item_size again or a class multiple), this bin is a
    // full three-item plan; reward it decisively.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 0 && (after_pair == next_item_size || after_pair % 10 == 0) {
            score -= 46.0;
        }
    }

    // Combined fine-grained residual + lookahead: when many bins fit and
    // this placement leaves a residual that both is small in absolute
    // terms AND can absorb the next item, consolidate decisively here.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Class-aware dead-zone tax — a leftover whose size sits strictly
    // between the next item's class boundary and the next class floor is
    // unlikely to be filled by anything arriving soon; tax it in proportion
    // to how far it overshoots the next item, but only when alternatives
    // exist (multiple fitting bins), so unique fits stay untouched.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting — in the final third of the
    // stream, prefer placements that leave a residual exactly reusable by
    // the next item even at the cost of a slightly larger current fit;
    // chains of exact handoffs eliminate trailing waste bins.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation — when many bins are open,
    // the tightest fit matters more because each leftover fragment is
    // another bin that may never close; sharpen the tight-fit gradient
    // with open_bins_count so crowded states converge to best-fit harder.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket — a post_residual that falls
    // within [next_item_size, next_item_size + 3] is a guaranteed reuse
    // for the immediate successor; reward it progressively beyond the
    // generic slack bonus, strongest when few bins fit (scarce space).
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain — in the final 20% of the stream,
    // small items (<= 12) should preferentially drain the bin with the
    // SMALLEST residual they can fit, preserving large pockets for the
    // remaining medium/large items; tax placements into big pockets.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — if this placement closes the bin exactly
    // AND the next item also fits the residual after being added (i.e. a
    // two-item exact close), reward decisively regardless of bin count.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // NEW: Dead-space minimization gradient — among competing bins, rank
    // placements by post_residual relative to the item size with a smooth
    // quadratic tax; this continuously pushes selection toward the fit
    // that leaves the least unusable space, beyond the tiered bonuses.
    if fitting_bins_count > 1 && post_residual > 0 {
        let r = post_residual as f64;
        score += 0.012 * r * r;
    }

    // NEW: Overshoot-decay reward — when the post_residual exceeds the
    // next item by more than the next item's own class width, the leftover
    // likely survives another step; reward placements whose post_residual
    // is within one class width (10) above a multiple of next_item_size,
    // since the next-next arrival can still tile it.
    if next_item_size >= 5 && post_residual > 0 && post_residual >= next_item_size {
        let over = post_residual % next_item_size;
        if over <= 4 {
            score -= 12.0;
        }
    }

    // NEW: Late-stage zero-waste escalation — in the last 30% of the
    // stream, every wasted unit is a bin that cannot be reclaimed; scale
    // the post-residual tax with remaining-item density so the heuristic
    // becomes strictly best-fit when the end approaches.
    if progress > 0.7 && post_residual > 0 {
        score += post_residual as f64 * 0.4 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
            score -= 32.0;
        }
    }

    // Pair exactness — residual exactly equals current+next is a jackpot.
    if pair > 0 && bin_residual == pair {
        score -= 266.0;
    }

    // Multi-fill potential — how many additional items of next size could
    // still land in this bin after the current one. More = better consolidation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let multi = post_residual / next_item_size;
        if multi >= 2 {
            score -= 22.0 * (multi.min(4) as f64);
        }
    }

    // Reusability shaping: leftover between ~15% and ~45% of capacity is highly reusable.
    if post_residual > 0 {
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 30.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
    }

    // Exact-complement chain — post_residual can exactly absorb next item
    // plus another known-size chunk; near-perfect plan, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 68.0;
        }
    }

    // Avoid leaving residuals just below the next item size (dead pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax — residuals too small for most item classes
    // (1..=9) are almost guaranteed waste; scale penalty with depth.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
    }

    // Harmonic-fit bonus — post_residual matching common complements of
    // typical item sizes (multiples of 25 or 50) stays fillable.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0) {
        score -= 35.0;
    }

    // Mid-band residual shaping — reward exactly-fillable remainders,
    // punish near-miss remainders just above the next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
    }

    // Fit-quality gradient among competing bins — push selection toward
    // the bin whose placement leaves the smallest post_residual relative
    // to the item's own class.
    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 58.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Three-item chain check — current + next + a small filler (1..=10)
    // exactly fills this bin's residual; an exceptionally strong plan.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let chain = bin_residual - item_size - next_item_size;
        if chain >= 1 && chain <= 10 {
            score -= 88.0;
        }
    }

    // Two-step exactness — after placing the current item, check whether
    // post_residual can absorb next_item_size AND a mid-class filler exactly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 15 && after_next <= 45 && after_next % 5 == 0 {
            score -= 36.0;
        }
        if after_next > 0 && after_next < 10 {
            score += 26.0;
        }
    }

    // Residual-fragmentation tax — when many open bins exist, leaving a
    // mid-sized residual (fragment) spreads waste across bins; consolidate.
    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        // When open bins exist but every fit is poor (large item, tiny residuals),
        // opening fresh is cheaper than shattering a usable residual.
        if fitting_bins_count > 0 && item_size > bin_capacity / 3 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 45.0 * (1.0 - progress);
            }
        }
        // Protect big pockets late in the stream.
        if fitting_bins_count > 0 && progress > 0.4 && item_size <= bin_capacity / 3 {
            if mean_residual < item_size as f64 * 1.5 {
                score -= 27.0 * progress;
            }
        }
        // If the next item is large and no open bin could hold it after
        // this placement, opening a fresh bin now preserves flexibility.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            if post_residual < next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin discipline — opening a new bin late wastes
        // capacity unless the item is big; penalize small-item new bins late.
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Mid-stream fresh-bin restraint — between 25% and 60% progress,
        // small items should almost never open fresh bins while any fit exists.
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        // Endgame fresh-bin economy — in the final 15% of the stream,
        // opening a fresh bin for a small item is almost pure waste.
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        // Pair-fit gate — if this fresh bin can absorb BOTH the current
        // and the next item exactly, opening it is a genuine plan, not waste.
        if pair > 0 && bin_residual >= pair {
            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
                score -= 98.0;
            }
        }
        // Dead-pocket escape — when the best available fit would leave a
        // residual too small for any plausible item (<= 9), a fresh bin
        // with a full residual is strictly better than shattering the pocket.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 9 {
            score -= 90.0 * (1.0 - progress).max(0.2);
        }
        // Next-item dead-pocket escape — if the current fit would leave a
        // residual just below next_item_size (unusable by the immediate
        // successor), a fresh bin preserves that space for the successor.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score -= 62.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin exact-pair plan — opening a bin whose capacity is
        // exactly current + next (or within 2) is a perfect two-item plan.
        if next_item_size > 0 {
            let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
            if diff >= 0 && diff <= 2 {
                score -= 112.0;
            }
        }
        // Oversized-item fresh-bin sharpening — items above 60% of capacity
        // almost never share a bin; when any open bin would be shattered to
        // a near-dead pocket (< 15 left), prefer the fresh bin aggressively.
        if fitting_bins_count > 0 && item_size * 5 > bin_capacity * 3 {
            if post_residual > 0 && post_residual < 15 {
                score -= 52.0;
            }
        }
        // Fresh-bin tileability — if the fresh bin's capacity can be
        // tiled by the next item repeated k>=2 times after this placement,
        // opening it now is a multi-item consolidation plan.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let after = bin_capacity - item_size;
            if after % next_item_size == 0 && after / next_item_size >= 2 {
                score -= 44.0;
            }
        }
        // Fresh-bin fragment-consolidation — when open bins hold many
        // small scattered fragments (low mean residual, many bins), opening
        // one fresh bin for a large item keeps those fragments intact for
        // the many small items that follow, instead of burning the single
        // large pocket that remains.
        if fitting_bins_count > 0 && open_bins_count > 3 && item_size > bin_capacity / 2 {
            if mean_residual < item_size as f64 * 1.2 {
                score -= 40.0 * (1.0 - progress).max(0.25);
            }
        }
        // Fresh-bin mid-fit gate — when an open-bin fit would leave a
        // residual in the awkward 30..=45 band (too big to die, too small
        // to tile reliably) while the fresh bin can hold current+next with
        // slack <= 10, prefer the fresh bin as a deliberate two-item plan.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= 30 && post_residual <= 45 {
            let fresh_slack = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_slack <= 10 {
                score -= 58.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin triple-tile plan — if the fresh bin can hold the
        // current item plus the next item twice with <= 5 slack, opening it
        // is a three-item consolidation that eliminates a whole future bin.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let t3 = bin_capacity - (item_size + 2 * next_item_size);
            if t3 <= 5 {
                score -= 74.0 * (1.0 - progress).max(0.4);
            }
        }
        score += 30.0 + 40.0 * progress;
    }

    // Waste-floor shaping for regular placements — when several bins fit,
    // a placement leaving a residual of 10..=19 is a near-dead pocket for
    // most distributions; tax it progressively (sharpened slope).
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 19 {
        score += 24.0 + (19 - post_residual as i32) as f64 * 4.0;
    }

    // Sub-next dead-band sharpening — when multiple bins fit, a placement
    // whose residual sits within 8 units below next_item_size is unusable
    // by the immediate successor; tax proportionally to closeness.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 8 {
            score += 14.0 + (8 - gap as i32) as f64 * 4.0;
        }
    }

    // Congestion: many open bins -> favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals from being consumed by small items late in stream.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Late-stream exactness boost — perfect/near-perfect fits matter more
    // when few items remain.
    let remaining_frac = 1.0 - progress;
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Divisibility-aware waste penalty — leftover that no multiple of any
    // plausible item class fills is taxed mildly.
    if post_residual > 0 && post_residual < bin_capacity {
        let cls = (post_residual / 10).max(1);
        if post_residual % (cls * 10) != 0 && post_residual < 50 {
            score += 11.0;
        }
    }

    // Exact-fill lookahead sweep — reward placements where the residual
    // after this item can be tiled exactly by the next item repeated k
    // times (k >= 1) with zero leftover.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // Post-residual reusability vs. mean coupling — a leftover close to
    // the stream's mean residual is statistically most likely to be reused
    // later; reward closeness, punish outliers among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 22.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
    }

    // Dead-zone gradient refinement — residuals in the 20..=34 band are
    // only fillable by mid-class items; when the next item is small
    // (<= 10), such residuals are likely to survive untapped.
    if post_residual >= 20 && post_residual <= 34 && next_item_size > 0 && next_item_size <= 10 {
        score += 16.0;
    }

    // Two-bin exact-split plan — when exactly two bins fit and this
    // placement leaves a residual that exactly equals next_item_size, it
    // is a perfect handoff; reward it beyond the generic lookahead bonus.
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0;
    }

    // Residual-value discount for large leftovers consumed by small
    // items — placing a tiny item into a big pocket destroys future
    // packing potential; scale the tax with the destroyed fraction.
    if post_residual > 0 && item_size > 0 && bin_residual > item_size {
        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Dead-space budget coupling — when the mean residual across open bins
    // is already high, leaving yet another mid-range leftover compounds
    // waste; tax placements whose post_residual both exceeds the mean and
    // sits in the hard-to-fill 10..=29 band.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Near-perfect-fit gradient sharpening — among competing bins, a
    // post_residual of exactly 1..=2 is nearly a perfect fill; reward it
    // beyond the flat tier so the tightest bin wins decisively.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    // Dual-lookahead consolidation — when the current item and the
    // next-item pair leave a residual within a small-filler band of
    // zero, prefer this bin strongly.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // Waste-gap interpolation — among competing bins, prefer the bin
    // whose post_residual sits on a reusable band boundary (multiple of
    // 10), taxing residuals stranded mid-band between classes.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual < 60 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 14.0;
        } else if m >= 7 {
            score += 6.0 + (m - 7) as f64 * 3.0;
        }
    }

    // Triple-chain consolidation — when the current item plus the
    // next item leaves a residual exactly tileable by a third plausible
    // chunk (next_item_size again or a class multiple), this bin is a
    // full three-item plan; reward it decisively.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 0 && (after_pair == next_item_size || after_pair % 10 == 0) {
            score -= 46.0;
        }
    }

    // Combined fine-grained residual + lookahead: when many bins fit and
    // this placement leaves a residual that both is small in absolute
    // terms AND can absorb the next item, consolidate decisively here.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Class-aware dead-zone tax — a leftover whose size sits strictly
    // between the next item's class boundary and the next class floor is
    // unlikely to be filled by anything arriving soon; tax it in proportion
    // to how far it overshoots the next item, but only when alternatives
    // exist (multiple fitting bins), so unique fits stay untouched.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting — in the final third of the
    // stream, prefer placements that leave a residual exactly reusable by
    // the next item even at the cost of a slightly larger current fit;
    // chains of exact handoffs eliminate trailing waste bins.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation — when many bins are open,
    // the tightest fit matters more because each leftover fragment is
    // another bin that may never close; sharpen the tight-fit gradient
    // with open_bins_count so crowded states converge to best-fit harder.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket — a post_residual that falls
    // within [next_item_size, next_item_size + 3] is a guaranteed reuse
    // for the immediate successor; reward it progressively beyond the
    // generic slack bonus, strongest when few bins fit (scarce space).
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain — in the final 20% of the stream,
    // small items (<= 12) should preferentially drain the bin with the
    // SMALLEST residual they can fit, preserving large pockets for the
    // remaining medium/large items; tax placements into big pockets.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — if this placement closes the bin exactly
    // AND the next item also fits the residual after being added (i.e. a
    // two-item exact close), reward decisively regardless of bin count.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // NEW: Congestion-scaled dead-band widening — when many bins are open,
    // widen the sub-next dead-band tax so crowded states avoid leaving
    // residuals just under the successor's size even at moderate gaps.
    if open_bins_count > 5 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap > 8 && gap <= 14 {
            score += 6.0 + (14 - gap as i32) as f64 * 1.5;
        }
    }

    // NEW: Mid-residual harvest gate — placements leaving residuals in
    // 20..=29 when the next item cannot use them (next > post) are taxed
    // progressively with progress, since late mid-fragments rarely close.
    if next_item_size > 0 && post_residual >= 20 && post_residual <= 29 && next_item_size > post_residual {
        score += 10.0 * progress;
    }

    // NEW: Fresh-bin exact-triple plan — when the fresh bin's capacity is
    // within 3 of current + 2x next, opening it is a near-perfect
    // three-item plan; reward decisively so it beats mediocre open fits.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let d3 = bin_capacity as i64 - (item_size as i64 + 2 * next_item_size as i64);
        if d3 >= 0 && d3 <= 3 {
            score -= 96.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
            score -= 32.0;
        }
    }

    // Pair exactness — residual exactly equals current+next is a jackpot.
    if pair > 0 && bin_residual == pair {
        score -= 266.0;
    }

    // Multi-fill potential — how many additional items of next size could
    // still land in this bin after the current one. More = better consolidation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let multi = post_residual / next_item_size;
        if multi >= 2 {
            score -= 22.0 * (multi.min(4) as f64);
        }
    }

    // Reusability shaping: leftover between ~15% and ~45% of capacity is highly reusable.
    if post_residual > 0 {
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 30.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
    }

    // Exact-complement chain — post_residual can exactly absorb next item
    // plus another known-size chunk; near-perfect plan, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 68.0;
        }
    }

    // Avoid leaving residuals just below the next item size (dead pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax — residuals too small for most item classes
    // (1..=9) are almost guaranteed waste; scale penalty with depth.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
    }

    // Harmonic-fit bonus — post_residual matching common complements of
    // typical item sizes (multiples of 25 or 50) stays fillable.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0) {
        score -= 35.0;
    }

    // Mid-band residual shaping — reward exactly-fillable remainders,
    // punish near-miss remainders just above the next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
    }

    // Fit-quality gradient among competing bins — push selection toward
    // the bin whose placement leaves the smallest post_residual relative
    // to the item's own class.
    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 58.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Three-item chain check — current + next + a small filler (1..=10)
    // exactly fills this bin's residual; an exceptionally strong plan.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let chain = bin_residual - item_size - next_item_size;
        if chain >= 1 && chain <= 10 {
            score -= 88.0;
        }
    }

    // Two-step exactness — after placing the current item, check whether
    // post_residual can absorb next_item_size AND a mid-class filler exactly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 15 && after_next <= 45 && after_next % 5 == 0 {
            score -= 36.0;
        }
        if after_next > 0 && after_next < 10 {
            score += 26.0;
        }
    }

    // Residual-fragmentation tax — when many open bins exist, leaving a
    // mid-sized residual (fragment) spreads waste across bins; consolidate.
    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        // When open bins exist but every fit is poor (large item, tiny residuals),
        // opening fresh is cheaper than shattering a usable residual.
        if fitting_bins_count > 0 && item_size > bin_capacity / 3 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 45.0 * (1.0 - progress);
            }
        }
        // Protect big pockets late in the stream.
        if fitting_bins_count > 0 && progress > 0.4 && item_size <= bin_capacity / 3 {
            if mean_residual < item_size as f64 * 1.5 {
                score -= 27.0 * progress;
            }
        }
        // If the next item is large and no open bin could hold it after
        // this placement, opening a fresh bin now preserves flexibility.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            if post_residual < next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin discipline — opening a new bin late wastes
        // capacity unless the item is big; penalize small-item new bins late.
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Mid-stream fresh-bin restraint — between 25% and 60% progress,
        // small items should almost never open fresh bins while any fit exists.
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        // Endgame fresh-bin economy — in the final 15% of the stream,
        // opening a fresh bin for a small item is almost pure waste.
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        // Pair-fit gate — if this fresh bin can absorb BOTH the current
        // and the next item exactly, opening it is a genuine plan, not waste.
        if pair > 0 && bin_residual >= pair {
            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
                score -= 98.0;
            }
        }
        // Dead-pocket escape — when the best available fit would leave a
        // residual too small for any plausible item (<= 9), a fresh bin
        // with a full residual is strictly better than shattering the pocket.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 9 {
            score -= 90.0 * (1.0 - progress).max(0.2);
        }
        // Next-item dead-pocket escape — if the current fit would leave a
        // residual just below next_item_size (unusable by the immediate
        // successor), a fresh bin preserves that space for the successor.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score -= 62.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin exact-pair plan — opening a bin whose capacity is
        // exactly current + next (or within 2) is a perfect two-item plan.
        if next_item_size > 0 {
            let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
            if diff >= 0 && diff <= 2 {
                score -= 112.0;
            }
        }
        // Oversized-item fresh-bin sharpening — items above 60% of capacity
        // almost never share a bin; when any open bin would be shattered to
        // a near-dead pocket (< 15 left), prefer the fresh bin aggressively.
        if fitting_bins_count > 0 && item_size * 5 > bin_capacity * 3 {
            if post_residual > 0 && post_residual < 15 {
                score -= 52.0;
            }
        }
        // Fresh-bin tileability — if the fresh bin's capacity can be
        // tiled by the next item repeated k>=2 times after this placement,
        // opening it now is a multi-item consolidation plan.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let after = bin_capacity - item_size;
            if after % next_item_size == 0 && after / next_item_size >= 2 {
                score -= 44.0;
            }
        }
        // Fresh-bin fragment-consolidation — when open bins hold many
        // small scattered fragments (low mean residual, many bins), opening
        // one fresh bin for a large item keeps those fragments intact for
        // the many small items that follow, instead of burning the single
        // large pocket that remains.
        if fitting_bins_count > 0 && open_bins_count > 3 && item_size > bin_capacity / 2 {
            if mean_residual < item_size as f64 * 1.2 {
                score -= 40.0 * (1.0 - progress).max(0.25);
            }
        }
        // Fresh-bin mid-fit gate — when an open-bin fit would leave a
        // residual in the awkward 30..=45 band (too big to die, too small
        // to tile reliably) while the fresh bin can hold current+next with
        // slack <= 10, prefer the fresh bin as a deliberate two-item plan.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= 30 && post_residual <= 45 {
            let fresh_slack = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_slack <= 10 {
                score -= 58.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin triple-tile plan — if the fresh bin can hold the
        // current item plus the next item twice with <= 5 slack, opening it
        // is a three-item consolidation that eliminates a whole future bin.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let t3 = bin_capacity - (item_size + 2 * next_item_size);
            if t3 <= 5 {
                score -= 74.0 * (1.0 - progress).max(0.4);
            }
        }
        score += 30.0 + 40.0 * progress;
    }

    // Waste-floor shaping for regular placements — when several bins fit,
    // a placement leaving a residual of 10..=19 is a near-dead pocket for
    // most distributions; tax it progressively (sharpened slope).
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 19 {
        score += 24.0 + (19 - post_residual as i32) as f64 * 4.0;
    }

    // Sub-next dead-band sharpening — when multiple bins fit, a placement
    // whose residual sits within 8 units below next_item_size is unusable
    // by the immediate successor; tax proportionally to closeness.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 8 {
            score += 14.0 + (8 - gap as i32) as f64 * 4.0;
        }
    }

    // Congestion: many open bins -> favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals from being consumed by small items late in stream.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Late-stream exactness boost — perfect/near-perfect fits matter more
    // when few items remain.
    let remaining_frac = 1.0 - progress;
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Divisibility-aware waste penalty — leftover that no multiple of any
    // plausible item class fills is taxed mildly.
    if post_residual > 0 && post_residual < bin_capacity {
        let cls = (post_residual / 10).max(1);
        if post_residual % (cls * 10) != 0 && post_residual < 50 {
            score += 11.0;
        }
    }

    // Exact-fill lookahead sweep — reward placements where the residual
    // after this item can be tiled exactly by the next item repeated k
    // times (k >= 1) with zero leftover.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // Post-residual reusability vs. mean coupling — a leftover close to
    // the stream's mean residual is statistically most likely to be reused
    // later; reward closeness, punish outliers among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 22.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
    }

    // Dead-zone gradient refinement — residuals in the 20..=34 band are
    // only fillable by mid-class items; when the next item is small
    // (<= 10), such residuals are likely to survive untapped.
    if post_residual >= 20 && post_residual <= 34 && next_item_size > 0 && next_item_size <= 10 {
        score += 16.0;
    }

    // Two-bin exact-split plan — when exactly two bins fit and this
    // placement leaves a residual that exactly equals next_item_size, it
    // is a perfect handoff; reward it beyond the generic lookahead bonus.
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0;
    }

    // Residual-value discount for large leftovers consumed by small
    // items — placing a tiny item into a big pocket destroys future
    // packing potential; scale the tax with the destroyed fraction.
    if post_residual > 0 && item_size > 0 && bin_residual > item_size {
        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Dead-space budget coupling — when the mean residual across open bins
    // is already high, leaving yet another mid-range leftover compounds
    // waste; tax placements whose post_residual both exceeds the mean and
    // sits in the hard-to-fill 10..=29 band.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Near-perfect-fit gradient sharpening — among competing bins, a
    // post_residual of exactly 1..=2 is nearly a perfect fill; reward it
    // beyond the flat tier so the tightest bin wins decisively.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    // Dual-lookahead consolidation — when the current item and the
    // next-item pair leave a residual within a small-filler band of
    // zero, prefer this bin strongly.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // Waste-gap interpolation — among competing bins, prefer the bin
    // whose post_residual sits on a reusable band boundary (multiple of
    // 10), taxing residuals stranded mid-band between classes.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual < 60 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 14.0;
        } else if m >= 7 {
            score += 6.0 + (m - 7) as f64 * 3.0;
        }
    }

    // Triple-chain consolidation — when the current item plus the
    // next item leaves a residual exactly tileable by a third plausible
    // chunk (next_item_size again or a class multiple), this bin is a
    // full three-item plan; reward it decisively.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 0 && (after_pair == next_item_size || after_pair % 10 == 0) {
            score -= 46.0;
        }
    }

    // Combined fine-grained residual + lookahead: when many bins fit and
    // this placement leaves a residual that both is small in absolute
    // terms AND can absorb the next item, consolidate decisively here.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Class-aware dead-zone tax — a leftover whose size sits strictly
    // between the next item's class boundary and the next class floor is
    // unlikely to be filled by anything arriving soon; tax it in proportion
    // to how far it overshoots the next item, but only when alternatives
    // exist (multiple fitting bins), so unique fits stay untouched.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting — in the final third of the
    // stream, prefer placements that leave a residual exactly reusable by
    // the next item even at the cost of a slightly larger current fit;
    // chains of exact handoffs eliminate trailing waste bins.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation — when many bins are open,
    // the tightest fit matters more because each leftover fragment is
    // another bin that may never close; sharpen the tight-fit gradient
    // with open_bins_count so crowded states converge to best-fit harder.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket — a post_residual that falls
    // within [next_item_size, next_item_size + 3] is a guaranteed reuse
    // for the immediate successor; reward it progressively beyond the
    // generic slack bonus, strongest when few bins fit (scarce space).
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain — in the final 20% of the stream,
    // small items (<= 12) should preferentially drain the bin with the
    // SMALLEST residual they can fit, preserving large pockets for the
    // remaining medium/large items; tax placements into big pockets.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — if this placement closes the bin exactly
    // AND the next item also fits the residual after being added (i.e. a
    // two-item exact close), reward decisively regardless of bin count.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // NEW (gen 16): Continuous post-residual gradient — replace the
    // coarse absolute base term with a super-linear waste curve so that
    // every extra unit of leftover is punished increasingly hard; this
    // directly targets the diagnosed dead-space weakness while keeping
    // all tiered bonuses intact.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let cap = bin_capacity as f64;
        score += (pr * pr) / (2.0 * cap);
    }

    // NEW (gen 16): Mean-residual matching gate — when competing bins
    // exist, a placement whose post_residual lands close to the current
    // mean residual is most likely to be filled by a future item of
    // typical size; reward tight proximity with a graded bonus.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist <= 3.0 {
            score -= 14.0;
        }
    }

    // NEW (gen 16): Endgame zero-waste sweep — in the final 10% of the
    // stream, any placement that exactly closes a bin (post_residual 0)
    // is worth extra because every remaining item must otherwise open a
    // fresh bin; sharpen the terminal exactness reward.
    if progress > 0.9 && post_residual == 0 {
        score -= 90.0 * progress;
    }

    // NEW (gen 16): Next-item drain continuity — when the residual after
    // this placement can absorb the next item AND still leave a small
    // (<= 10) remainder for a filler, this bin supports a three-item
    // chain; reward it scaled by how few bins are open (scarcity).
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 10 {
            let scarcity = (open_bins_count as f64).max(1.0);
            score -= 30.0 / scarcity.sqrt().max(1.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
            score -= 32.0;
        }
    }

    // Pair exactness — residual exactly equals current+next is a jackpot.
    if pair > 0 && bin_residual == pair {
        score -= 266.0;
    }

    // Multi-fill potential — how many additional items of next size could
    // still land in this bin after the current one. More = better consolidation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let multi = post_residual / next_item_size;
        if multi >= 2 {
            score -= 22.0 * (multi.min(4) as f64);
        }
    }

    // Reusability shaping: leftover between ~15% and ~45% of capacity is highly reusable.
    if post_residual > 0 {
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 30.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
    }

    // Exact-complement chain — post_residual can exactly absorb next item
    // plus another known-size chunk; near-perfect plan, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 68.0;
        }
    }

    // Avoid leaving residuals just below the next item size (dead pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax — residuals too small for most item classes
    // (1..=9) are almost guaranteed waste; scale penalty with depth.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
    }

    // Harmonic-fit bonus — post_residual matching common complements of
    // typical item sizes (multiples of 25 or 50) stays fillable.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0) {
        score -= 35.0;
    }

    // Mid-band residual shaping — reward exactly-fillable remainders,
    // punish near-miss remainders just above the next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
    }

    // Fit-quality gradient among competing bins — push selection toward
    // the bin whose placement leaves the smallest post_residual relative
    // to the item's own class.
    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 58.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Three-item chain check — current + next + a small filler (1..=10)
    // exactly fills this bin's residual; an exceptionally strong plan.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let chain = bin_residual - item_size - next_item_size;
        if chain >= 1 && chain <= 10 {
            score -= 88.0;
        }
    }

    // Two-step exactness — after placing the current item, check whether
    // post_residual can absorb next_item_size AND a mid-class filler exactly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 15 && after_next <= 45 && after_next % 5 == 0 {
            score -= 36.0;
        }
        if after_next > 0 && after_next < 10 {
            score += 26.0;
        }
    }

    // Residual-fragmentation tax — when many open bins exist, leaving a
    // mid-sized residual (fragment) spreads waste across bins; consolidate.
    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        // When open bins exist but every fit is poor (large item, tiny residuals),
        // opening fresh is cheaper than shattering a usable residual.
        if fitting_bins_count > 0 && item_size > bin_capacity / 3 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 45.0 * (1.0 - progress);
            }
        }
        // Protect big pockets late in the stream.
        if fitting_bins_count > 0 && progress > 0.4 && item_size <= bin_capacity / 3 {
            if mean_residual < item_size as f64 * 1.5 {
                score -= 27.0 * progress;
            }
        }
        // If the next item is large and no open bin could hold it after
        // this placement, opening a fresh bin now preserves flexibility.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            if post_residual < next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin discipline — opening a new bin late wastes
        // capacity unless the item is big; penalize small-item new bins late.
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Mid-stream fresh-bin restraint — between 25% and 60% progress,
        // small items should almost never open fresh bins while any fit exists.
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        // Endgame fresh-bin economy — in the final 15% of the stream,
        // opening a fresh bin for a small item is almost pure waste.
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        // Pair-fit gate — if this fresh bin can absorb BOTH the current
        // and the next item exactly, opening it is a genuine plan, not waste.
        if pair > 0 && bin_residual >= pair {
            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
                score -= 98.0;
            }
        }
        // Dead-pocket escape — when the best available fit would leave a
        // residual too small for any plausible item (<= 9), a fresh bin
        // with a full residual is strictly better than shattering the pocket.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 9 {
            score -= 90.0 * (1.0 - progress).max(0.2);
        }
        // Next-item dead-pocket escape — if the current fit would leave a
        // residual just below next_item_size (unusable by the immediate
        // successor), a fresh bin preserves that space for the successor.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score -= 62.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin exact-pair plan — opening a bin whose capacity is
        // exactly current + next (or within 2) is a perfect two-item plan.
        if next_item_size > 0 {
            let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
            if diff >= 0 && diff <= 2 {
                score -= 112.0;
            }
        }
        // Oversized-item fresh-bin sharpening — items above 60% of capacity
        // almost never share a bin; when any open bin would be shattered to
        // a near-dead pocket (< 15 left), prefer the fresh bin aggressively.
        if fitting_bins_count > 0 && item_size * 5 > bin_capacity * 3 {
            if post_residual > 0 && post_residual < 15 {
                score -= 52.0;
            }
        }
        // Fresh-bin tileability — if the fresh bin's capacity can be
        // tiled by the next item repeated k>=2 times after this placement,
        // opening it now is a multi-item consolidation plan.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let after = bin_capacity - item_size;
            if after % next_item_size == 0 && after / next_item_size >= 2 {
                score -= 44.0;
            }
        }
        // Fresh-bin fragment-consolidation — when open bins hold many
        // small scattered fragments (low mean residual, many bins), opening
        // one fresh bin for a large item keeps those fragments intact for
        // the many small items that follow, instead of burning the single
        // large pocket that remains.
        if fitting_bins_count > 0 && open_bins_count > 3 && item_size > bin_capacity / 2 {
            if mean_residual < item_size as f64 * 1.2 {
                score -= 40.0 * (1.0 - progress).max(0.25);
            }
        }
        // Fresh-bin mid-fit gate — when an open-bin fit would leave a
        // residual in the awkward 30..=45 band (too big to die, too small
        // to tile reliably) while the fresh bin can hold current+next with
        // slack <= 10, prefer the fresh bin as a deliberate two-item plan.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= 30 && post_residual <= 45 {
            let fresh_slack = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_slack <= 10 {
                score -= 58.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin triple-tile plan — if the fresh bin can hold the
        // current item plus the next item twice with <= 5 slack, opening it
        // is a three-item consolidation that eliminates a whole future bin.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let t3 = bin_capacity - (item_size + 2 * next_item_size);
            if t3 <= 5 {
                score -= 74.0 * (1.0 - progress).max(0.4);
            }
        }
        score += 30.0 + 40.0 * progress;
    }

    // Waste-floor shaping for regular placements — when several bins fit,
    // a placement leaving a residual of 10..=19 is a near-dead pocket for
    // most distributions; tax it progressively (sharpened slope).
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 19 {
        score += 24.0 + (19 - post_residual as i32) as f64 * 4.0;
    }

    // Sub-next dead-band sharpening — when multiple bins fit, a placement
    // whose residual sits within 8 units below next_item_size is unusable
    // by the immediate successor; tax proportionally to closeness.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 8 {
            score += 14.0 + (8 - gap as i32) as f64 * 4.0;
        }
    }

    // Congestion: many open bins -> favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals from being consumed by small items late in stream.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Late-stream exactness boost — perfect/near-perfect fits matter more
    // when few items remain.
    let remaining_frac = 1.0 - progress;
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Divisibility-aware waste penalty — leftover that no multiple of any
    // plausible item class fills is taxed mildly.
    if post_residual > 0 && post_residual < bin_capacity {
        let cls = (post_residual / 10).max(1);
        if post_residual % (cls * 10) != 0 && post_residual < 50 {
            score += 11.0;
        }
    }

    // Exact-fill lookahead sweep — reward placements where the residual
    // after this item can be tiled exactly by the next item repeated k
    // times (k >= 1) with zero leftover.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // Post-residual reusability vs. mean coupling — a leftover close to
    // the stream's mean residual is statistically most likely to be reused
    // later; reward closeness, punish outliers among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 22.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
    }

    // Dead-zone gradient refinement — residuals in the 20..=34 band are
    // only fillable by mid-class items; when the next item is small
    // (<= 10), such residuals are likely to survive untapped.
    if post_residual >= 20 && post_residual <= 34 && next_item_size > 0 && next_item_size <= 10 {
        score += 16.0;
    }

    // Two-bin exact-split plan — when exactly two bins fit and this
    // placement leaves a residual that exactly equals next_item_size, it
    // is a perfect handoff; reward it beyond the generic lookahead bonus.
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0;
    }

    // Residual-value discount for large leftovers consumed by small
    // items — placing a tiny item into a big pocket destroys future
    // packing potential; scale the tax with the destroyed fraction.
    if post_residual > 0 && item_size > 0 && bin_residual > item_size {
        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Dead-space budget coupling — when the mean residual across open bins
    // is already high, leaving yet another mid-range leftover compounds
    // waste; tax placements whose post_residual both exceeds the mean and
    // sits in the hard-to-fill 10..=29 band.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Near-perfect-fit gradient sharpening — among competing bins, a
    // post_residual of exactly 1..=2 is nearly a perfect fill; reward it
    // beyond the flat tier so the tightest bin wins decisively.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    // Dual-lookahead consolidation — when the current item and the
    // next-item pair leave a residual within a small-filler band of
    // zero, prefer this bin strongly.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // Waste-gap interpolation — among competing bins, prefer the bin
    // whose post_residual sits on a reusable band boundary (multiple of
    // 10), taxing residuals stranded mid-band between classes.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual < 60 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 14.0;
        } else if m >= 7 {
            score += 6.0 + (m - 7) as f64 * 3.0;
        }
    }

    // Triple-chain consolidation — when the current item plus the
    // next item leaves a residual exactly tileable by a third plausible
    // chunk (next_item_size again or a class multiple), this bin is a
    // full three-item plan; reward it decisively.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 0 && (after_pair == next_item_size || after_pair % 10 == 0) {
            score -= 46.0;
        }
    }

    // Combined fine-grained residual + lookahead: when many bins fit and
    // this placement leaves a residual that both is small in absolute
    // terms AND can absorb the next item, consolidate decisively here.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Class-aware dead-zone tax — a leftover whose size sits strictly
    // between the next item's class boundary and the next class floor is
    // unlikely to be filled by anything arriving soon; tax it in proportion
    // to how far it overshoots the next item, but only when alternatives
    // exist (multiple fitting bins), so unique fits stay untouched.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting — in the final third of the
    // stream, prefer placements that leave a residual exactly reusable by
    // the next item even at the cost of a slightly larger current fit;
    // chains of exact handoffs eliminate trailing waste bins.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation — when many bins are open,
    // the tightest fit matters more because each leftover fragment is
    // another bin that may never close; sharpen the tight-fit gradient
    // with open_bins_count so crowded states converge to best-fit harder.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket — a post_residual that falls
    // within [next_item_size, next_item_size + 3] is a guaranteed reuse
    // for the immediate successor; reward it progressively beyond the
    // generic slack bonus, strongest when few bins fit (scarce space).
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain — in the final 20% of the stream,
    // small items (<= 12) should preferentially drain the bin with the
    // SMALLEST residual they can fit, preserving large pockets for the
    // remaining medium/large items; tax placements into big pockets.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — if this placement closes the bin exactly
    // AND the next item also fits the residual after being added (i.e. a
    // two-item exact close), reward decisively regardless of bin count.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // NEW: Continuation refinement — tighten the waste-floor band to
    // directly target the diagnosed residual/dead-space weakness. Extend
    // the near-dead-pocket tax (10..=19) smoothly into 20..=29 with a
    // gentler slope, and deepen the top-tier perfect-fit rewards so the
    // tightest bins dominate even more decisively among competitors.
    if fitting_bins_count > 1 && post_residual >= 20 && post_residual <= 29 {
        score += 8.0 + (29 - post_residual as i32) as f64 * 1.6;
    }
    if fitting_bins_count > 1 && post_residual >= 3 && post_residual <= 5 {
        score -= 18.0 * (6 - post_residual as i32) as f64;
    }

    // NEW: Dead-space budget enforcement — when the stream's mean residual
    // is already low (packing is going well), any placement that would
    // leave a leftover noticeably ABOVE that mean is the primary source of
    // the remaining wasted bins; tax it proportionally, scaled by how much
    // slack the current placement wastes relative to the best conceivable
    // (zero-leftover) outcome, but only when alternatives exist.
    if fitting_bins_count > 1 && post_residual > 0 && mean_residual < 40.0 {
        let excess = (post_residual as f64) - mean_residual;
        if excess > 12.0 {
            score += 6.0 + excess * 0.45;
        }
    }

    // NEW: Half-capacity pocket trap — a leftover sitting just below half
    // of the item's own size class band (e.g. residual 24..=39 when the
    // next item is medium 30..=49) is a classic dead pocket: too small for
    // the successor, too large to ignore. Detect the specific mismatch
    // where post_residual is within 12 below the next class floor and tax
    // it hard, pushing selection toward bins that avoid stranding space.
    if next_item_size > 0 && post_residual > 0 {
        let next_floor = (next_item_size / 10) * 10;
        if next_floor >= 20 && post_residual < next_floor && next_floor - post_residual <= 12 {
            score += 15.0 + (next_floor - post_residual) as f64 * 1.1;
        }
    }

    // NEW: Late-stream zero-waste sweep — in the final quarter, every
    // leftover is likely permanent waste; escalate the tax on any
    // non-zero post_residual proportionally to remaining slack, while
    // preserving the existing exact-handoff bonuses.
    if progress > 0.75 && post_residual > 0 {
        score += (post_residual as f64) * 0.55 * ((progress - 0.75) * 4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

