        }
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        // Pair-fit gate — fresh bin absorbing current+next exactly.
        if pair > 0 && bin_residual >= pair {
            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
