        }
    }

    // Late-stream fragment harvesting.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket.
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — two-item exact close.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // NEW: Cumulative dead-space budget — when the stream's mean residual is
    // already low (tight packing achieved), be extra intolerant of any
    // placement that leaves a mid-range leftover; when mean residual is high
    // (fragmented state), tolerate leftovers that exceed the mean so we
    // consolidate into the fullest bins instead of spreading waste.
    if post_residual > 0 && post_residual < 30 {
        if mean_residual < 15.0 {
            score += 18.0;
        } else if (post_residual as f64) < mean_residual * 0.5 {
            score -= 12.0;
        }
    }

    // NEW: Scarcity-weighted tightness — with few fitting bins, residual
    // quality dominates; scale the base post_residual term by bin scarcity
    // so tight fits win harder when space is scarce.
    if fitting_bins_count > 0 && fitting_bins_count <= 3 && post_residual > 0 {
        score += (post_residual as f64) * (0.15 * (3 - fitting_bins_count) as f64);
    }

    score
}

