        // Waste-floor shaping: residuals of 10..=19 are near-dead pockets.
        if post_residual >= 10 && post_residual <= 19 {
            score += 24.0 + (19 - post_residual as i32) as f64 * 4.0;
        }
        // Sub-next dead-band sharpening.
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score += 14.0 + (8 - gap as i32) as f64 * 4.0;
            }
        }
        // Mean-residual closeness coupling.
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 22.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
        // Band-boundary alignment: multiples of 10 are reusable.
        if post_residual < 60 {
            let m = post_residual % 10;
            if m == 0 {
                score -= 14.0;
            } else if m >= 7 {
                score += 6.0 + (m - 7) as f64 * 3.0;
            }
        }
        if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 34.0;
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let overshoot = post_residual - next_item_size;
            if overshoot > 10 && overshoot <= 20 {
                score += 8.0 + (overshoot - 10) as f64 * 1.2;
            }
        }
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        if fitting_bins_count > 0 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 45.0 * (1.0 - progress);
            }
            if item_size > bin_capacity / 3 && progress > 0.6 && mean_residual > (item_size as f64) + 15.0 {
                score -= 55.0 * (1.0 - progress);
            }
            if open_bins_count > 3 && item_size > bin_capacity / 2 && mean_residual < item_size as f64 * 1.2 {
                score -= 40.0 * (1.0 - progress).max(0.25);
            }
            // Dead-pocket escape — a fit leaving a residual <= 9 is worse
            // than a fresh bin with full residual.
            if post_residual > 0 && post_residual <= 9 {
                score -= 90.0 * (1.0 - progress).max(0.2);
            }
            // Next-item dead-pocket escape.
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
                let gap = next_item_size - post_residual;
                if gap <= 8 {
                    score -= 62.0 * (1.0 - progress).max(0.3);
                }
            }
            // Oversized-item sharpening.
            if item_size * 5 > bin_capacity * 3 && post_residual > 0 && post_residual < 15 {
                score -= 52.0;
            }
            // Fresh-bin exact-pair plan.
            if next_item_size > 0 {
                let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
                if diff >= 0 && diff <= 2 {
                    score -= 112.0;
                }
            }
            // Fresh-bin tileability with the next item.
            if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
                let after = bin_capacity - item_size;
                if after % next_item_size == 0 && after / next_item_size >= 2 {
                    score -= 44.0;
                }
            }
            // Fresh-bin triple-tile plan — current + next twice with tiny slack.
            if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
                let t3 = bin_capacity - (item_size + 2 * next_item_size);
                if t3 <= 5 {
                    score -= 74.0 * (1.0 - progress).max(0.4);
                }
            }
            // Fresh-bin mid-fit gate — awkward 30..=45 leftover vs a fresh
            // two-item plan with slack <= 10.
            if next_item_size > 0 && post_residual >= 30 && post_residual <= 45 {
                let fresh_slack = bin_capacity.saturating_sub(item_size + next_item_size);
                if fresh_slack <= 10 {
                    score -= 58.0 * (1.0 - progress).max(0.3);
                }
            }
            // Late-stream fresh-bin discipline.
            if progress > 0.6 && item_size <= bin_capacity / 4 {
                score += 55.0 * progress;
            }
            if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 {
                score += 38.0;
            }
            if progress > 0.85 && item_size < bin_capacity / 5 {
                score += 78.0;
            }
        }
        // Preserve flexibility: large next item wouldn't fit after this placement.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 && post_residual < next_item_size {
            score -= 34.0 * (1.0 - progress);
        }
        score += 30.0 + 40.0 * progress;
    }

    // Congestion: many open bins -> favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals from being consumed by small items late in stream.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Residual fragmentation guard: tiny slivers accumulate as dead space.
    if post_residual > 0 && post_residual < 6 && progress > 0.3 {
        score += 45.0;
    }

    // Late-stream exactness boost.
    let remaining_frac = 1.0 - progress;
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Late-stream fragment harvesting — exact handoffs in the final third.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Residual-value discount for large leftovers consumed by small items.
    if post_residual > 0 && bin_residual > item_size {
        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Dead-space budget coupling.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Two-bin exact-split plan — perfect handoff when exactly two bins fit.
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0;
    }

    // Fragment-count-aware consolidation — crowded states converge to best-fit.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket — guaranteed reuse for the successor,
    // strongest when few bins fit (scarce space).
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain — small items should drain the smallest
    // usable pocket, preserving large pockets for later medium/large items.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — two-item exact close jackpot.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // Divisibility-aware waste penalty — leftover no plausible class multiple
    // fills is taxed mildly.
    if post_residual > 0 && post_residual < bin_capacity {
        let cls = (post_residual / 10).max(1);
        if post_residual % (cls * 10) != 0 && post_residual < 50 {
            score += 11.0;
        }
    }

    // Exact-fill lookahead sweep — residual tileable exactly by next item.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // Dead-zone gradient refinement — mid-band residuals survive untapped
    // when the next item is small.
    if post_residual >= 20 && post_residual <= 34 && next_item_size > 0 && next_item_size <= 10 {
        score += 16.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let remaining_frac = 1.0 - progress;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
            score -= 32.0;
        }
    }

    // Pair exactness — residual exactly equals current+next is a jackpot.
    if pair > 0 && bin_residual == pair {
        score -= 266.0;
    }

    // Multi-fill potential — how many additional items of next size could
    // still land in this bin after the current one. More = better consolidation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let multi = post_residual / next_item_size;
        if multi >= 2 {
            score -= 22.0 * (multi.min(4) as f64);
        }
    }

    // Reusability shaping: leftover between ~15% and ~45% of capacity is highly reusable.
    if post_residual > 0 {
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 30.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
    }

    // Exact-complement chain — post_residual can exactly absorb next item
    // plus another known-size chunk; near-perfect plan, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 68.0;
        }
    }

    // Avoid leaving residuals just below the next item size (dead pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax — residuals too small for most item classes
    // (1..=9) are almost guaranteed waste; scale penalty with depth.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
    }

    // Harmonic-fit bonus — post_residual matching common complements of
    // typical item sizes (multiples of 25 or 50) stays fillable.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0) {
        score -= 35.0;
    }

    // Mid-band residual shaping — reward exactly-fillable remainders,
    // punish near-miss remainders just above the next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
    }

    // Fit-quality gradient among competing bins — push selection toward
    // the bin whose placement leaves the smallest post_residual relative
    // to the item's own class.
    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 58.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Three-item chain check — current + next + a small filler (1..=10)
    // exactly fills this bin's residual; an exceptionally strong plan.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let chain = bin_residual - item_size - next_item_size;
        if chain >= 1 && chain <= 10 {
            score -= 88.0;
        }
    }

    // Two-step exactness — after placing the current item, check whether
    // post_residual can absorb next_item_size AND a mid-class filler exactly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 15 && after_next <= 45 && after_next % 5 == 0 {
            score -= 36.0;
        }
        if after_next > 0 && after_next < 10 {
            score += 26.0;
        }
    }

    // Residual-fragmentation tax — when many open bins exist, leaving a
    // mid-sized residual (fragment) spreads waste across bins; consolidate.
    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        // When open bins exist but every fit is poor (large item, tiny residuals),
        // opening fresh is cheaper than shattering a usable residual.
        if fitting_bins_count > 0 && item_size > bin_capacity / 3 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 45.0 * (1.0 - progress);
            }
        }
        // Protect big pockets late in the stream.
        if fitting_bins_count > 0 && progress > 0.4 && item_size <= bin_capacity / 3 {
            if mean_residual < item_size as f64 * 1.5 {
                score -= 27.0 * progress;
            }
        }
        // If the next item is large and no open bin could hold it after
        // this placement, opening a fresh bin now preserves flexibility.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            if post_residual < next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin discipline — opening a new bin late wastes
        // capacity unless the item is big; penalize small-item new bins late.
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Mid-stream fresh-bin restraint — between 25% and 60% progress,
        // small items should almost never open fresh bins while any fit exists.
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        // Endgame fresh-bin economy — in the final 15% of the stream,
        // opening a fresh bin for a small item is almost pure waste.
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        // Pair-fit gate — if this fresh bin can absorb BOTH the current
        // and the next item exactly, opening it is a genuine plan, not waste.
        if pair > 0 && bin_residual >= pair {
            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
                score -= 98.0;
            }
        }
        // Dead-pocket escape — when the best available fit would leave a
        // residual too small for any plausible item (<= 9), a fresh bin
        // with a full residual is strictly better than shattering the pocket.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 9 {
            score -= 90.0 * (1.0 - progress).max(0.2);
        }
        // Next-item dead-pocket escape — if the current fit would leave a
        // residual just below next_item_size (unusable by the immediate
        // successor), a fresh bin preserves that space for the successor.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score -= 62.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin exact-pair plan — opening a bin whose capacity is
        // exactly current + next (or within 2) is a perfect two-item plan.
        if next_item_size > 0 {
            let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
            if diff >= 0 && diff <= 2 {
                score -= 112.0;
            }
        }
        // Oversized-item fresh-bin sharpening — items above 60% of capacity
        // almost never share a bin; when any open bin would be shattered to
        // a near-dead pocket (< 15 left), prefer the fresh bin aggressively.
        if fitting_bins_count > 0 && item_size * 5 > bin_capacity * 3 {
            if post_residual > 0 && post_residual < 15 {
                score -= 52.0;
            }
        }
        // Fresh-bin tileability — if the fresh bin's capacity can be
        // tiled by the next item repeated k>=2 times after this placement,
        // opening it now is a multi-item consolidation plan.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let after = bin_capacity - item_size;
            if after % next_item_size == 0 && after / next_item_size >= 2 {
                score -= 44.0;
            }
        }
        // Fresh-bin fragment-consolidation — when open bins hold many
        // small scattered fragments (low mean residual, many bins), opening
        // one fresh bin for a large item keeps those fragments intact for
        // the many small items that follow, instead of burning the single
        // large pocket that remains.
        if fitting_bins_count > 0 && open_bins_count > 3 && item_size > bin_capacity / 2 {
            if mean_residual < item_size as f64 * 1.2 {
                score -= 40.0 * (1.0 - progress).max(0.25);
            }
        }
        // Fresh-bin mid-fit gate — when an open-bin fit would leave a
        // residual in the awkward 30..=45 band (too big to die, too small
        // to tile reliably) while the fresh bin can hold current+next with
        // slack <= 10, prefer the fresh bin as a deliberate two-item plan.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= 30 && post_residual <= 45 {
            let fresh_slack = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_slack <= 10 {
                score -= 58.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin triple-tile plan — if the fresh bin can hold the
        // current item plus the next item twice with <= 5 slack, opening it
        // is a three-item consolidation that eliminates a whole future bin.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let t3 = bin_capacity - (item_size + 2 * next_item_size);
            if t3 <= 5 {
                score -= 74.0 * (1.0 - progress).max(0.4);
            }
        }
        // NEW: Fresh-bin fragment-rescue gate — when the best open-bin fit
        // would strand a residual in the 10..=24 dead band while the fresh
        // bin's post-placement leftover is itself reusable (>= 15 or 0),
        // opening fresh converts a doomed pocket into live capacity.
        if fitting_bins_count > 0 && post_residual >= 10 && post_residual <= 24 {
            let fresh_left = bin_capacity.saturating_sub(item_size);
            if fresh_left == 0 || fresh_left >= 15 {
                score -= 66.0 * (1.0 - progress).max(0.25);
            }
        }
        // NEW: Fresh-bin mid-pocket sweep — if several open bins fit and the
        // mean residual is already in the awkward 10..=28 band (fragmented
        // state), a fresh bin keeps big items out of the fragments.
        if fitting_bins_count > 1 && open_bins_count > 2 && mean_residual < 28.0 && item_size >= next_item_size {
            score -= 30.0 * (1.0 - progress).max(0.3);
        }
        score += 30.0 + 40.0 * progress;
    }

    // Waste-floor shaping for regular placements — when several bins fit,
    // a placement leaving a residual of 10..=19 is a near-dead pocket for
    // most distributions; tax it progressively (sharpened slope).
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 19 {
        score += 24.0 + (19 - post_residual as i32) as f64 * 4.0;
    }

    // Sub-next dead-band sharpening — when multiple bins fit, a placement
    // whose residual sits within 8 units below next_item_size is unusable
    // by the immediate successor; tax proportionally to closeness.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 8 {
            score += 14.0 + (8 - gap as i32) as f64 * 4.0;
        }
    }

    // Congestion: many open bins -> favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals from being consumed by small items late in stream.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Late-stream exactness boost — perfect/near-perfect fits matter more
    // when few items remain.
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Divisibility-aware waste penalty — leftover that no multiple of any
    // plausible item class fills is taxed mildly.
    if post_residual > 0 && post_residual < bin_capacity {
        let cls = (post_residual / 10).max(1);
        if post_residual % (cls * 10) != 0 && post_residual < 50 {
            score += 11.0;
        }
    }

    // Exact-fill lookahead sweep — reward placements where the residual
    // after this item can be tiled exactly by the next item repeated k
    // times (k >= 1) with zero leftover.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // Post-residual reusability vs. mean coupling — a leftover close to
    // the stream's mean residual is statistically most likely to be reused
    // later; reward closeness, punish outliers among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 22.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
    }

    // Dead-zone gradient refinement — residuals in the 20..=34 band are
    // only fillable by mid-class items; when the next item is small
    // (<= 10), such residuals are likely to survive untapped.
    if post_residual >= 20 && post_residual <= 34 && next_item_size > 0 && next_item_size <= 10 {
        score += 16.0;
    }

    // Two-bin exact-split plan — when exactly two bins fit and this
    // placement leaves a residual that exactly equals next_item_size, it
    // is a perfect handoff; reward it beyond the generic lookahead bonus.
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0;
    }

    // Residual-value discount for large leftovers consumed by small
    // items — placing a tiny item into a big pocket destroys future
    // packing potential; scale the tax with the destroyed fraction.
    if post_residual > 0 && item_size > 0 && bin_residual > item_size {
        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Dead-space budget coupling — when the mean residual across open bins
    // is already high, leaving yet another mid-range leftover compounds
    // waste; tax placements whose post_residual both exceeds the mean and
    // sits in the hard-to-fill 10..=29 band.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Near-perfect-fit gradient sharpening — among competing bins, a
    // post_residual of exactly 1..=2 is nearly a perfect fill; reward it
    // beyond the flat tier so the tightest bin wins decisively.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    // Dual-lookahead consolidation — when the current item and the
    // next-item pair leave a residual within a small-filler band of
    // zero, prefer this bin strongly.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // Waste-gap interpolation — among competing bins, prefer the bin
    // whose post_residual sits on a reusable band boundary (multiple of
    // 10), taxing residuals stranded mid-band between classes.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual < 60 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 14.0;
        } else if m >= 7 {
            score += 6.0 + (m - 7) as f64 * 3.0;
        }
    }

    // Triple-chain consolidation — when the current item plus the
    // next item leaves a residual exactly tileable by a third plausible
    // chunk (next_item_size again or a class multiple), this bin is a
    // full three-item plan; reward it decisively.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 0 && (after_pair == next_item_size || after_pair % 10 == 0) {
            score -= 46.0;
        }
    }

    // Combined fine-grained residual + lookahead: when many bins fit and
    // this placement leaves a residual that both is small in absolute
    // terms AND can absorb the next item, consolidate decisively here.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Class-aware dead-zone tax — a leftover whose size sits strictly
    // between the next item's class boundary and the next class floor is
    // unlikely to be filled by anything arriving soon; tax it in proportion
    // to how far it overshoots the next item, but only when alternatives
    // exist (multiple fitting bins), so unique fits stay untouched.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting — in the final third of the
    // stream, prefer placements that leave a residual exactly reusable by
    // the next item even at the cost of a slightly larger current fit;
    // chains of exact handoffs eliminate trailing waste bins.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation — when many bins are open,
    // the tightest fit matters more because each leftover fragment is
    // another bin that may never close; sharpen the tight-fit gradient
    // with open_bins_count so crowded states converge to best-fit harder.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket — a post_residual that falls
    // within [next_item_size, next_item_size + 3] is a guaranteed reuse
    // for the immediate successor; reward it progressively beyond the
    // generic slack bonus, strongest when few bins fit (scarce space).
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain — in the final 20% of the stream,
    // small items (<= 12) should preferentially drain the bin with the
    // SMALLEST residual they can fit, preserving large pockets for the
    // remaining medium/large items; tax placements into big pockets.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — if this placement closes the bin exactly
    // AND the next item also fits the residual after being added (i.e. a
    // two-item exact close), reward decisively regardless of bin count.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // NEW: Dead-band depth-aware redirection — when the placement leaves
    // a residual in the doomed 10..=24 band and an alternative bin exists
    // whose residual is at least 15 units larger (i.e. this bin's pocket
    // is uniquely shallow), tax this placement so the tighter alternative
    // fragments the smallest pocket instead of a reusable one.
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 24 {
        score += 18.0 * (1.0 - progress);
    }

    // NEW: Overshoot-vs-class conservation — when the next item cannot
    // fit the post_residual but the overshoot gap is small, the wasted
    // units are exactly (next - post); penalize proportionally so bins
    // whose leftover just misses the successor lose to bins that keep it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count > 1 {
        score += (next_item_size - post_residual) as f64 * 3.0 * progress.max(0.3);
    }

    // NEW: Mean-residual reclamation — late in the stream, prefer placing
    // into bins whose residual is close to the mean (statistically the
    // most reusable pockets), draining the middle of the distribution and
    // leaving outliers (both huge and tiny) for the tail.
    if progress > 0.5 && fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((bin_residual as f64) - mean_residual).abs();
        if dist < 10.0 {
            score -= 16.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
            score -= 32.0;
        }
    }

    // Pair exactness — residual exactly equals current+next is a jackpot.
    if pair > 0 && bin_residual == pair {
        score -= 266.0;
    }

    // Multi-fill potential — how many additional items of next size could
    // still land in this bin after the current one. More = better consolidation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let multi = post_residual / next_item_size;
        if multi >= 2 {
            score -= 22.0 * (multi.min(4) as f64);
        }
    }

    // Reusability shaping: leftover between ~15% and ~45% of capacity is highly reusable.
    if post_residual > 0 {
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 30.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
    }

    // Exact-complement chain — post_residual can exactly absorb next item
    // plus another known-size chunk; near-perfect plan, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 68.0;
        }
    }

    // Avoid leaving residuals just below the next item size (dead pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax — residuals too small for most item classes
    // (1..=9) are almost guaranteed waste; scale penalty with depth.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
    }

    // Harmonic-fit bonus — post_residual matching common complements of
    // typical item sizes (multiples of 25 or 50) stays fillable.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0) {
        score -= 35.0;
    }

    // Mid-band residual shaping — reward exactly-fillable remainders,
    // punish near-miss remainders just above the next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
    }

    // Fit-quality gradient among competing bins — push selection toward
    // the bin whose placement leaves the smallest post_residual relative
    // to the item's own class.
    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 58.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Three-item chain check — current + next + a small filler (1..=10)
    // exactly fills this bin's residual; an exceptionally strong plan.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let chain = bin_residual - item_size - next_item_size;
        if chain >= 1 && chain <= 10 {
            score -= 88.0;
        }
    }

    // Two-step exactness — after placing the current item, check whether
    // post_residual can absorb next_item_size AND a mid-class filler exactly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 15 && after_next <= 45 && after_next % 5 == 0 {
            score -= 36.0;
        }
        if after_next > 0 && after_next < 10 {
            score += 26.0;
        }
    }

    // Residual-fragmentation tax — when many open bins exist, leaving a
    // mid-sized residual (fragment) spreads waste across bins; consolidate.
    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        // When open bins exist but every fit is poor (large item, tiny residuals),
        // opening fresh is cheaper than shattering a usable residual.
        if fitting_bins_count > 0 && item_size > bin_capacity / 3 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 45.0 * (1.0 - progress);
            }
        }
        // Protect big pockets late in the stream.
        if fitting_bins_count > 0 && progress > 0.4 && item_size <= bin_capacity / 3 {
            if mean_residual < item_size as f64 * 1.5 {
                score -= 27.0 * progress;
            }
        }
        // If the next item is large and no open bin could hold it after
        // this placement, opening a fresh bin now preserves flexibility.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            if post_residual < next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin discipline — opening a new bin late wastes
        // capacity unless the item is big; penalize small-item new bins late.
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Mid-stream fresh-bin restraint — between 25% and 60% progress,
        // small items should almost never open fresh bins while any fit exists.
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        // Endgame fresh-bin economy — in the final 15% of the stream,
        // opening a fresh bin for a small item is almost pure waste.
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        // Pair-fit gate — if this fresh bin can absorb BOTH the current
        // and the next item exactly, opening it is a genuine plan, not waste.
        if pair > 0 && bin_residual >= pair {
            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
                score -= 98.0;
            }
        }
        // Dead-pocket escape — when the best available fit would leave a
        // residual too small for any plausible item (<= 9), a fresh bin
        // with a full residual is strictly better than shattering the pocket.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 9 {
            score -= 90.0 * (1.0 - progress).max(0.2);
        }
        // Next-item dead-pocket escape — if the current fit would leave a
        // residual just below next_item_size (unusable by the immediate
        // successor), a fresh bin preserves that space for the successor.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score -= 62.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin exact-pair plan — opening a bin whose capacity is
        // exactly current + next (or within 2) is a perfect two-item plan.
        if next_item_size > 0 {
            let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
            if diff >= 0 && diff <= 2 {
                score -= 112.0;
            }
        }
        // Oversized-item fresh-bin sharpening — items above 60% of capacity
        // almost never share a bin; when any open bin would be shattered to
        // a near-dead pocket (< 15 left), prefer the fresh bin aggressively.
        if fitting_bins_count > 0 && item_size * 5 > bin_capacity * 3 {
            if post_residual > 0 && post_residual < 15 {
                score -= 52.0;
            }
        }
        // Fresh-bin tileability — if the fresh bin's capacity can be
        // tiled by the next item repeated k>=2 times after this placement,
        // opening it now is a multi-item consolidation plan.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let after = bin_capacity - item_size;
            if after % next_item_size == 0 && after / next_item_size >= 2 {
                score -= 44.0;
            }
        }
        // Fresh-bin fragment-consolidation — when open bins hold many
        // small scattered fragments (low mean residual, many bins), opening
        // one fresh bin for a large item keeps those fragments intact for
        // the many small items that follow, instead of burning the single
        // large pocket that remains.
        if fitting_bins_count > 0 && open_bins_count > 3 && item_size > bin_capacity / 2 {
            if mean_residual < item_size as f64 * 1.2 {
                score -= 40.0 * (1.0 - progress).max(0.25);
            }
        }
        // Fresh-bin mid-fit gate — when an open-bin fit would leave a
        // residual in the awkward 30..=45 band (too big to die, too small
        // to tile reliably) while the fresh bin can hold current+next with
        // slack <= 10, prefer the fresh bin as a deliberate two-item plan.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= 30 && post_residual <= 45 {
            let fresh_slack = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_slack <= 10 {
                score -= 58.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin triple-tile plan — if the fresh bin can hold the
        // current item plus the next item twice with <= 5 slack, opening it
        // is a three-item consolidation that eliminates a whole future bin.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let t3 = bin_capacity - (item_size + 2 * next_item_size);
            if t3 <= 5 {
                score -= 74.0 * (1.0 - progress).max(0.4);
            }
        }
        // NEW: Fresh-bin dead-band escape at moderate progress — when the
        // only open-bin fits leave residuals in the 10..=19 near-dead band
        // and the item is mid-sized, a fresh bin keeps the fragments alive
        // for later small items instead of shattering them now.
        if fitting_bins_count > 0 && progress < 0.7 && post_residual >= 10 && post_residual <= 19 && item_size > bin_capacity / 4 {
            score -= 30.0 * (1.0 - progress).max(0.3);
        }
        score += 30.0 + 40.0 * progress;
    }

    // Waste-floor shaping for regular placements — when several bins fit,
    // a placement leaving a residual of 10..=19 is a near-dead pocket for
    // most distributions; tax it progressively (sharpened slope).
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 19 {
        score += 24.0 + (19 - post_residual as i32) as f64 * 4.0;
    }

    // Sub-next dead-band sharpening — when multiple bins fit, a placement
    // whose residual sits within 8 units below next_item_size is unusable
    // by the immediate successor; tax proportionally to closeness.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 8 {
            score += 14.0 + (8 - gap as i32) as f64 * 4.0;
        }
    }

    // Congestion: many open bins -> favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals from being consumed by small items late in stream.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Late-stream exactness boost — perfect/near-perfect fits matter more
    // when few items remain.
    let remaining_frac = 1.0 - progress;
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Divisibility-aware waste penalty — leftover that no multiple of any
    // plausible item class fills is taxed mildly.
    if post_residual > 0 && post_residual < bin_capacity {
        let cls = (post_residual / 10).max(1);
        if post_residual % (cls * 10) != 0 && post_residual < 50 {
            score += 11.0;
        }
    }

    // Exact-fill lookahead sweep — reward placements where the residual
    // after this item can be tiled exactly by the next item repeated k
    // times (k >= 1) with zero leftover.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // Post-residual reusability vs. mean coupling — a leftover close to
    // the stream's mean residual is statistically most likely to be reused
    // later; reward closeness, punish outliers among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 22.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
    }

    // Dead-zone gradient refinement — residuals in the 20..=34 band are
    // only fillable by mid-class items; when the next item is small
    // (<= 10), such residuals are likely to survive untapped.
    if post_residual >= 20 && post_residual <= 34 && next_item_size > 0 && next_item_size <= 10 {
        score += 16.0;
    }

    // Two-bin exact-split plan — when exactly two bins fit and this
    // placement leaves a residual that exactly equals next_item_size, it
    // is a perfect handoff; reward it beyond the generic lookahead bonus.
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0;
    }

    // Residual-value discount for large leftovers consumed by small
    // items — placing a tiny item into a big pocket destroys future
    // packing potential; scale the tax with the destroyed fraction.
    if post_residual > 0 && item_size > 0 && bin_residual > item_size {
        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Dead-space budget coupling — when the mean residual across open bins
    // is already high, leaving yet another mid-range leftover compounds
    // waste; tax placements whose post_residual both exceeds the mean and
    // sits in the hard-to-fill 10..=29 band.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Near-perfect-fit gradient sharpening — among competing bins, a
    // post_residual of exactly 1..=2 is nearly a perfect fill; reward it
    // beyond the flat tier so the tightest bin wins decisively.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    // Dual-lookahead consolidation — when the current item and the
    // next-item pair leave a residual within a small-filler band of
    // zero, prefer this bin strongly.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // Waste-gap interpolation — among competing bins, prefer the bin
    // whose post_residual sits on a reusable band boundary (multiple of
    // 10), taxing residuals stranded mid-band between classes.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual < 60 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 14.0;
        } else if m >= 7 {
            score += 6.0 + (m - 7) as f64 * 3.0;
        }
    }

    // Triple-chain consolidation — when the current item plus the
    // next item leaves a residual exactly tileable by a third plausible
    // chunk (next_item_size again or a class multiple), this bin is a
    // full three-item plan; reward it decisively.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 0 && (after_pair == next_item_size || after_pair % 10 == 0) {
            score -= 46.0;
        }
    }

    // Combined fine-grained residual + lookahead: when many bins fit and
    // this placement leaves a residual that both is small in absolute
    // terms AND can absorb the next item, consolidate decisively here.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Class-aware dead-zone tax — a leftover whose size sits strictly
    // between the next item's class boundary and the next class floor is
    // unlikely to be filled by anything arriving soon; tax it in proportion
    // to how far it overshoots the next item, but only when alternatives
    // exist (multiple fitting bins), so unique fits stay untouched.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting — in the final third of the
    // stream, prefer placements that leave a residual exactly reusable by
    // the next item even at the cost of a slightly larger current fit;
    // chains of exact handoffs eliminate trailing waste bins.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation — when many bins are open,
    // the tightest fit matters more because each leftover fragment is
    // another bin that may never close; sharpen the tight-fit gradient
    // with open_bins_count so crowded states converge to best-fit harder.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket — a post_residual that falls
    // within [next_item_size, next_item_size + 3] is a guaranteed reuse
    // for the immediate successor; reward it progressively beyond the
    // generic slack bonus, strongest when few bins fit (scarce space).
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain — in the final 20% of the stream,
    // small items (<= 12) should preferentially drain the bin with the
    // SMALLEST residual they can fit, preserving large pockets for the
    // remaining medium/large items; tax placements into big pockets.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — if this placement closes the bin exactly
    // AND the next item also fits the residual after being added (i.e. a
    // two-item exact close), reward decisively regardless of bin count.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // NEW: Mean-residual-matched pocket — a leftover within ±4 of the
    // stream's mean residual is the statistically most reusable size;
    // reward it when alternatives exist, sharpening best-fit selection
    // toward bins whose waste matches the observed fragment scale.
    if fitting_bins_count > 1 && post_residual > 0 && mean_residual > 0.0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist <= 4.0 {
            score -= 16.0 * (1.0 - dist / 4.0);
        }
    }

    // NEW: Triple-exact sweep — current item plus next item plus a
    // second copy of the next item exactly closes the bin; a decisive
    // three-item plan that should dominate all competing placements.
    if next_item_size > 0 && bin_residual >= item_size + 2 * next_item_size {
        let t3 = bin_residual - (item_size + 2 * next_item_size);
        if t3 == 0 {
            score -= 120.0;
        } else if t3 <= 3 {
            score -= 48.0;
        }
    }

    // NEW: Late-stream zero-waste surge — in the final quarter, an exact
    // close is worth even more because every avoided bin directly cuts
    // the total; scale the perfect-fit reward by progress.
    if post_residual == 0 && progress > 0.75 {
        score -= 90.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
            score -= 32.0;
        }
    }

    // Pair exactness — residual exactly equals current+next is a jackpot.
    if pair > 0 && bin_residual == pair {
        score -= 266.0;
    }

    // Multi-fill potential — how many additional items of next size could
    // still land in this bin after the current one. More = better consolidation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let multi = post_residual / next_item_size;
        if multi >= 2 {
            score -= 22.0 * (multi.min(4) as f64);
        }
    }

    // Reusability shaping: leftover between ~15% and ~45% of capacity is highly reusable.
    if post_residual > 0 {
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 30.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
    }

    // Exact-complement chain — post_residual can exactly absorb next item
    // plus another known-size chunk; near-perfect plan, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 68.0;
        }
    }

    // Avoid leaving residuals just below the next item size (dead pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax — residuals too small for most item classes
    // (1..=9) are almost guaranteed waste; scale penalty with depth.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
    }

    // Harmonic-fit bonus — post_residual matching common complements of
    // typical item sizes (multiples of 25 or 50) stays fillable.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0) {
        score -= 35.0;
    }

    // Mid-band residual shaping — reward exactly-fillable remainders,
    // punish near-miss remainders just above the next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
    }

    // Fit-quality gradient among competing bins — push selection toward
    // the bin whose placement leaves the smallest post_residual relative
    // to the item's own class.
    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 58.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Three-item chain check — current + next + a small filler (1..=10)
    // exactly fills this bin's residual; an exceptionally strong plan.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let chain = bin_residual - item_size - next_item_size;
        if chain >= 1 && chain <= 10 {
            score -= 88.0;
        }
    }

    // Two-step exactness — after placing the current item, check whether
    // post_residual can absorb next_item_size AND a mid-class filler exactly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 15 && after_next <= 45 && after_next % 5 == 0 {
            score -= 36.0;
        }
        if after_next > 0 && after_next < 10 {
            score += 26.0;
        }
    }

    // Residual-fragmentation tax — when many open bins exist, leaving a
    // mid-sized residual (fragment) spreads waste across bins; consolidate.
    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        // When open bins exist but every fit is poor (large item, tiny residuals),
        // opening fresh is cheaper than shattering a usable residual.
        if fitting_bins_count > 0 && item_size > bin_capacity / 3 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 45.0 * (1.0 - progress);
            }
        }
        // Protect big pockets late in the stream.
        if fitting_bins_count > 0 && progress > 0.4 && item_size <= bin_capacity / 3 {
            if mean_residual < item_size as f64 * 1.5 {
                score -= 27.0 * progress;
            }
        }
        // If the next item is large and no open bin could hold it after
        // this placement, opening a fresh bin now preserves flexibility.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            if post_residual < next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin discipline — opening a new bin late wastes
        // capacity unless the item is big; penalize small-item new bins late.
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Mid-stream fresh-bin restraint — between 25% and 60% progress,
        // small items should almost never open fresh bins while any fit exists.
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        // Endgame fresh-bin economy — in the final 15% of the stream,
        // opening a fresh bin for a small item is almost pure waste.
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        // Pair-fit gate — if this fresh bin can absorb BOTH the current
        // and the next item exactly, opening it is a genuine plan, not waste.
        if pair > 0 && bin_residual >= pair {
            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
                score -= 98.0;
            }
        }
        // Dead-pocket escape — when the best available fit would leave a
        // residual too small for any plausible item (<= 9), a fresh bin
        // with a full residual is strictly better than shattering the pocket.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 9 {
            score -= 90.0 * (1.0 - progress).max(0.2);
        }
        // Next-item dead-pocket escape — if the current fit would leave a
        // residual just below next_item_size (unusable by the immediate
        // successor), a fresh bin preserves that space for the successor.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score -= 62.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin exact-pair plan — opening a bin whose capacity is
        // exactly current + next (or within 2) is a perfect two-item plan.
        if next_item_size > 0 {
            let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
            if diff >= 0 && diff <= 2 {
                score -= 112.0;
            }
        }
        // Oversized-item fresh-bin sharpening — items above 60% of capacity
        // almost never share a bin; when any open bin would be shattered to
        // a near-dead pocket (< 15 left), prefer the fresh bin aggressively.
        if fitting_bins_count > 0 && item_size * 5 > bin_capacity * 3 {
            if post_residual > 0 && post_residual < 15 {
                score -= 52.0;
            }
        }
        // Fresh-bin tileability — if the fresh bin's capacity can be
        // tiled by the next item repeated k>=2 times after this placement,
        // opening it now is a multi-item consolidation plan.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let after = bin_capacity - item_size;
            if after % next_item_size == 0 && after / next_item_size >= 2 {
                score -= 44.0;
            }
        }
        // Fresh-bin fragment-consolidation — when open bins hold many
        // small scattered fragments (low mean residual, many bins), opening
        // one fresh bin for a large item keeps those fragments intact for
        // the many small items that follow, instead of burning the single
        // large pocket that remains.
        if fitting_bins_count > 0 && open_bins_count > 3 && item_size > bin_capacity / 2 {
            if mean_residual < item_size as f64 * 1.2 {
                score -= 40.0 * (1.0 - progress).max(0.25);
            }
        }
        // Fresh-bin mid-fit gate — when an open-bin fit would leave a
        // residual in the awkward 30..=45 band (too big to die, too small
        // to tile reliably) while the fresh bin can hold current+next with
        // slack <= 10, prefer the fresh bin as a deliberate two-item plan.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= 30 && post_residual <= 45 {
            let fresh_slack = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_slack <= 10 {
                score -= 58.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin triple-tile plan — if the fresh bin can hold the
        // current item plus the next item twice with <= 5 slack, opening it
        // is a three-item consolidation that eliminates a whole future bin.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let t3 = bin_capacity - (item_size + 2 * next_item_size);
            if t3 <= 5 {
                score -= 74.0 * (1.0 - progress).max(0.4);
            }
        }
        // NEW: Fresh-bin dead-band escape widening — when the best open-bin
        // fit leaves a residual in the 10..=19 near-dead band (fillable only
        // by rare tiny items), a fresh bin is usually better; scale the
        // escape with how close the residual is to true dead space.
        if fitting_bins_count > 0 && post_residual >= 10 && post_residual <= 19 {
            score -= 34.0 * (1.0 - progress).max(0.35) * (20 - post_residual as i32) as f64 / 10.0;
        }
        score += 30.0 + 40.0 * progress;
    }

    // Waste-floor shaping for regular placements — when several bins fit,
    // a placement leaving a residual of 10..=19 is a near-dead pocket for
    // most distributions; tax it progressively (sharpened slope).
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 19 {
        score += 24.0 + (19 - post_residual as i32) as f64 * 4.0;
    }

    // Sub-next dead-band sharpening — when multiple bins fit, a placement
    // whose residual sits within 8 units below next_item_size is unusable
    // by the immediate successor; tax proportionally to closeness.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 8 {
            score += 14.0 + (8 - gap as i32) as f64 * 4.0;
        }
    }

    // Congestion: many open bins -> favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals from being consumed by small items late in stream.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Late-stream exactness boost — perfect/near-perfect fits matter more
    // when few items remain.
    let remaining_frac = 1.0 - progress;
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Divisibility-aware waste penalty — leftover that no multiple of any
    // plausible item class fills is taxed mildly.
    if post_residual > 0 && post_residual < bin_capacity {
        let cls = (post_residual / 10).max(1);
        if post_residual % (cls * 10) != 0 && post_residual < 50 {
            score += 11.0;
        }
    }

    // Exact-fill lookahead sweep — reward placements where the residual
    // after this item can be tiled exactly by the next item repeated k
    // times (k >= 1) with zero leftover.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // Post-residual reusability vs. mean coupling — a leftover close to
    // the stream's mean residual is statistically most likely to be reused
    // later; reward closeness, punish outliers among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 22.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
    }

    // Dead-zone gradient refinement — residuals in the 20..=34 band are
    // only fillable by mid-class items; when the next item is small
    // (<= 10), such residuals are likely to survive untapped.
    if post_residual >= 20 && post_residual <= 34 && next_item_size > 0 && next_item_size <= 10 {
        score += 16.0;
    }

    // Two-bin exact-split plan — when exactly two bins fit and this
    // placement leaves a residual that exactly equals next_item_size, it
    // is a perfect handoff; reward it beyond the generic lookahead bonus.
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0;
    }

    // Residual-value discount for large leftovers consumed by small
    // items — placing a tiny item into a big pocket destroys future
    // packing potential; scale the tax with the destroyed fraction.
    if post_residual > 0 && item_size > 0 && bin_residual > item_size {
        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Dead-space budget coupling — when the mean residual across open bins
    // is already high, leaving yet another mid-range leftover compounds
    // waste; tax placements whose post_residual both exceeds the mean and
    // sits in the hard-to-fill 10..=29 band.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Near-perfect-fit gradient sharpening — among competing bins, a
    // post_residual of exactly 1..=2 is nearly a perfect fill; reward it
    // beyond the flat tier so the tightest bin wins decisively.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    // Dual-lookahead consolidation — when the current item and the
    // next-item pair leave a residual within a small-filler band of
    // zero, prefer this bin strongly.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // Waste-gap interpolation — among competing bins, prefer the bin
    // whose post_residual sits on a reusable band boundary (multiple of
    // 10), taxing residuals stranded mid-band between classes.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual < 60 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 14.0;
        } else if m >= 7 {
            score += 6.0 + (m - 7) as f64 * 3.0;
        }
    }

    // Triple-chain consolidation — when the current item plus the
    // next item leaves a residual exactly tileable by a third plausible
    // chunk (next_item_size again or a class multiple), this bin is a
    // full three-item plan; reward it decisively.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 0 && (after_pair == next_item_size || after_pair % 10 == 0) {
            score -= 46.0;
        }
    }

    // Combined fine-grained residual + lookahead: when many bins fit and
    // this placement leaves a residual that both is small in absolute
    // terms AND can absorb the next item, consolidate decisively here.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Class-aware dead-zone tax — a leftover whose size sits strictly
    // between the next item's class boundary and the next class floor is
    // unlikely to be filled by anything arriving soon; tax it in proportion
    // to how far it overshoots the next item, but only when alternatives
    // exist (multiple fitting bins), so unique fits stay untouched.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting — in the final third of the
    // stream, prefer placements that leave a residual exactly reusable by
    // the next item even at the cost of a slightly larger current fit;
    // chains of exact handoffs eliminate trailing waste bins.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation — when many bins are open,
    // the tightest fit matters more because each leftover fragment is
    // another bin that may never close; sharpen the tight-fit gradient
    // with open_bins_count so crowded states converge to best-fit harder.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket — a post_residual that falls
    // within [next_item_size, next_item_size + 3] is a guaranteed reuse
    // for the immediate successor; reward it progressively beyond the
    // generic slack bonus, strongest when few bins fit (scarce space).
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain — in the final 20% of the stream,
    // small items (<= 12) should preferentially drain the bin with the
    // SMALLEST residual they can fit, preserving large pockets for the
    // remaining medium/large items; tax placements into big pockets.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — if this placement closes the bin exactly
    // AND the next item also fits the residual after being added (i.e. a
    // two-item exact close), reward decisively regardless of bin count.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // NEW: Endgame drain targeting — in the final quarter, prefer draining
    // the bin whose post-residual is smallest overall (tightest absolute
    // closure), scaled by how little of the stream remains.
    if progress > 0.75 && post_residual > 0 {
        score += (post_residual as f64) * 0.55 * (progress - 0.75) * 4.0;
    }

    // NEW: Two-item exact closure gradient — when the current item plus
    // the next item exactly closes this bin, it is the strongest possible
    // plan; extend the reward to near-exact closures (slack 1..=3) with a
    // decaying bonus so near-perfect two-item plans beat generic fits.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let slack2 = bin_residual - item_size - next_item_size;
        if slack2 >= 1 && slack2 <= 3 {
            score -= 70.0 - (slack2 as f64) * 12.0;
        }
    }

    // NEW: Mean-residual anchored pocket reuse — a leftover that both
    // exceeds next_item_size and lands within a tight window around the
    // stream's mean residual is highly likely to be consumed by a future
    // item of typical size; reward this statistical sweet spot.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let anchor = (post_residual as f64 - mean_residual).abs();
        if anchor <= 10.0 && post_residual - next_item_size <= 15 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
            score -= 32.0;
        }
    }

    // Pair exactness — residual exactly equals current+next is a jackpot.
    if pair > 0 && bin_residual == pair {
        score -= 266.0;
    }

    // Multi-fill potential — how many additional items of next size could
    // still land in this bin after the current one. More = better consolidation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let multi = post_residual / next_item_size;
        if multi >= 2 {
            score -= 22.0 * (multi.min(4) as f64);
        }
    }

    // Reusability shaping: leftover between ~15% and ~45% of capacity is highly reusable.
    if post_residual > 0 {
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 30.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
    }

    // Exact-complement chain — post_residual can exactly absorb next item
    // plus another known-size chunk; near-perfect plan, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 68.0;
        }
    }

    // Avoid leaving residuals just below the next item size (dead pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax — residuals too small for most item classes
    // (1..=9) are almost guaranteed waste; scale penalty with depth.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
    }

    // Harmonic-fit bonus — post_residual matching common complements of
    // typical item sizes (multiples of 25 or 50) stays fillable.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0) {
        score -= 35.0;
    }

    // Mid-band residual shaping — reward exactly-fillable remainders,
    // punish near-miss remainders just above the next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
    }

    // Fit-quality gradient among competing bins — push selection toward
    // the bin whose placement leaves the smallest post_residual relative
    // to the item's own class.
    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 58.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Three-item chain check — current + next + a small filler (1..=10)
    // exactly fills this bin's residual; an exceptionally strong plan.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let chain = bin_residual - item_size - next_item_size;
        if chain >= 1 && chain <= 10 {
            score -= 88.0;
        }
    }

    // Two-step exactness — after placing the current item, check whether
    // post_residual can absorb next_item_size AND a mid-class filler exactly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 15 && after_next <= 45 && after_next % 5 == 0 {
            score -= 36.0;
        }
        if after_next > 0 && after_next < 10 {
            score += 26.0;
        }
    }

    // Residual-fragmentation tax — when many open bins exist, leaving a
    // mid-sized residual (fragment) spreads waste across bins; consolidate.
    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        // When open bins exist but every fit is poor (large item, tiny residuals),
        // opening fresh is cheaper than shattering a usable residual.
        if fitting_bins_count > 0 && item_size > bin_capacity / 3 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 45.0 * (1.0 - progress);
            }
        }
        // Protect big pockets late in the stream.
        if fitting_bins_count > 0 && progress > 0.4 && item_size <= bin_capacity / 3 {
            if mean_residual < item_size as f64 * 1.5 {
                score -= 27.0 * progress;
            }
        }
        // If the next item is large and no open bin could hold it after
        // this placement, opening a fresh bin now preserves flexibility.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            if post_residual < next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin discipline — opening a new bin late wastes
        // capacity unless the item is big; penalize small-item new bins late.
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Mid-stream fresh-bin restraint — between 25% and 60% progress,
        // small items should almost never open fresh bins while any fit exists.
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        // Endgame fresh-bin economy — in the final 15% of the stream,
        // opening a fresh bin for a small item is almost pure waste.
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        // Pair-fit gate — if this fresh bin can absorb BOTH the current
        // and the next item exactly, opening it is a genuine plan, not waste.
        if pair > 0 && bin_residual >= pair {
            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
                score -= 98.0;
            }
        }
        // Dead-pocket escape — when the best available fit would leave a
        // residual too small for any plausible item (<= 9), a fresh bin
        // with a full residual is strictly better than shattering the pocket.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 9 {
            score -= 90.0 * (1.0 - progress).max(0.2);
        }
        // Next-item dead-pocket escape — if the current fit would leave a
        // residual just below next_item_size (unusable by the immediate
        // successor), a fresh bin preserves that space for the successor.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score -= 62.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin exact-pair plan — opening a bin whose capacity is
        // exactly current + next (or within 2) is a perfect two-item plan.
        if next_item_size > 0 {
            let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
            if diff >= 0 && diff <= 2 {
                score -= 112.0;
            }
        }
        // Oversized-item fresh-bin sharpening — items above 60% of capacity
        // almost never share a bin; when any open bin would be shattered to
        // a near-dead pocket (< 15 left), prefer the fresh bin aggressively.
        if fitting_bins_count > 0 && item_size * 5 > bin_capacity * 3 {
            if post_residual > 0 && post_residual < 15 {
                score -= 52.0;
            }
        }
        // Fresh-bin tileability — if the fresh bin's capacity can be
        // tiled by the next item repeated k>=2 times after this placement,
        // opening it now is a multi-item consolidation plan.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let after = bin_capacity - item_size;
            if after % next_item_size == 0 && after / next_item_size >= 2 {
                score -= 44.0;
            }
        }
        // Fresh-bin fragment-consolidation — when open bins hold many
        // small scattered fragments (low mean residual, many bins), opening
        // one fresh bin for a large item keeps those fragments intact for
        // the many small items that follow, instead of burning the single
        // large pocket that remains.
        if fitting_bins_count > 0 && open_bins_count > 3 && item_size > bin_capacity / 2 {
            if mean_residual < item_size as f64 * 1.2 {
                score -= 40.0 * (1.0 - progress).max(0.25);
            }
        }
        // Fresh-bin mid-fit gate — when an open-bin fit would leave a
        // residual in the awkward 30..=45 band while the fresh bin can hold
        // current+next with slack <= 10, prefer the fresh bin.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= 30 && post_residual <= 45 {
            let fresh_slack = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_slack <= 10 {
                score -= 58.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin triple-tile plan — if the fresh bin can hold the
        // current item plus the next item twice with <= 5 slack, opening it
        // is a three-item consolidation that eliminates a whole future bin.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let t3 = bin_capacity - (item_size + 2 * next_item_size);
            if t3 <= 5 {
                score -= 74.0 * (1.0 - progress).max(0.4);
            }
        }
        // NEW: Fresh-bin best-fit comparison — when the mean slack across
        // open bins after this placement would be worse than the fresh
        // bin's own leftover (capacity - item), opening fresh wastes less.
        if fitting_bins_count > 0 && post_residual > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size);
            if fresh_left + 12 < post_residual && item_size >= bin_capacity / 3 {
                score -= 48.0 * (1.0 - progress).max(0.3);
            }
        }
        score += 30.0 + 40.0 * progress;
    }

    // Waste-floor shaping for regular placements — when several bins fit,
    // a placement leaving a residual of 10..=19 is a near-dead pocket for
    // most distributions; tax it progressively (sharpened slope).
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 19 {
        score += 24.0 + (19 - post_residual as i32) as f64 * 4.0;
    }

    // Sub-next dead-band sharpening — when multiple bins fit, a placement
    // whose residual sits within 8 units below next_item_size is unusable
    // by the immediate successor; tax proportionally to closeness.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 8 {
            score += 14.0 + (8 - gap as i32) as f64 * 4.0;
        }
    }

    // Congestion: many open bins -> favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals from being consumed by small items late in stream.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Late-stream exactness boost — perfect/near-perfect fits matter more
    // when few items remain.
    let remaining_frac = 1.0 - progress;
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Divisibility-aware waste penalty — leftover that no multiple of any
    // plausible item class fills is taxed mildly.
    if post_residual > 0 && post_residual < bin_capacity {
        let cls = (post_residual / 10).max(1);
        if post_residual % (cls * 10) != 0 && post_residual < 50 {
            score += 11.0;
        }
    }

    // Exact-fill lookahead sweep — reward placements where the residual
    // after this item can be tiled exactly by the next item repeated k
    // times (k >= 1) with zero leftover.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // Post-residual reusability vs. mean coupling — a leftover close to
    // the stream's mean residual is statistically most likely to be reused
    // later; reward closeness, punish outliers among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 22.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
    }

    // Dead-zone gradient refinement — residuals in the 20..=34 band are
    // only fillable by mid-class items; when the next item is small
    // (<= 10), such residuals are likely to survive untapped.
    if post_residual >= 20 && post_residual <= 34 && next_item_size > 0 && next_item_size <= 10 {
        score += 16.0;
    }

    // Two-bin exact-split plan — when exactly two bins fit and this
    // placement leaves a residual that exactly equals next_item_size, it
    // is a perfect handoff; reward it beyond the generic lookahead bonus.
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0;
    }

    // Residual-value discount for large leftovers consumed by small
    // items — placing a tiny item into a big pocket destroys future
    // packing potential; scale the tax with the destroyed fraction.
    if post_residual > 0 && item_size > 0 && bin_residual > item_size {
        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Dead-space budget coupling — when the mean residual across open bins
    // is already high, leaving yet another mid-range leftover compounds
    // waste; tax placements whose post_residual both exceeds the mean and
    // sits in the hard-to-fill 10..=29 band.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Near-perfect-fit gradient sharpening — among competing bins, a
    // post_residual of exactly 1..=2 is nearly a perfect fill; reward it
    // beyond the flat tier so the tightest bin wins decisively.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    // Dual-lookahead consolidation — when the current item and the
    // next-item pair leave a residual within a small-filler band of
    // zero, prefer this bin strongly.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // Waste-gap interpolation — among competing bins, prefer the bin
    // whose post_residual sits on a reusable band boundary (multiple of
    // 10), taxing residuals stranded mid-band between classes.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual < 60 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 14.0;
        } else if m >= 7 {
            score += 6.0 + (m - 7) as f64 * 3.0;
        }
    }

    // Triple-chain consolidation — when the current item plus the
    // next item leaves a residual exactly tileable by a third plausible
    // chunk (next_item_size again or a class multiple), this bin is a
    // full three-item plan; reward it decisively.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 0 && (after_pair == next_item_size || after_pair % 10 == 0) {
            score -= 46.0;
        }
    }

    // Combined fine-grained residual + lookahead: when many bins fit and
    // this placement leaves a residual that both is small in absolute
    // terms AND can absorb the next item, consolidate decisively here.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Class-aware dead-zone tax — a leftover whose size sits strictly
    // between the next item's class boundary and the next class floor is
    // unlikely to be filled by anything arriving soon; tax it in proportion
    // to how far it overshoots the next item, but only when alternatives
    // exist (multiple fitting bins), so unique fits stay untouched.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting — in the final third of the
    // stream, prefer placements that leave a residual exactly reusable by
    // the next item even at the cost of a slightly larger current fit;
    // chains of exact handoffs eliminate trailing waste bins.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation — when many bins are open,
    // the tightest fit matters more because each leftover fragment is
    // another bin that may never close; sharpen the tight-fit gradient
    // with open_bins_count so crowded states converge to best-fit harder.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket — a post_residual that falls
    // within [next_item_size, next_item_size + 3] is a guaranteed reuse
    // for the immediate successor; reward it progressively beyond the
    // generic slack bonus, strongest when few bins fit (scarce space).
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain — in the final 20% of the stream,
    // small items (<= 12) should preferentially drain the bin with the
    // SMALLEST residual they can fit, preserving large pockets for the
    // remaining medium/large items; tax placements into big pockets.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — if this placement closes the bin exactly
    // AND the next item also fits the residual after being added (i.e. a
    // two-item exact close), reward decisively regardless of bin count.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // NEW: Waste-floor gradient — among competing bins, scale the penalty
    // of any nonzero post_residual by how many bins fit; when many bins
    // fit, even small leftovers should be avoided harder, pushing the
    // selection toward the truly tightest bin.
    if fitting_bins_count > 1 && post_residual > 0 {
        score += (post_residual as f64) * (fitting_bins_count.min(8) as f64) * 0.12;
    }

    // NEW: Mean-residual-targeted reuse — a placement whose post_residual
    // lands within 3 of the mean open-bin residual is statistically the
    // most likely to be exactly consumed by a future item; reward it,
    // scaled by remaining stream (more future = more value).
    if fitting_bins_count > 1 && post_residual > 0 {
        let d = ((post_residual as f64) - mean_residual).abs();
        if d <= 3.0 {
            score -= 18.0 * remaining_frac.max(0.2);
        }
    }

    // NEW: Mid-band tileability check — post_residual that is a multiple
    // of next_item_size within a small overshoot (<= 4) can be drained by
    // a run of next items plus one filler; reward this hybrid plan.
    if next_item_size > 1 && post_residual > next_item_size {
        let over = post_residual % next_item_size;
        if over > 0 && over <= 4 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
            score -= 32.0;
        }
    }

    // Pair exactness — residual exactly equals current+next is a jackpot.
    if pair > 0 && bin_residual == pair {
        score -= 266.0;
    }

    // Multi-fill potential — how many additional items of next size could
    // still land in this bin after the current one. More = better consolidation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let multi = post_residual / next_item_size;
        if multi >= 2 {
            score -= 22.0 * (multi.min(4) as f64);
        }
    }

    // Reusability shaping: leftover between ~15% and ~45% of capacity is highly reusable.
    if post_residual > 0 {
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 30.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
    }

    // Exact-complement chain — post_residual can exactly absorb next item
    // plus another known-size chunk; near-perfect plan, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 68.0;
        }
    }

    // Avoid leaving residuals just below the next item size (dead pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax — residuals too small for most item classes
    // (1..=9) are almost guaranteed waste; scale penalty with depth.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
    }

    // Harmonic-fit bonus — post_residual matching common complements of
    // typical item sizes (multiples of 25 or 50) stays fillable.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0) {
        score -= 35.0;
    }

    // Mid-band residual shaping — reward exactly-fillable remainders,
    // punish near-miss remainders just above the next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
    }

    // Fit-quality gradient among competing bins — push selection toward
    // the bin whose placement leaves the smallest post_residual relative
    // to the item's own class.
    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 58.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Three-item chain check — current + next + a small filler (1..=10)
    // exactly fills this bin's residual; an exceptionally strong plan.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let chain = bin_residual - item_size - next_item_size;
        if chain >= 1 && chain <= 10 {
            score -= 88.0;
        }
    }

    // Two-step exactness — after placing the current item, check whether
    // post_residual can absorb next_item_size AND a mid-class filler exactly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 15 && after_next <= 45 && after_next % 5 == 0 {
            score -= 36.0;
        }
        if after_next > 0 && after_next < 10 {
            score += 26.0;
        }
    }

    // Residual-fragmentation tax — when many open bins exist, leaving a
    // mid-sized residual (fragment) spreads waste across bins; consolidate.
    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        // When open bins exist but every fit is poor (large item, tiny residuals),
        // opening fresh is cheaper than shattering a usable residual.
        if fitting_bins_count > 0 && item_size > bin_capacity / 3 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 45.0 * (1.0 - progress);
            }
        }
        // Protect big pockets late in the stream.
        if fitting_bins_count > 0 && progress > 0.4 && item_size <= bin_capacity / 3 {
            if mean_residual < item_size as f64 * 1.5 {
                score -= 27.0 * progress;
            }
        }
        // If the next item is large and no open bin could hold it after
        // this placement, opening a fresh bin now preserves flexibility.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            if post_residual < next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin discipline — opening a new bin late wastes
        // capacity unless the item is big; penalize small-item new bins late.
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Mid-stream fresh-bin restraint — between 25% and 60% progress,
        // small items should almost never open fresh bins while any fit exists.
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        // Endgame fresh-bin economy — in the final 15% of the stream,
        // opening a fresh bin for a small item is almost pure waste.
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        // Pair-fit gate — if this fresh bin can absorb BOTH the current
        // and the next item exactly, opening it is a genuine plan, not waste.
        if pair > 0 && bin_residual >= pair {
            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
                score -= 98.0;
            }
        }
        // Dead-pocket escape — when the best available fit would leave a
        // residual too small for any plausible item (<= 9), a fresh bin
        // with a full residual is strictly better than shattering the pocket.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 9 {
            score -= 90.0 * (1.0 - progress).max(0.2);
        }
        // Next-item dead-pocket escape — if the current fit would leave a
        // residual just below next_item_size (unusable by the immediate
        // successor), a fresh bin preserves that space for the successor.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score -= 62.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin exact-pair plan — opening a bin whose capacity is
        // exactly current + next (or within 2) is a perfect two-item plan.
        if next_item_size > 0 {
            let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
            if diff >= 0 && diff <= 2 {
                score -= 112.0;
            }
        }
        // Oversized-item fresh-bin sharpening — items above 60% of capacity
        // almost never share a bin; when any open bin would be shattered to
        // a near-dead pocket (< 15 left), prefer the fresh bin aggressively.
        if fitting_bins_count > 0 && item_size * 5 > bin_capacity * 3 {
            if post_residual > 0 && post_residual < 15 {
                score -= 52.0;
            }
        }
        // Fresh-bin tileability — if the fresh bin's capacity can be
        // tiled by the next item repeated k>=2 times after this placement,
        // opening it now is a multi-item consolidation plan.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let after = bin_capacity - item_size;
            if after % next_item_size == 0 && after / next_item_size >= 2 {
                score -= 44.0;
            }
        }
        // Fresh-bin fragment-consolidation — when open bins hold many
        // small scattered fragments (low mean residual, many bins), opening
        // one fresh bin for a large item keeps those fragments intact for
        // the many small items that follow, instead of burning the single
        // large pocket that remains.
        if fitting_bins_count > 0 && open_bins_count > 3 && item_size > bin_capacity / 2 {
            if mean_residual < item_size as f64 * 1.2 {
                score -= 40.0 * (1.0 - progress).max(0.25);
            }
        }
        // Fresh-bin mid-fit gate — when an open-bin fit would leave a
        // residual in the awkward 30..=45 band (too big to die, too small
        // to tile reliably) while the fresh bin can hold current+next with
        // slack <= 10, prefer the fresh bin as a deliberate two-item plan.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= 30 && post_residual <= 45 {
            let fresh_slack = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_slack <= 10 {
                score -= 58.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin triple-tile plan — if the fresh bin can hold the
        // current item plus the next item twice with <= 5 slack, opening it
        // is a three-item consolidation that eliminates a whole future bin.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let t3 = bin_capacity - (item_size + 2 * next_item_size);
            if t3 <= 5 {
                score -= 74.0 * (1.0 - progress).max(0.4);
            }
        }
        score += 30.0 + 40.0 * progress;
    }

    // Waste-floor shaping for regular placements — when several bins fit,
    // a placement leaving a residual of 10..=19 is a near-dead pocket for
    // most distributions; tax it progressively (sharpened slope).
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 19 {
        score += 24.0 + (19 - post_residual as i32) as f64 * 4.0;
    }

    // Sub-next dead-band sharpening — when multiple bins fit, a placement
    // whose residual sits within 8 units below next_item_size is unusable
    // by the immediate successor; tax proportionally to closeness.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 8 {
            score += 14.0 + (8 - gap as i32) as f64 * 4.0;
        }
    }

    // Congestion: many open bins -> favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals from being consumed by small items late in stream.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Late-stream exactness boost — perfect/near-perfect fits matter more
    // when few items remain.
    let remaining_frac = 1.0 - progress;
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Divisibility-aware waste penalty — leftover that no multiple of any
    // plausible item class fills is taxed mildly.
    if post_residual > 0 && post_residual < bin_capacity {
        let cls = (post_residual / 10).max(1);
        if post_residual % (cls * 10) != 0 && post_residual < 50 {
            score += 11.0;
        }
    }

    // Exact-fill lookahead sweep — reward placements where the residual
    // after this item can be tiled exactly by the next item repeated k
    // times (k >= 1) with zero leftover.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // Post-residual reusability vs. mean coupling — a leftover close to
    // the stream's mean residual is statistically most likely to be reused
    // later; reward closeness, punish outliers among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 22.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
    }

    // Dead-zone gradient refinement — residuals in the 20..=34 band are
    // only fillable by mid-class items; when the next item is small
    // (<= 10), such residuals are likely to survive untapped.
    if post_residual >= 20 && post_residual <= 34 && next_item_size > 0 && next_item_size <= 10 {
        score += 16.0;
    }

    // Two-bin exact-split plan — when exactly two bins fit and this
    // placement leaves a residual that exactly equals next_item_size, it
    // is a perfect handoff; reward it beyond the generic lookahead bonus.
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0;
    }

    // Residual-value discount for large leftovers consumed by small
    // items — placing a tiny item into a big pocket destroys future
    // packing potential; scale the tax with the destroyed fraction.
    if post_residual > 0 && item_size > 0 && bin_residual > item_size {
        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Dead-space budget coupling — when the mean residual across open bins
    // is already high, leaving yet another mid-range leftover compounds
    // waste; tax placements whose post_residual both exceeds the mean and
    // sits in the hard-to-fill 10..=29 band.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Near-perfect-fit gradient sharpening — among competing bins, a
    // post_residual of exactly 1..=2 is nearly a perfect fill; reward it
    // beyond the flat tier so the tightest bin wins decisively.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    // Dual-lookahead consolidation — when the current item and the
    // next-item pair leave a residual within a small-filler band of
    // zero, prefer this bin strongly.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // Waste-gap interpolation — among competing bins, prefer the bin
    // whose post_residual sits on a reusable band boundary (multiple of
    // 10), taxing residuals stranded mid-band between classes.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual < 60 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 14.0;
        } else if m >= 7 {
            score += 6.0 + (m - 7) as f64 * 3.0;
        }
    }

    // Triple-chain consolidation — when the current item plus the
    // next item leaves a residual exactly tileable by a third plausible
    // chunk (next_item_size again or a class multiple), this bin is a
    // full three-item plan; reward it decisively.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 0 && (after_pair == next_item_size || after_pair % 10 == 0) {
            score -= 46.0;
        }
    }

    // Combined fine-grained residual + lookahead: when many bins fit and
    // this placement leaves a residual that both is small in absolute
    // terms AND can absorb the next item, consolidate decisively here.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Class-aware dead-zone tax — a leftover whose size sits strictly
    // between the next item's class boundary and the next class floor is
    // unlikely to be filled by anything arriving soon; tax it in proportion
    // to how far it overshoots the next item, but only when alternatives
    // exist (multiple fitting bins), so unique fits stay untouched.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting — in the final third of the
    // stream, prefer placements that leave a residual exactly reusable by
    // the next item even at the cost of a slightly larger current fit;
    // chains of exact handoffs eliminate trailing waste bins.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation — when many bins are open,
    // the tightest fit matters more because each leftover fragment is
    // another bin that may never close; sharpen the tight-fit gradient
    // with open_bins_count so crowded states converge to best-fit harder.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket — a post_residual that falls
    // within [next_item_size, next_item_size + 3] is a guaranteed reuse
    // for the immediate successor; reward it progressively beyond the
    // generic slack bonus, strongest when few bins fit (scarce space).
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain — in the final 20% of the stream,
    // small items (<= 12) should preferentially drain the bin with the
    // SMALLEST residual they can fit, preserving large pockets for the
    // remaining medium/large items; tax placements into big pockets.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — if this placement closes the bin exactly
    // AND the next item also fits the residual after being added (i.e. a
    // two-item exact close), reward decisively regardless of bin count.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // NEW (gen 17): Residual-variance compression — diagnosed weakness is
    // suboptimal residual space. When many bins are open, placements whose
    // post_residual lands near the mean residual keep the fragment
    // distribution tight, making future small items fillable almost
    // everywhere; reward alignment, punish fragment outliers harder as
    // congestion grows.
    if open_bins_count > 3 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        let congestion = ((open_bins_count as f64).min(12.0)) / 12.0;
        if dist <= 10.0 {
            score -= 12.0 * congestion;
        } else if dist > 25.0 {
            score += 8.0 * congestion * ((dist - 25.0) / 20.0).min(1.5);
        }
    }

    // NEW (gen 17): Post-residual tileability sweep — a leftover that can
    // be tiled exactly by the next item k>=2 times means this bin becomes
    // a full multi-item plan; reward grows with k and with stream progress
    // (chains matter most when few items remain to complete them).
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= (14.0 + 18.0 * progress) * (k.min(4) as f64);
        }
    }

    // NEW (gen 17): Near-exact closure gradient — among competing bins,
    // residuals of 3..=5 are the second-best outcome after exact fills;
    // sharpen the tier so the tightest of several near-closures wins, and
    // escalate the reward as the stream nears its end (trailing waste is
    // what separates 4060 from 3992 bins).
    if fitting_bins_count > 1 && post_residual >= 3 && post_residual <= 5 {
        score -= 30.0 + 40.0 * progress;
    }

    // NEW (gen 17): Dead-pocket anti-shatter guard — when only one bin
