        }
    }

    // Dead-space budget coupling — high mean residual + hard-to-fill band.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Near-perfect-fit gradient sharpening — post_residual of 1..=2 wins.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    // Dual-lookahead consolidation — pair leaves residual within small
    // filler band of zero.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // Waste-gap interpolation — prefer residuals on reusable band boundaries.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual < 60 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 14.0;
        } else if m >= 7 {
            score += 6.0 + (m - 7) as f64 * 3.0;
        }
    }

    // Triple-chain consolidation — three-item plan reward.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 0 && (after_pair == next_item_size || after_pair % 10 == 0) {
            score -= 46.0;
        }
    }

    // Combined fine-grained residual + lookahead: consolidate decisively.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Class-aware dead-zone tax — leftover strictly between next item's
    // class boundary and the next class floor is unlikely to be filled.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting — exact handoffs eliminate trailing
    // waste bins.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation — crowded states converge to
    // best-fit harder.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket — guaranteed reuse for the successor.
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain — small items should preferentially
    // drain the bin with the smallest residual they can fit.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — two-item exact close reward.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // NEW (gen 17): Tight-fit scarcity gradient — when only a handful of
    // bins can fit the item, the tightest fit matters disproportionately;
    // scale the near-perfect tier bonus with scarcity so scarce-space
    // states lock in the best available fit rather than leaving fragments.
    if fitting_bins_count >= 1 && fitting_bins_count <= 3 && post_residual > 0 && post_residual <= 6 {
        score -= 24.0 * (4 - fitting_bins_count as i32).max(1) as f64;
    }

    // NEW (gen 17): Mid-band tileability sweep — a post_residual that can
    // be tiled by next_item_size with small slack (<= 3) is a planned
    // continuation; reward it beyond the generic divisibility bonus.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem > 0 && rem <= 3 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

