        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
    }

    // Harmonic-fit bonus.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0) {
        score -= 35.0;
    }

    // Mid-band residual shaping (borrowed from best).
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
    }

    // Fit-quality gradient among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 58.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Three-item chain check with small filler.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let chain = bin_residual - item_size - next_item_size;
        if chain >= 1 && chain <= 10 {
            score -= 88.0;
        }
    }

    // Two-step exactness after next item.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 15 && after_next <= 45 && after_next % 5 == 0 {
            score -= 36.0;
        }
        if after_next > 0 && after_next < 10 {
            score += 26.0;
        }
    }

    // Residual-fragmentation tax.
    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let remaining_frac = 1.0 - progress;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        if fitting_bins_count > 0 && item_size > bin_capacity / 3 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 45.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count > 0 && progress > 0.4 && item_size <= bin_capacity / 3 {
            if mean_residual < item_size as f64 * 1.5 {
                score -= 27.0 * progress;
            }
        }
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            if post_residual < next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
        }
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        // Pair-fit gate for fresh bin.
        if pair > 0 && bin_residual >= pair {
            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
                score -= 98.0;
            }
        }
        // Dead-pocket escape to fresh bin.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 9 {
            score -= 90.0 * (1.0 - progress).max(0.2);
        }
        // Next-item dead-pocket escape.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score -= 62.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin exact-pair plan.
        if next_item_size > 0 {
            let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
            if diff >= 0 && diff <= 2 {
                score -= 112.0;
            }
        }
        // Oversized-item fresh-bin sharpening.
        if fitting_bins_count > 0 && item_size * 5 > bin_capacity * 3 {
            if post_residual > 0 && post_residual < 15 {
                score -= 52.0;
            }
        }
        // Fresh-bin tileability.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let after = bin_capacity - item_size;
            if after % next_item_size == 0 && after / next_item_size >= 2 {
                score -= 44.0;
            }
        }
        // Fragment-consolidation for large items.
        if fitting_bins_count > 0 && open_bins_count > 3 && item_size > bin_capacity / 2 {
            if mean_residual < item_size as f64 * 1.2 {
                score -= 40.0 * (1.0 - progress).max(0.25);
            }
        }
        // Mid-fit gate.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= 30 && post_residual <= 45 {
            let fresh_slack = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_slack <= 10 {
                score -= 58.0 * (1.0 - progress).max(0.3);
            }
        }
        // Triple-tile plan.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let t3 = bin_capacity - (item_size + 2 * next_item_size);
            if t3 <= 5 {
                score -= 74.0 * (1.0 - progress).max(0.4);
            }
        }
        score += 30.0 + 40.0 * progress;
    }

    // Waste-floor shaping.
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 19 {
        score += 24.0 + (19 - post_residual as i32) as f64 * 4.0;
    }

    // Sub-next dead-band sharpening.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 8 {
            score += 14.0 + (8 - gap as i32) as f64 * 4.0;
        }
    }

    // Congestion.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals late.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Late-stream exactness boost.
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Divisibility-aware waste penalty.
    if post_residual > 0 && post_residual < bin_capacity {
        let cls = (post_residual / 10).max(1);
        if post_residual % (cls * 10) != 0 && post_residual < 50 {
            score += 11.0;
        }
    }

    // Exact-fill lookahead sweep.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // Post-residual reusability vs. mean coupling.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 22.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
    }

    // Dead-zone gradient refinement.
    if post_residual >= 20 && post_residual <= 34 && next_item_size > 0 && next_item_size <= 10 {
        score += 16.0;
    }

    // Two-bin exact-split plan.
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0;
    }

    // Residual-value discount.
    if post_residual > 0 && item_size > 0 && bin_residual > item_size {
        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Dead-space budget coupling.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Near-perfect-fit gradient sharpening.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    // Dual-lookahead consolidation.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // Waste-gap interpolation.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual < 60 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 14.0;
        } else if m >= 7 {
            score += 6.0 + (m - 7) as f64 * 3.0;
        }
    }

    // Triple-chain consolidation.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 0 && (after_pair == next_item_size || after_pair % 10 == 0) {
            score -= 46.0;
        }
    }

    // Combined fine-grained residual + lookahead.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Class-aware dead-zone tax.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket.
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // Residual-efficiency gradient.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual <= 40 {
        score += (post_residual as f64) * 1.8;
    }

    // Next-item dead-space guard.
    if next_item_size > 0 && next_item_size <= 20 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.5;
    }

    // Crowded-state exact-close emphasis.
    if post_residual == 0 && open_bins_count > 3 {
        score -= 30.0 + (open_bins_count.min(12) as f64) * 4.0;
    }

    // NEW MUTATION: residual-band match to next-item class — a post_residual
    // that falls within the next item's size class band (multiple of 10
    // floor) is statistically reusable; reward closeness to that floor.
    if next_item_size > 0 && post_residual > 0 {
        let next_floor = ((next_item_size / 10) * 10).max(10);
        let d = post_residual as i64 - next_floor as i64;
        if d >= 0 && d <= 4 {
            score -= 20.0 - d as f64 * 3.0;
        }
    }

    // NEW MUTATION: smooth tight-fit tiebreaker — a continuous quadratic
    // waste term that dominates only when several bins fit, breaking ties
    // toward the smallest post_residual without distorting unique fits.
    if fitting_bins_count > 1 && post_residual > 0 {
        let pr = post_residual as f64;
        score += pr * pr * 0.012;
    }

    // NEW MUTATION: endgame exact-close surge — in the final 10% of the
    // stream, closing a bin exactly is nearly free capacity; amplify.
    if post_residual == 0 && progress > 0.9 {
        score -= 55.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
            score -= 32.0;
        }
    }

    // Pair exactness — residual exactly equals current+next is a jackpot.
    if pair > 0 && bin_residual == pair {
        score -= 266.0;
    }

    // Multi-fill potential — how many additional items of next size could
    // still land in this bin after the current one. More = better consolidation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let multi = post_residual / next_item_size;
        if multi >= 2 {
            score -= 22.0 * (multi.min(4) as f64);
        }
    }

    // Reusability shaping: leftover between ~15% and ~45% of capacity is highly reusable.
    if post_residual > 0 {
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 30.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
    }

    // Exact-complement chain — post_residual can exactly absorb next item
    // plus another known-size chunk; near-perfect plan, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 68.0;
        }
    }

    // Avoid leaving residuals just below the next item size (dead pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax — residuals too small for most item classes
    // (1..=9) are almost guaranteed waste; scale penalty with depth.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
    }

    // Harmonic-fit bonus — post_residual matching common complements of
    // typical item sizes (multiples of 25 or 50) stays fillable.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0) {
        score -= 35.0;
    }

    // Mid-band residual shaping — reward exactly-fillable remainders,
    // punish near-miss remainders just above the next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
    }

    // Fit-quality gradient among competing bins — push selection toward
    // the bin whose placement leaves the smallest post_residual relative
    // to the item's own class.
    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 58.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Three-item chain check — current + next + a small filler (1..=10)
    // exactly fills this bin's residual; an exceptionally strong plan.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let chain = bin_residual - item_size - next_item_size;
        if chain >= 1 && chain <= 10 {
            score -= 88.0;
        }
    }

    // Two-step exactness — after placing the current item, check whether
    // post_residual can absorb next_item_size AND a mid-class filler exactly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 15 && after_next <= 45 && after_next % 5 == 0 {
            score -= 36.0;
        }
        if after_next > 0 && after_next < 10 {
            score += 26.0;
        }
    }

    // Residual-fragmentation tax — when many open bins exist, leaving a
    // mid-sized residual (fragment) spreads waste across bins; consolidate.
    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        // When open bins exist but every fit is poor (large item, tiny residuals),
        // opening fresh is cheaper than shattering a usable residual.
        if fitting_bins_count > 0 && item_size > bin_capacity / 3 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 45.0 * (1.0 - progress);
            }
        }
        // Protect big pockets late in the stream.
        if fitting_bins_count > 0 && progress > 0.4 && item_size <= bin_capacity / 3 {
            if mean_residual < item_size as f64 * 1.5 {
                score -= 27.0 * progress;
            }
        }
        // If the next item is large and no open bin could hold it after
        // this placement, opening a fresh bin now preserves flexibility.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            if post_residual < next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin discipline — opening a new bin late wastes
        // capacity unless the item is big; penalize small-item new bins late.
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Mid-stream fresh-bin restraint — between 25% and 60% progress,
        // small items should almost never open fresh bins while any fit exists.
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        // Endgame fresh-bin economy — in the final 15% of the stream,
        // opening a fresh bin for a small item is almost pure waste.
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        // Pair-fit gate — if this fresh bin can absorb BOTH the current
        // and the next item exactly, opening it is a genuine plan, not waste.
        if pair > 0 && bin_residual >= pair {
            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
                score -= 98.0;
            }
        }
        // Dead-pocket escape — when the best available fit would leave a
        // residual too small for any plausible item (<= 9), a fresh bin
        // with a full residual is strictly better than shattering the pocket.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 9 {
            score -= 90.0 * (1.0 - progress).max(0.2);
        }
        // Next-item dead-pocket escape — if the current fit would leave a
        // residual just below next_item_size (unusable by the immediate
        // successor), a fresh bin preserves that space for the successor.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score -= 62.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin exact-pair plan — opening a bin whose capacity is
        // exactly current + next (or within 2) is a perfect two-item plan.
        if next_item_size > 0 {
            let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
            if diff >= 0 && diff <= 2 {
                score -= 112.0;
            }
        }
        // Oversized-item fresh-bin sharpening — items above 60% of capacity
        // almost never share a bin; when any open bin would be shattered to
        // a near-dead pocket (< 15 left), prefer the fresh bin aggressively.
        if fitting_bins_count > 0 && item_size * 5 > bin_capacity * 3 {
            if post_residual > 0 && post_residual < 15 {
                score -= 52.0;
            }
        }
        // Fresh-bin tileability — if the fresh bin's capacity can be
        // tiled by the next item repeated k>=2 times after this placement,
        // opening it now is a multi-item consolidation plan.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let after = bin_capacity - item_size;
            if after % next_item_size == 0 && after / next_item_size >= 2 {
                score -= 44.0;
            }
        }
        // Fresh-bin fragment-consolidation — when open bins hold many
        // small scattered fragments (low mean residual, many bins), opening
        // one fresh bin for a large item keeps those fragments intact for
        // the many small items that follow, instead of burning the single
        // large pocket that remains.
        if fitting_bins_count > 0 && open_bins_count > 3 && item_size > bin_capacity / 2 {
            if mean_residual < item_size as f64 * 1.2 {
                score -= 40.0 * (1.0 - progress).max(0.25);
            }
        }
        // Fresh-bin mid-fit gate — when an open-bin fit would leave a
        // residual in the awkward 30..=45 band while the fresh bin can
        // hold current+next with slack <= 10, prefer the fresh bin.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= 30 && post_residual <= 45 {
            let fresh_slack = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_slack <= 10 {
                score -= 58.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin triple-tile plan — if the fresh bin can hold the
        // current item plus the next item twice with <= 5 slack.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let t3 = bin_capacity - (item_size + 2 * next_item_size);
            if t3 <= 5 {
                score -= 74.0 * (1.0 - progress).max(0.4);
            }
        }
        score += 30.0 + 40.0 * progress;
    }

    // Waste-floor shaping for regular placements — when several bins fit,
    // a placement leaving a residual of 10..=19 is a near-dead pocket for
    // most distributions; tax it progressively (sharpened slope).
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 19 {
        score += 24.0 + (19 - post_residual as i32) as f64 * 4.0;
    }

    // Sub-next dead-band sharpening — when multiple bins fit, a placement
    // whose residual sits within 8 units below next_item_size is unusable
    // by the immediate successor; tax proportionally to closeness.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 8 {
            score += 14.0 + (8 - gap as i32) as f64 * 4.0;
        }
    }

    // Congestion: many open bins -> favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals from being consumed by small items late in stream.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Late-stream exactness boost — perfect/near-perfect fits matter more
    // when few items remain.
    let remaining_frac = 1.0 - progress;
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Divisibility-aware waste penalty — leftover that no multiple of any
    // plausible item class fills is taxed mildly.
    if post_residual > 0 && post_residual < bin_capacity {
        let cls = (post_residual / 10).max(1);
        if post_residual % (cls * 10) != 0 && post_residual < 50 {
            score += 11.0;
        }
    }

    // Exact-fill lookahead sweep — reward placements where the residual
    // after this item can be tiled exactly by the next item repeated k
    // times (k >= 1) with zero leftover.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // Post-residual reusability vs. mean coupling — a leftover close to
    // the stream's mean residual is statistically most likely to be reused
    // later; reward closeness, punish outliers among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 22.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
    }

    // Dead-zone gradient refinement — residuals in the 20..=34 band are
    // only fillable by mid-class items; when the next item is small
    // (<= 10), such residuals are likely to survive untapped.
    if post_residual >= 20 && post_residual <= 34 && next_item_size > 0 && next_item_size <= 10 {
        score += 16.0;
    }

    // Two-bin exact-split plan — when exactly two bins fit and this
    // placement leaves a residual that exactly equals next_item_size, it
    // is a perfect handoff; reward it beyond the generic lookahead bonus.
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0;
    }

    // Residual-value discount for large leftovers consumed by small
    // items — placing a tiny item into a big pocket destroys future
    // packing potential; scale the tax with the destroyed fraction.
    if post_residual > 0 && item_size > 0 && bin_residual > item_size {
        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Dead-space budget coupling — when the mean residual across open bins
    // is already high, leaving yet another mid-range leftover compounds
    // waste; tax placements whose post_residual both exceeds the mean and
    // sits in the hard-to-fill 10..=29 band.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Near-perfect-fit gradient sharpening — among competing bins, a
    // post_residual of exactly 1..=2 is nearly a perfect fill; reward it
    // beyond the flat tier so the tightest bin wins decisively.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    // Dual-lookahead consolidation — when the current item and the
    // next-item pair leave a residual within a small-filler band of
    // zero, prefer this bin strongly.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // Waste-gap interpolation — among competing bins, prefer the bin
    // whose post_residual sits on a reusable band boundary (multiple of
    // 10), taxing residuals stranded mid-band between classes.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual < 60 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 14.0;
        } else if m >= 7 {
            score += 6.0 + (m - 7) as f64 * 3.0;
        }
    }

    // Triple-chain consolidation — when the current item plus the
    // next item leaves a residual exactly tileable by a third plausible
    // chunk (next_item_size again or a class multiple), this bin is a
    // full three-item plan; reward it decisively.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 0 && (after_pair == next_item_size || after_pair % 10 == 0) {
            score -= 46.0;
        }
    }

    // Combined fine-grained residual + lookahead: when many bins fit and
    // this placement leaves a residual that both is small in absolute
    // terms AND can absorb the next item, consolidate decisively here.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Class-aware dead-zone tax — a leftover whose size sits strictly
    // between the next item's class boundary and the next class floor is
    // unlikely to be filled by anything arriving soon; tax it in proportion
    // to how far it overshoots the next item, but only when alternatives
    // exist (multiple fitting bins), so unique fits stay untouched.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting — in the final third of the
    // stream, prefer placements that leave a residual exactly reusable by
    // the next item even at the cost of a slightly larger current fit;
    // chains of exact handoffs eliminate trailing waste bins.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation — when many bins are open,
    // the tightest fit matters more because each leftover fragment is
    // another bin that may never close; sharpen the tight-fit gradient
    // with open_bins_count so crowded states converge to best-fit harder.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket — a post_residual that falls
    // within [next_item_size, next_item_size + 3] is a guaranteed reuse
    // for the immediate successor; reward it progressively beyond the
    // generic slack bonus, strongest when few bins fit (scarce space).
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain — in the final 20% of the stream,
    // small items (<= 12) should preferentially drain the bin with the
    // SMALLEST residual they can fit, preserving large pockets for the
    // remaining medium/large items; tax placements into big pockets.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — if this placement closes the bin exactly
    // AND the next item also fits the residual after being added (i.e. a
    // two-item exact close), reward decisively regardless of bin count.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // Residual-efficiency gradient — among competing bins, prefer
    // the placement whose post_residual is smallest in absolute terms
    // beyond the flat tiers; a smooth secondary term that breaks ties
    // toward the tightest fit and directly reduces dead space.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual <= 40 {
        score += (post_residual as f64) * 1.8;
    }

    // Next-item dead-space guard — a placement whose post_residual
    // sits in the 1..=next_item_size-1 dead band is doubly wasteful when
    // the next item is small (high-frequency arrivals); tax it harder so
    // competing bins that can absorb the next item win.
    if next_item_size > 0 && next_item_size <= 20 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.5;
    }

    // Crowded-state exact-close emphasis — when many bins are open,
    // closing a bin exactly (post_residual == 0) removes a fragment for
    // good; amplify the perfect-fit reward with congestion.
    if post_residual == 0 && open_bins_count > 3 {
        score -= 30.0 + (open_bins_count.min(12) as f64) * 4.0;
    }

    // GEN19: Quadratic dead-space sweep — extend the residual-efficiency
    // gradient beyond 40 with a convex slope so mid-large leftovers
    // (40..=80) are taxed proportionally harder, pushing selection toward
    // bins that genuinely minimize wasted space rather than only near-ties.
    if fitting_bins_count > 1 && post_residual > 40 && post_residual <= 80 {
        score += 72.0 + (post_residual as f64 - 40.0) * 2.2;
    }

    // GEN19: Reuse-likelihood coupling — a leftover is only valuable if
    // some plausible item class can fill it; reward leftovers that sit
    // at or above the next item's size band (fillable soon) and tax
    // leftovers in the "class gap" just below a class boundary, which
    // statistically survives until stream end as pure waste.
    if post_residual > 0 {
        let cls_floor = ((post_residual / 10) * 10) as f64;
        let in_class_gap = (post_residual as f64 - cls_floor) <= 2.0 && post_residual < 50;
        if in_class_gap && fitting_bins_count > 1 {
            score += 9.0;
        }
        // Leftovers that can still hold the next item twice (k>=2 chain
        // potential) are compounding assets; deepen the existing reward.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 12.0 * (1.0 - progress * 0.5);
        }
    }

    // GEN19: Endgame zero-waste sprint — in the final 10% of the stream,
    // every remaining unit of dead space is unrecoverable; apply a smooth
    // extra tax proportional to post_residual so the tightest possible
    // placement wins in the closing stretch.
    if progress > 0.9 && post_residual > 0 {
        score += (post_residual as f64) * 1.4 * (progress - 0.9) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
            score -= 32.0;
        }
    }

    // Pair exactness — residual exactly equals current+next is a jackpot.
    if pair > 0 && bin_residual == pair {
        score -= 266.0;
    }

    // Multi-fill potential — how many additional items of next size could
    // still land in this bin after the current one. More = better consolidation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let multi = post_residual / next_item_size;
        if multi >= 2 {
            score -= 22.0 * (multi.min(4) as f64);
        }
    }

    // Reusability shaping: leftover between ~15% and ~45% of capacity is highly reusable.
    if post_residual > 0 {
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 30.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
    }

    // Exact-complement chain — post_residual can exactly absorb next item
    // plus another known-size chunk; near-perfect plan, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 68.0;
        }
    }

    // Avoid leaving residuals just below the next item size (dead pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax — residuals too small for most item classes
    // (1..=9) are almost guaranteed waste; scale penalty with depth.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
    }

    // Harmonic-fit bonus — post_residual matching common complements of
    // typical item sizes (multiples of 25 or 50) stays fillable.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0) {
        score -= 35.0;
    }

    // Mid-band residual shaping — reward exactly-fillable remainders,
    // punish near-miss remainders just above the next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
    }

    // Fit-quality gradient among competing bins — push selection toward
    // the bin whose placement leaves the smallest post_residual relative
    // to the item's own class.
    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 58.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Three-item chain check — current + next + a small filler (1..=10)
    // exactly fills this bin's residual; an exceptionally strong plan.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let chain = bin_residual - item_size - next_item_size;
        if chain >= 1 && chain <= 10 {
            score -= 88.0;
        }
    }

    // Two-step exactness — after placing the current item, check whether
    // post_residual can absorb next_item_size AND a mid-class filler exactly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 15 && after_next <= 45 && after_next % 5 == 0 {
            score -= 36.0;
        }
        if after_next > 0 && after_next < 10 {
            score += 26.0;
        }
    }

    // Residual-fragmentation tax — when many open bins exist, leaving a
    // mid-sized residual (fragment) spreads waste across bins; consolidate.
    if open_bins_count > 4 && post_residual > 12 && post_residual < bin_capacity / 3 {
        score += 14.0;
    }

    // New-bin candidate logic.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 70.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 135.0;
        }
        // When open bins exist but every fit is poor (large item, tiny residuals),
        // opening fresh is cheaper than shattering a usable residual.
        if fitting_bins_count > 0 && item_size > bin_capacity / 3 {
            let avg_fit_slack: f64 = mean_residual - item_size as f64;
            if avg_fit_slack < 8.0 {
                score -= 45.0 * (1.0 - progress);
            }
        }
        // Protect big pockets late in the stream.
        if fitting_bins_count > 0 && progress > 0.4 && item_size <= bin_capacity / 3 {
            if mean_residual < item_size as f64 * 1.5 {
                score -= 27.0 * progress;
            }
        }
        // If the next item is large and no open bin could hold it after
        // this placement, opening a fresh bin now preserves flexibility.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            if post_residual < next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin discipline — opening a new bin late wastes
        // capacity unless the item is big; penalize small-item new bins late.
        if progress > 0.6 && item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Mid-stream fresh-bin restraint — between 25% and 60% progress,
        // small items should almost never open fresh bins while any fit exists.
        if progress > 0.25 && progress <= 0.6 && item_size <= bin_capacity / 3 && fitting_bins_count > 0 {
            score += 38.0;
        }
        // Endgame fresh-bin economy — in the final 15% of the stream,
        // opening a fresh bin for a small item is almost pure waste.
        if progress > 0.85 && item_size < bin_capacity / 5 && fitting_bins_count > 0 {
            score += 78.0;
        }
        // Pair-fit gate — if this fresh bin can absorb BOTH the current
        // and the next item exactly, opening it is a genuine plan, not waste.
        if pair > 0 && bin_residual >= pair {
            let pair_slack = bin_residual - pair;
            if pair_slack <= 4 {
                score -= 98.0;
            }
        }
        // Dead-pocket escape — when the best available fit would leave a
        // residual too small for any plausible item (<= 9), a fresh bin
        // with a full residual is strictly better than shattering the pocket.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 9 {
            score -= 90.0 * (1.0 - progress).max(0.2);
        }
        // Next-item dead-pocket escape — if the current fit would leave a
        // residual just below next_item_size (unusable by the immediate
        // successor), a fresh bin preserves that space for the successor.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score -= 62.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin exact-pair plan — opening a bin whose capacity is
        // exactly current + next (or within 2) is a perfect two-item plan.
        if next_item_size > 0 {
            let diff = bin_capacity as i64 - (item_size as i64 + next_item_size as i64);
            if diff >= 0 && diff <= 2 {
                score -= 112.0;
            }
        }
        // Oversized-item fresh-bin sharpening — items above 60% of capacity
        // almost never share a bin; when any open bin would be shattered to
        // a near-dead pocket (< 15 left), prefer the fresh bin aggressively.
        if fitting_bins_count > 0 && item_size * 5 > bin_capacity * 3 {
            if post_residual > 0 && post_residual < 15 {
                score -= 52.0;
            }
        }
        // Fresh-bin tileability — if the fresh bin's capacity can be
        // tiled by the next item repeated k>=2 times after this placement,
        // opening it now is a multi-item consolidation plan.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let after = bin_capacity - item_size;
            if after % next_item_size == 0 && after / next_item_size >= 2 {
                score -= 44.0;
            }
        }
        // Fresh-bin fragment-consolidation — when open bins hold many
        // small scattered fragments (low mean residual, many bins), opening
        // one fresh bin for a large item keeps those fragments intact for
        // the many small items that follow, instead of burning the single
        // large pocket that remains.
        if fitting_bins_count > 0 && open_bins_count > 3 && item_size > bin_capacity / 2 {
            if mean_residual < item_size as f64 * 1.2 {
                score -= 40.0 * (1.0 - progress).max(0.25);
            }
        }
        // Fresh-bin mid-fit gate — when an open-bin fit would leave a
        // residual in the awkward 30..=45 band while the fresh bin can
        // hold current+next with slack <= 10, prefer the fresh bin.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= 30 && post_residual <= 45 {
            let fresh_slack = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_slack <= 10 {
                score -= 58.0 * (1.0 - progress).max(0.3);
            }
        }
        // Fresh-bin triple-tile plan — if the fresh bin can hold the
        // current item plus the next item twice with <= 5 slack.
        if next_item_size > 0 && bin_capacity >= item_size + 2 * next_item_size {
            let t3 = bin_capacity - (item_size + 2 * next_item_size);
            if t3 <= 5 {
                score -= 74.0 * (1.0 - progress).max(0.4);
            }
        }
        // Late-stream fresh-bin gate for medium items — in the final 20%,
        // opening a fresh bin for a mid item (<= capacity/2) while any fit
        // exists is usually waste unless the fit would shatter a pocket.
        if progress > 0.8 && item_size <= bin_capacity / 2 && fitting_bins_count > 0 && post_residual > 12 {
            score += 30.0 * progress;
        }
        score += 30.0 + 40.0 * progress;
    }

    // Waste-floor shaping for regular placements — when several bins fit,
    // a placement leaving a residual of 10..=19 is a near-dead pocket for
    // most distributions; tax it progressively (sharpened slope).
    if fitting_bins_count > 1 && post_residual >= 10 && post_residual <= 19 {
        score += 24.0 + (19 - post_residual as i32) as f64 * 4.0;
    }

    // Sub-next dead-band sharpening — when multiple bins fit, a placement
    // whose residual sits within 8 units below next_item_size is unusable
    // by the immediate successor; tax proportionally to closeness.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 8 {
            score += 14.0 + (8 - gap as i32) as f64 * 4.0;
        }
    }

    // Congestion: many open bins -> favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 15.0;
    }

    // Protect large residuals from being consumed by small items late in stream.
    if bin_residual > bin_capacity * 3 / 4 && item_size < bin_capacity / 4 && progress > 0.5 {
        score += 36.0;
    }

    // Late-stream exactness boost — perfect/near-perfect fits matter more
    // when few items remain.
    let remaining_frac = 1.0 - progress;
    if post_residual <= 8 && remaining_frac < 0.25 {
        score -= 62.0 * (1.0 - remaining_frac * 4.0).max(0.0);
    }

    // Divisibility-aware waste penalty — leftover that no multiple of any
    // plausible item class fills is taxed mildly.
    if post_residual > 0 && post_residual < bin_capacity {
        let cls = (post_residual / 10).max(1);
        if post_residual % (cls * 10) != 0 && post_residual < 50 {
            score += 11.0;
        }
    }

    // Exact-fill lookahead sweep — reward placements where the residual
    // after this item can be tiled exactly by the next item repeated k
    // times (k >= 1) with zero leftover.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k >= 1 && k <= 4 {
            score -= 18.0 * k as f64;
        }
    }

    // Post-residual reusability vs. mean coupling — a leftover close to
    // the stream's mean residual is statistically most likely to be reused
    // later; reward closeness, punish outliers among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        if dist < 6.0 {
            score -= 22.0;
        } else if dist > 40.0 {
            score += 9.0;
        }
    }

    // Dead-zone gradient refinement — residuals in the 20..=34 band are
    // only fillable by mid-class items; when the next item is small
    // (<= 10), such residuals are likely to survive untapped.
    if post_residual >= 20 && post_residual <= 34 && next_item_size > 0 && next_item_size <= 10 {
        score += 16.0;
    }

    // Two-bin exact-split plan — when exactly two bins fit and this
    // placement leaves a residual that exactly equals next_item_size, it
    // is a perfect handoff; reward it beyond the generic lookahead bonus.
    if fitting_bins_count == 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0;
    }

    // Residual-value discount for large leftovers consumed by small
    // items — placing a tiny item into a big pocket destroys future
    // packing potential; scale the tax with the destroyed fraction.
    if post_residual > 0 && item_size > 0 && bin_residual > item_size {
        let consumed_frac = item_size as f64 / bin_residual as f64;
        if consumed_frac < 0.2 && post_residual > 40 {
            score += 22.0 * (1.0 - consumed_frac * 5.0);
        }
    }

    // Dead-space budget coupling — when the mean residual across open bins
    // is already high, leaving yet another mid-range leftover compounds
    // waste; tax placements whose post_residual both exceeds the mean and
    // sits in the hard-to-fill 10..=29 band.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 10.0 + 0.25 * (post_residual as f64 - mean_residual).min(20.0);
    }

    // Near-perfect-fit gradient sharpening — among competing bins, a
    // post_residual of exactly 1..=2 is nearly a perfect fill; reward it
    // beyond the flat tier so the tightest bin wins decisively.
    if fitting_bins_count > 1 && post_residual >= 1 && post_residual <= 2 {
        score -= 42.0;
    }

    // Dual-lookahead consolidation — when the current item and the
    // next-item pair leave a residual within a small-filler band of
    // zero, prefer this bin strongly.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 10 && after_pair <= 25 {
            score -= 30.0;
        }
    }

    // Waste-gap interpolation — among competing bins, prefer the bin
    // whose post_residual sits on a reusable band boundary (multiple of
    // 10), taxing residuals stranded mid-band between classes.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual < 60 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 14.0;
        } else if m >= 7 {
            score += 6.0 + (m - 7) as f64 * 3.0;
        }
    }

    // Triple-chain consolidation — when the current item plus the
    // next item leaves a residual exactly tileable by a third plausible
    // chunk (next_item_size again or a class multiple), this bin is a
    // full three-item plan; reward it decisively.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair > 0 && (after_pair == next_item_size || after_pair % 10 == 0) {
            score -= 46.0;
        }
    }

    // Combined fine-grained residual + lookahead: when many bins fit and
    // this placement leaves a residual that both is small in absolute
    // terms AND can absorb the next item, consolidate decisively here.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 34.0;
        }
    }

    // Class-aware dead-zone tax — a leftover whose size sits strictly
    // between the next item's class boundary and the next class floor is
    // unlikely to be filled by anything arriving soon; tax it in proportion
    // to how far it overshoots the next item, but only when alternatives
    // exist (multiple fitting bins), so unique fits stay untouched.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot > 10 && overshoot <= 20 {
            score += 8.0 + (overshoot - 10) as f64 * 1.2;
        }
    }

    // Late-stream fragment harvesting — in the final third of the
    // stream, prefer placements that leave a residual exactly reusable by
    // the next item even at the cost of a slightly larger current fit;
    // chains of exact handoffs eliminate trailing waste bins.
    if progress > 0.66 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 * progress;
    }

    // Fragment-count-aware consolidation — when many bins are open,
    // the tightest fit matters more because each leftover fragment is
    // another bin that may never close; sharpen the tight-fit gradient
    // with open_bins_count so crowded states converge to best-fit harder.
    if open_bins_count > 6 && post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    }

    // Next-item-size-matched pocket — a post_residual that falls
    // within [next_item_size, next_item_size + 3] is a guaranteed reuse
    // for the immediate successor; reward it progressively beyond the
    // generic slack bonus, strongest when few bins fit (scarce space).
    if next_item_size > 0 && post_residual >= next_item_size {
        let over = post_residual - next_item_size;
        if over <= 3 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= 26.0 * scarcity * (4 - over as i32) as f64;
        }
    }

    // Late-stream small-item drain — in the final 20% of the stream,
    // small items (<= 12) should preferentially drain the bin with the
    // SMALLEST residual they can fit, preserving large pockets for the
    // remaining medium/large items; tax placements into big pockets.
    if progress > 0.8 && item_size <= 12 && post_residual > 30 {
        score += 20.0 * (1.0 - remaining_frac * 5.0).max(0.0);
    }

    // Exact-capacity sweep — if this placement closes the bin exactly
    // AND the next item also fits the residual after being added (i.e. a
    // two-item exact close), reward decisively regardless of bin count.
    if next_item_size > 0 && post_residual == 0 && bin_residual == item_size + next_item_size {
        score -= 150.0;
    }

    // Residual-efficiency gradient — among competing bins, prefer
    // the placement whose post_residual is smallest in absolute terms
    // beyond the flat tiers; a smooth secondary term that breaks ties
    // toward the tightest fit and directly reduces dead space.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual <= 40 {
        score += (post_residual as f64) * 1.8;
    }

    // Next-item dead-space guard — a placement whose post_residual
    // sits in the 1..=next_item_size-1 dead band is doubly wasteful when
    // the next item is small (high-frequency arrivals); tax it harder so
    // competing bins that can absorb the next item win.
    if next_item_size > 0 && next_item_size <= 20 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.5;
    }

    // Crowded-state exact-close emphasis — when many bins are open,
    // closing a bin exactly (post_residual == 0) removes a fragment for
    // good; amplify the perfect-fit reward with congestion.
    if post_residual == 0 && open_bins_count > 3 {
        score -= 30.0 + (open_bins_count.min(12) as f64) * 4.0;
    }

    // NEW: Total-waste budget coupling — the sum of the placement's
    // post_residual and the mean residual of other open bins estimates
    // the stream-wide dead-space trajectory; when this placement would
    // push the average dead space above a small threshold, tax it
    // proportionally so the tightest-bin choice compounds globally.
    if post_residual > 0 && open_bins_count > 1 {
        let projected = (post_residual as f64 + mean_residual * (open_bins_count as f64 - 1.0)) / open_bins_count as f64;
        if projected > 12.0 {
            score += (projected - 12.0).min(25.0) * 0.9;
        } else if projected < 6.0 {
            score -= 12.0;
        }
    }

    // NEW: Complement-tile lookahead — when the next item's complement
    // (capacity - next) can absorb the current item's post_residual
    // almost exactly, the pair forms a self-consistent two-bin plan;
    // reward it when competing bins exist.
    if next_item_size > 0 && next_item_size < bin_capacity && fitting_bins_count > 1 && post_residual > 0 {
        let next_complement = bin_capacity - next_item_size;
        let diff = next_complement as i32 - post_residual as i32;
        if diff >= 0 && diff <= 4 {
            score -= 48.0 - diff as f64 * 6.0;
        }
    }

    // NEW: Residual-harvest sequencing — when the next item cannot fit
    // this bin's post_residual but a SMALLER residual band (<= next + 10)
    // exists elsewhere in the stream (mean residual below next item),
    // prefer leaving this bin's residual as large as possible so future
    // medium items have room; reward bins that keep generous leftovers.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
        && mean_residual < next_item_size as f64 && fitting_bins_count > 1 {
        score += (next_item_size - post_residual) as f64 * 1.4;
    }

    // NEW: Dead-space budget coupling — when the mean residual across open
    // bins is already high, leaving yet another mid-range leftover
    // compounds waste; tax placements whose post_residual exceeds the mean
    // and sits in the hard-to-fill 10..=29 band (sharpened variant).
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 4.0 + 0.35 * (post_residual as f64 - mean_residual).min(18.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
