    }

    // Dead-space budget coupling (sharpened variant) — when the mean
    // residual across open bins is already high, leaving yet another
    // mid-range leftover compounds waste.
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 4.0 + 0.35 * (post_residual as f64 - mean_residual).min(18.0);
    }

    // NEW: Continuous dead-space gradient — replace the flat tier jump
    // between post_residual 15 and 25 with a smooth quadratic ramp so
