    if post_residual > 5 && post_residual <= 30 {
        score += 0.55 * (post_residual as f64 - 5.0) * (post_residual as f64 - 5.0) / 25.0;
    }

    // NEW: Late-stream exact-close multiplier — in the final quarter,
    // any placement that closes a bin (post_residual == 0) is doubly
    // valuable because remaining capacity is scarce; amplify the close.
    if post_residual == 0 && progress > 0.75 {
        score -= 55.0 * progress;
    }

    // NEW: Fresh-bin last-resort tightening — when the item is small and
    // the stream is nearly done, opening a fresh bin for anything under
    // a third of capacity that leaves > 20 dead space is pure waste.
    if bin_residual == bin_capacity && progress > 0.7 && item_size < bin_capacity / 3 && post_residual > 20 && fitting_bins_count > 0 {
        score += 45.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
