        }
        // NEW (mutation): fresh-bin mean-residual saturation gate — when the
        // average open-bin residual is already large enough to absorb this
        // item with comfortable slack, opening a new bin wastes capacity;
        // penalize proportionally to that slack.
        if fitting_bins_count > 0 && mean_residual > item_size as f64 + 10.0 {
            score += ((mean_residual - item_size as f64) - 10.0).min(30.0) * 1.1;
