    if open_bins_count > 5 && fitting_bins_count > 2 && post_residual > 0 && post_residual <= 20 {
        score += (post_residual as f64) * 0.9;
    }

    // COMBINED MUTATION 8: next-item large rescue — large successor (> cap/3)
    // that no longer fits after this placement is taxed mildly when
