    // punish near-miss remainders just above the next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
