pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear waste penalty: quadratic dead-space coupling scaled by stream progress.
    let x = pr / cap;
    let waste = x * x * (1.0 + 2.0 * progress);
    score += 40.0 * waste;

    // Reward tight fits: cubic falloff of post_residual.
    score -= 30.0 * (1.0 - x).powi(3);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    let ns = next_item_size as f64;
    if ns > 0.0 {
        let gap = (pr - ns) / cap;
        if gap > 0.0 {
            score -= 25.0 * gap * (1.0 - gap) * 4.0;
        } else {
            score += 15.0 * (-gap); // penalize blocking the next item
        }
    }

    // Mean residual coupling: prefer bins deviating below mean residual (denser bins).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev - 5.0 * dev;

    // Late-stream consolidation: mild pressure to fill open bins as stream ends.
    score += 20.0 * progress * (open_bins_count as f64).sqrt() * 0.05 * (1.0 - x);

    score
}

