            score += (projected - 12.0).min(25.0) * 0.9;
        } else if projected < 6.0 {
            score -= 12.0;
        }
    }

    // NEW: complement-tile lookahead.
    if next_item_size > 0 && next_item_size < bin_capacity && fitting_bins_count > 1 && post_residual > 0 {
        let next_complement = bin_capacity - next_item_size;
        let diff = next_complement as i32 - post_residual as i32;
        if diff >= 0 && diff <= 4 {
            score -= 48.0 - diff as f64 * 6.0;
