    // next_item_size plus a tiny filler with near-zero waste.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 6 {
            let urgency = if progress > 0.5 { 1.5 } else { 1.0 };
