        }
    }

    // NEW: crowding-aware tight-fit amplifier.
    if open_bins_count > 5 && fitting_bins_count > 2 && post_residual > 0 && post_residual <= 20 {
        score += (post_residual as f64) * 0.9;
    }

    // NEW: next-item large rescue.
    if next_item_size > 0 && next_item_size > bin_capacity / 3 && post_residual > 0
        && post_residual < next_item_size && fitting_bins_count > 1 {
        score += 18.0 * (1.0 - progress).max(0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "usable" classes (small, or multiples matching common item sizes)
    // are rewarded; awkward mid-range leftovers are penalized.
    let cap = bin_capacity as f64;

    // Class 1: perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Class 2: post_residual can host the lookahead item -> reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + 0.5 * (next_item_size as f64);
        // Extra reward if lookahead fills the bin almost exactly.
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 80.0;
        }
    } else if next_item_size > 0 {
        // Lookahead cannot use the leftover: penalize proportionally.
        score += 15.0;
    }

    // Integer-division thresholds on post_residual: classify leftover
    // into harmonic buckets of capacity/10.
    let bucket = post_residual / 10; // 0..10
    match bucket {
        0 => score -= 25.0,           // tiny waste, excellent bin
        1 => score -= 10.0,           // small waste
        2 | 3 => score += 5.0,        // awkward mid leftovers
        4 | 5 => score += 12.0,       // half-empty: risky dead space
        6 | 7 => score += 6.0,        // large leftover, may still be useful
        _ => {}                       // near-empty bin class handled below
    }

    // New-bin candidate: neutral-ish baseline; prefer it only when
    // existing bins would leave very wasteful residuals.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.1 * (open_bins_count as f64);
        // If the next item also fits comfortably in a fresh bin, slight bonus.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        return score;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins tighter than the average residual (best-fit flavor).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for fewer open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();

    // Modulo coupling: reward residuals that are harmonically aligned
    // with the item size (post_residual % item_size small => reusable).
    if item_size > 0 {
        let m = post_residual % item_size;
        score -= 0.4 * (item_size as f64 - m as f64);
    }

    score
}

