    // Crowding-aware tight-fit amplifier — when many bins are open AND
    // several fit, extra weight on the tightest fit compounds consolidation
    // and closes fragments early.
    if open_bins_count > 5 && fitting_bins_count > 2 && post_residual > 0 && post_residual <= 20 {
        score += (post_residual as f64) * 0.9;
    }

    // Next-item large rescue — if the next item is large (> capacity/3)
    // and this placement leaves a residual that cannot hold it, tax mildly
    // so bins preserving room for it win, but only when alternatives exist.
    if next_item_size > 0 && next_item_size > bin_capacity / 3 && post_residual > 0
        && post_residual < next_item_size && fitting_bins_count > 1 {
        score += 18.0 * (1.0 - progress).max(0.3);
    }

    // NEW (gen 25): mid-band dead-space shave — residuals in the 35..=55
    // band are too large to ignore but often too awkward to fill; among
    // competing bins, tax them proportionally so tighter fits win, while
    // sparing placements that exactly tile with the next item.
    if fitting_bins_count > 1 && post_residual >= 35 && post_residual <= 55 {
        let tileable = next_item_size > 0 && post_residual % next_item_size.max(1) == 0;
        if !tileable {
            score += 9.0 + (post_residual as f64 - 35.0) * 0.5;
        }
    }

    // NEW (gen 25): early-stream best-fit reinforcement — in the first
    // third of the stream, every wasted unit compounds; sharpen the
    // tight-fit preference so early bins close exactly rather than
    // accumulating fragments that never drain.
    if progress < 0.33 && fitting_bins_count > 1 && post_residual > 0 && post_residual <= 12 {
        score += (post_residual as f64) * 1.2;
    }

    // NEW (gen 25): fresh-bin slack economy — when a fresh bin would be
    // opened while an open-bin fit exists, penalize the fresh bin in
    // proportion to the capacity it strands (capacity minus item), unless
    // the fresh bin forms an exact pair plan with the next item.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let stranded = bin_capacity.saturating_sub(item_size);
        let exact_plan = next_item_size > 0 && stranded >= next_item_size && stranded - next_item_size <= 4;
        if !exact_plan && stranded > 30 {
            score += 16.0 + (stranded as f64 - 30.0).min(60.0) * 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match: next item fits with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 500.0 - slack * 3.0;
    }
    // Next item does NOT fit: penalize proportionally to how wasted the residual is.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Penalize unusable dead space (small residual unlikely to fit anything).
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Prefer bins whose residual is below the mean (tightly packed bins first).
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Reward compacting when many bins are open.
    score -= (open_bins_count as f64).ln() * 5.0;

    // Early in the stream, be more willing to keep bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0;

    score
}

