    }

    // Dead-space budget coupling (sharpened variant).
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 4.0 + 0.35 * (post_residual as f64 - mean_residual).min(18.0);
    }

    // Continuous dead-space quadratic ramp.
    if post_residual > 5 && post_residual <= 30 {
        score += 0.55 * (post_residual as f64 - 5.0) * (post_residual as f64 - 5.0) / 25.0;
    }

    // Late-stream exact-close multiplier.
    if post_residual == 0 && progress > 0.75 {
        score -= 55.0 * progress;
    }

    // Fresh-bin last-resort tightening.
    if bin_residual == bin_capacity && progress > 0.7 && item_size < bin_capacity / 3 && post_residual > 20 && fitting_bins_count > 0 {
        score += 45.0 * progress;
    }

    // Dual-chain tileability.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 6 {
            let urgency = if progress > 0.5 { 1.5 } else { 1.0 };
            score -= 46.0 * urgency;
        }
    }

    // Crowding-aware tight-fit amplifier.
    if open_bins_count > 5 && fitting_bins_count > 2 && post_residual > 0 && post_residual <= 20 {
        score += (post_residual as f64) * 0.9;
    }

    // Next-item large rescue.
    if next_item_size > 0 && next_item_size > bin_capacity / 3 && post_residual > 0
        && post_residual < next_item_size && fitting_bins_count > 1 {
        score += 18.0 * (1.0 - progress).max(0.3);
    }

    // NEW: mid-range residual compaction — for residuals in the awkward
    // 30..=60 band (too big for small items, too small for large ones),
    // tax proportionally so bins leaving compactable residuals win instead.
    if post_residual >= 30 && post_residual <= 60 && fitting_bins_count > 1 {
        score += (post_residual as f64 - 30.0) * 0.8;
    }

    // NEW: exact-residual reuse plan — if the post residual equals the
    // current item size, a repeat of this item later closes the bin
    // perfectly; reward this self-similar tiling, amplified by scarcity.
    if post_residual == item_size && item_size > 0 {
        let scarcity = if fitting_bins_count <= 2 { 1.4 } else { 1.0 };
        score -= 44.0 * scarcity;
    }

    // NEW: late-stream consolidation gate — when few items remain and
    // multiple bins fit, weight the absolute residual more heavily so
    // the last placements minimize total dead space.
    if remaining_frac < 0.15 && fitting_bins_count > 1 && post_residual > 0 {
        score += (post_residual as f64) * 1.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.6 * (post_residual as f64 - next_item_size as f64).min(20.0) / 10.0;
        } else {
            // Dead space for the next item: penalize proportionally to wasted gap.
            score += 0.35 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it yields a
    // genuinely better arrangement (e.g. item large relative to capacity,
    // or existing bins are too fragmented).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let mut penalty = 18.0;
        // Late in the stream, be more conservative about opening bins.
        penalty += 10.0 * progress;
        // If open bins are highly fragmented (large mean residual unusable),
        // opening a new bin is more acceptable.
        penalty -= 12.0 * fragmentation.max(0.0);
        // Large items relative to capacity fit better in a fresh bin.
        penalty -= 0.08 * item_size as f64;
        // If no other bin fits, new bin is the only option.
        if fitting_bins_count == 0 {
            penalty -= 60.0;
        }
        score += penalty.max(-5.0);
    }

    // Mild preference for tighter existing bins (lower residual before placement).
    score += 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

