}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer tight fits, scaled by stream progress (tight packing matters more later)
    let mut score = pr * (1.0 + 0.8 * progress);

    // Non-linear penalty on very small post-residuals that become dead space
    let dead = (pr / cap).powi(2) * (1.0 - fill).powi(2) * 40.0;
    score += dead;

    // Smooth interaction: residual vs mean residual deviation
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Lookahead: reward leaving space for the next item (smooth quadratic coupling)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = pr - n;
        score -= 3.0 * (1.0 - (gap / cap).abs()).max(0.0).powi(2) * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.05 * (1.0 + progress);

    // New-bin candidate: neutral-ish baseline, penalize slightly unless placement is bad
    if bin_residual == bin_capacity {
        score = cap as f64 * 0.9 + 5.0 * (1.0 - progress) - 0.3 * item_size as f64;
    }

    score
}

