}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Residuals smaller than the smallest possible item (1) are truly dead;
    // residuals below a "usefulness floor" are heavily penalized since they
    // can only host tiny items. Perfect fit (0) is ideal.
    if post_residual == 0 {
        score -= 60.0; // perfect fill: strongly favored
    } else if post_residual < 10 {
        score += 25.0; // near-dead gap: likely wasted forever
    } else if post_residual < 25 {
        score += 10.0; // small awkward gap
    }

    // Fractional dead-space term: convex penalty on wasted space.
    let pr = post_residual as f64;
    score += 0.15 * (pr / 100.0) * (pr / 100.0) * 100.0;

    // --- Lookahead coupling: can next item use this residual? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual remains useful: mild reward scaled by snugness
            let snug = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - snug / 100.0);
        } else {
            // next item can't use leftover: penalize proportionally
            score += 6.0;
        }
    }

    // --- Last-chance bonus: this is the only bin that fits ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0; // avoid opening a new bin unnecessarily
    }

    // --- Open-bin pressure: prefer filling existing bins over spawning ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Default cost of opening a new bin; overridden only if all fits
        // are terrible (heavy dead-space penalties above).
        score = 200.0
            - if fitting_bins_count == 0 { 500.0 } else { 0.0 }
            - if post_residual >= 60.0 && next_item_size > 0 && next_item_size <= post_residual { 15.0 } else { 0.0 };
    }

    // --- Mean-residual alignment: prefer bins close to mean (balanced use) ---
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

