    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress < 0.6 {
        let usable = mean_residual - item_size as f64;
        if usable > 15.0 {
            score += 30.0 + (usable - 15.0).min(30.0) * 0.8;
