    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let fit = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear waste penalty: dead space is superlinearly bad
    score += 18.0 * pr_norm * pr_norm;

    // Smooth progress coupling: tight packing valued more as stream advances
    score -= 30.0 * (1.0 - pr_norm) * fit * (0.4 + 0.6 * progress);

    // Reward near-perfect fills with a smooth bell around zero residual
    score -= 25.0 * (-(pr_norm * pr_norm) / 0.02).exp();

    // Lookahead: bonus if next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins with less residual than average
    score += 4.0 * (pr - mean_residual) / cap;

    // New-bin candidate: penalize opening unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - progress);
    }

    score
}

