pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" the leftover is.
    // Class 0: post_residual in {0} -> perfect fit, big reward.
    // Class 1: post_residual divisible into small chunks (<=10) -> highly reusable.
    // Class 2: mid-range leftovers (11..=30) -> moderately reusable.
    // Class 3: large awkward leftovers (31..=60) -> risky dead space.
    let pr = post_residual;
    let mut class_bonus: f64 = 0.0;
    if pr == 0 {
        class_bonus = 40.0; // perfect fit
    } else if pr <= 10 {
        class_bonus = 18.0 + 0.5 * (10 - pr) as f64;
    } else if pr <= 30 {
        class_bonus = 8.0 - 0.1 * (pr - 10) as f64;
    } else if pr <= 60 {
        class_bonus = -0.05 * (pr - 30) as f64; // mild penalty for awkward gaps
    } else {
        class_bonus = -2.0; // huge gap: item was small, bin nearly empty -> wasteful placement
    }
    score -= class_bonus;

    // Modulo structure: residual that is a multiple of common item granularities
    // (5, 10) tends to be reusable; odd primes less so.
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Integer division threshold: pr / 10 (how many small items fit)
        let small_fit = pr / 10;
        score -= 1.5 * small_fit as f64;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack_after_next = pr - next_item_size;
            score -= 10.0 - 0.2 * slack_after_next as f64;
        } else {
            // next item won't fit here regardless; penalize wasting tight space
            score += 2.0;
        }
        // Harmonic pairing: item_size + next_item_size near capacity multiples
        let pair = item_size + next_item_size;
        if pair % 100 == 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.1 * (post_residual as f64).min(50.0);
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Give it a baseline penalty that scales with how many
    // bins could fit the item.
    if bin_residual == bin_capacity {
        score += 15.0 + 4.0 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheap-ish; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer packing into fuller bins (tighter relative fill).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio;

    // Mild preference for bins with residuals below the mean (tighten the tight ones).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Many open bins -> encourage consolidation into existing bins.
    score += 0.5 * open_bins_count as f64;

    score
}

