            && (bin_capacity == item_size + next_item_size
                || (bin_capacity - item_size) % next_item_size == 0);
        if !exact_plan {
            score += 52.0 * (1.0 - progress * 5.0).max(0.0);
        }
    }

    // NEW (gen 29): waste-rate coupling — a placement whose post-residual
    // exceeds the mean residual by a lot is creating an outlier fragment;
    // tax it proportionally so residual variance shrinks, but only when
    // tighter alternatives exist.
    if fitting_bins_count > 1 && post_residual > 25 && (post_residual as f64) > mean_residual + 15.0 {
        score += ((post_residual as f64) - mean_residual - 15.0).min(30.0) * 1.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = it / cap;
    let mut score = pr;

    // Reward tight fits: squared residual penalty that shrinks with stream progress
    let tight = (pr / cap).powi(2);
    score += tight * (cap * (0.6 + 0.8 * progress));

    // Smooth non-linear coupling: residual x fit-ratio interaction
    score -= (fit_norm * (1.0 - fit_norm)) * cap * (1.0 + progress);

    // Penalize bins whose residual deviates from the mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * cap * 0.5;

    // Last-chance bin: strongly reward using it
    if fitting_bins_count == 1 {
        score -= cap * (1.2 + 0.8 * progress);
    } else {
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Lookahead: bonus if leftover residual accommodates next item exactly-ish
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        let gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= (1.0 - gap).max(0.0) * cap * 0.35 * (1.0 + progress);
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space that cannot fit next item: mild penalty
        score += (post_residual as f64) * 0.15 * progress;
    }

    // New-bin candidate: prefer keeping it closed early, more attractive late
    if bin_residual == bin_capacity {
        score = cap * (1.5 - 1.1 * progress) + pr;
        if fitting_bins_count <= 2 {
            score -= cap * 0.6 * progress;
        }
    }

    score
}

