    }

    // NEW: late-stream fragment-closure gradient — in the final stretch,
    // every unit of leftover waste matters more; apply a mild linear tax on
    // any nonzero residual scaled by how close to the end we are.
    if post_residual > 0 && progress > 0.6 {
        score += (post_residual as f64) * 0.45 * ((progress - 0.6) / 0.4);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if !is_new_bin {
        // Strong reward: the NEXT item fits exactly into the post residual (perfect 2-chain).
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 60.0;
            } else if post_residual >= next_item_size {
                // Slack left after the lookahead item; penalize proportional to leftover.
                let slack = (post_residual - next_item_size) as f64;
                score -= 25.0 - 0.35 * slack;
            } else {
                // Lookahead does not fit: penalize small unusable dead space.
                let dead = post_residual as f64;
                if dead < 10.0 {
                    score += 12.0; // tiny fragment is fine actually — but keep bin usable ranking
                    score -= 12.0; // net neutral; small fragments are acceptable
                } else {
                    score += 0.02 * dead; // mild penalty for larger stranded space
                }
            }
        }

        // Relative-to-mean coupling: prefer bins with residual near/below mean
        // (best-fit style), penalize outliers with unusually large residuals.
        let diff = post_residual as f64 - mean_residual;
        score += 0.10 * diff;

        // Last-chance bonus: if this is the only bin that can fit the item,
        // strongly favor using it rather than opening a new bin.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // Early stream: be greedy about filling bins tightly; late stream:
        // consolidate to close out bins.
        if progress < 0.3 {
            score += 0.05 * post_residual as f64; // discourage wasting early bins
        } else {
            score -= 0.03 * post_residual as f64; // late: prefer filling existing bins
        }

        // Many open bins: encourage consolidation into existing bins.
        if open_bins_count > 4 {
            score -= 0.5 * open_bins_count as f64;
        }
    } else {
        // New-bin base score: moderately high so existing bins usually win,
        // but lowered when the current item leaves a huge gap or when the
        // lookahead won't fit anywhere sensible (poor fit scenario).
        score = 55.0;

        // If item leaves large post residual in an existing bin context,
        // opening fresh may be better: reduce new-bin score.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in stream, avoid proliferating bins.
        score += 15.0 * progress;
    }

    score
}

