    if bin_residual == bin_capacity && progress < 0.25 && item_size >= bin_capacity / 2 && fitting_bins_count > 0 {
        score -= 22.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Perfect fit: exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.5 * (next_item_size as f64);
    }
    // Penalize if next item cannot fit here anyway and residual becomes dead-ish.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = (bin_residual - item_size) as f64;
        // If no open bin fits, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            // Opening a new bin only attractive if best fit leaves big residual.
            score += 15.0 + fit_quality * 0.1;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Prefer filling bins with larger residuals (reduce fragmentation across fleet).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Mild penalty for spreading across many bins when mean residual is small.
    if mean_residual < 15.0 && open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Prefer placing large items into already-open bins early (large items first intuition).
    if item_size > 50 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

