    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: waste after placement
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, larger residuals are tolerable; late, waste is punished quadratically.
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * cap * (0.25 + 1.75 * progress * progress);

    // Reward tight fits: item filling most of the bin
    let fill = it / cap;
    score -= 30.0 * fill * fill * (1.0 - progress);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // Many open bins: mild penalty to avoid bin proliferation
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 0.5 {
            score -= 25.0;
        } else if nxt <= pr {
            score -= 8.0 * (nxt / (pr + 1.0));
        }
    }

    // Compare against mean residual: prefer bins below mean (concentrate waste)
    score += 3.0 * ((pr - mean_residual) / cap);

    // New-bin candidate: neutral-ish baseline, penalize early opening, allow late
    if bin_residual == bin_capacity {
        score = 40.0 + 60.0 * (1.0 - progress) - 10.0 * (fitting_bins_count as f64).min(3.0);
    }

    score
}

