        }
        // Late-stream fresh-bin gate for medium items.
        if progress > 0.8 && item_size <= bin_capacity / 2 && fitting_bins_count > 0 && post_residual > 12 {
            score += 30.0 * progress;
        }
        // NEW: fresh-bin vs. best-available-fit arbitration — if some open bin
        // would leave a near-zero residual, opening a new bin wastes that
        // pocket; only prefer the fresh bin when all fits are sloppy.
        if fitting_bins_count > 0 {
            let sloppy = mean_residual - item_size as f64;
            if sloppy > 18.0 {
