    // fits are ranked continuously, cutting residual variance.
    if post_residual > 5 && post_residual <= 30 {
        score += 0.55 * (post_residual as f64 - 5.0) * (post_residual as f64 - 5.0) / 25.0;
    }

    // Late-stream exact-close multiplier.
    if post_residual == 0 && progress > 0.75 {
        score -= 55.0 * progress;
    }

    // Fresh-bin last-resort tightening.
    if bin_residual == bin_capacity && progress > 0.7 && item_size < bin_capacity / 3 && post_residual > 20 && fitting_bins_count > 0 {
        score += 45.0 * progress;
    }

    // Dual-chain tileability — when the residual after this placement can be
    // split into next_item_size plus a small filler (<= 6) with zero waste,
    // this is a decisive two-step plan; reward strongest when the stream is
    // late and bins are scarce.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 6 {
            let urgency = if progress > 0.5 { 1.5 } else { 1.0 };
            score -= 46.0 * urgency;
        }
    }

    // Crowding-aware tight-fit amplifier — when many bins are open AND
    // several fit, extra weight on the tightest fit compounds consolidation
    // and closes fragments early.
    if open_bins_count > 5 && fitting_bins_count > 2 && post_residual > 0 && post_residual <= 20 {
        score += (post_residual as f64) * 0.9;
    }

    // Next-item large rescue — if the next item is large (> capacity/3) and
    // this placement leaves a residual that cannot hold it, tax mildly so
    // bins preserving room for it win, but only when alternatives exist.
    if next_item_size > 0 && next_item_size > bin_capacity / 3 && post_residual > 0
        && post_residual < next_item_size && fitting_bins_count > 1 {
        score += 18.0 * (1.0 - progress).max(0.3);
    }

    // NEW (mutation): mid-band dead-space ramp extension — the quadratic
    // gradient above stops at 30; extend a gentler linear ramp to 60 so
    // medium leftovers are also ranked continuously, shrinking residual
    // variance in the 30-60 band where dead space accumulates.
    if post_residual > 30 && post_residual <= 60 {
        score += 5.0 + (post_residual as f64 - 30.0) * 0.75;
    }

    // NEW (mutation): variance-killer tiebreak — among competing bins with
    // equal-ish fits, prefer the one whose post-residual lands closest to
    // the mean residual (harmonizes future fill opportunities).
    if fitting_bins_count > 1 && post_residual > 0 && post_residual <= 80 {
        let dist = ((post_residual as f64) - mean_residual).abs();
        score += dist * 0.55;
    }

    // NEW (mutation): exact-two-fill sweep — residual that can hold exactly
    // two copies of the next item with zero waste is a guaranteed future
    // close; reward scaled by how late in the stream we are.
    if next_item_size > 0 && post_residual == 2 * next_item_size && next_item_size > 0 {
        score -= 40.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction bands. Small post_residual classes are good.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Integer-division thresholds on post_residual (harmonic classes:
    // 0..=5 tiny, 6..=15 small, 16..=30 medium, >30 large dead space)
    let class = post_residual / 10;
    match class {
        0 => score -= 12.0,             // near-perfect fit
        1 => score -= 7.0,              // good fit
        2 | 3 => score -= 2.0,          // acceptable
        _ => score += frac * 30.0,      // large dead space penalty
    }

    // Reward exact modulo harmonics: post_residual divisible by 10
    // leaves room for typical future items (sizes in harmonic classes).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current
    // item is large relative to capacity and mean residual is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        score += 20.0 - 15.0 * pressure - 10.0 * (item_size as f64 / bin_capacity as f64) - 5.0 * progress;
    }

    // Mild preference for tighter bins overall (best-fit flavor) when
    // many bins are open.
    score += (bin_residual as f64 - mean_residual) * 0.05 * (open_bins_count.min(20) as f64 / 20.0);

    score
}

