    if post_residual > 0 && post_residual <= 20 && progress > 0.55 {
        score -= 12.0 * (1.0 - progress);
    }

    // NEW (mutation): fragmentation-closure coupling — with many open bins,
    // prefer placements that zero out a bin entirely to reduce open count.
    if post_residual == 0 && open_bins_count > 8 {
        score -= 20.0 + (open_bins_count.min(20) as f64) * 1.5;
