    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Archetype #47: strict dead-space avoidance + open-bin pressure.
    let mut score = post_residual as f64;

    // 1) Hard penalty for "unusable" dead space: gaps smaller than the
    //    minimum plausible item size (1..100 interface => use small threshold)
    //    are likely wasted forever. Penalize gaps in [1, 12) extra hard,
    //    with a smooth ramp so near-perfect fits are still favored.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 12.0 {
        score += (12.0 - gap) * 3.0; // up to +36 for a 1-unit sliver
    }

    // 2) Reward exact/near-exact fills (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 25.0;
    }

    // 3) Open-bin pressure: with many open bins, prefer consolidating into
    //    existing ones; when few bins are open, opening a new one is cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (4.0 + 6.0 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // 4) New-bin candidate (empty bin): base cost so we only open a new bin
    //    when existing bins would leave significant dead space.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.9 + pressure * 0.5;
        // If the next item could pair with the residual left here, opening
        // is more attractive (reserve space for lookahead pairing).
        if next_item_size > 0 && next_item_size <= bin_residual - item_size {
            score -= 15.0;
        }
        return score;
    }

    // 5) Last-chance bonus: if this is the ONLY bin that fits, strongly
    //    prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // 6) Lookahead coupling: if the leftover gap exactly accommodates the
    //    next item, this placement is especially valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover too small for the known next item: mild penalty
        score += 6.0;
    }

    // 7) Prefer bins whose residual is already below average (filling
    //    tighter bins first keeps larger gaps available elsewhere).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

