        score -= 24.0 * scarcity_w * (13.0 - post_residual as f64) / 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the next item fits exactly into the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 + 0.5 * slack; // strong reward for chainable placement
    }
    // Penalize post residual that no plausible item can use (dead space)
    if next_item_size > post_residual {
        score += 0.3 * post_residual as f64;
    }

    // Prefer bins tighter than the mean residual (good fit)
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize slightly unless open bins are all poor fits
    if bin_residual == bin_capacity {
        score += 10.0;
        // open a new bin only if no existing bin gives a tight fit
        if post_residual as f64 > mean_residual {
            score += 15.0;
        }
    }

    score
}

