    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_tight = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 8.0 * pair_tight;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        // Dead space too small for next item: mild penalty.
        score += 3.0;
