    // Last-chance bonus: only bin that fits — avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in stream, be pickier about waste; late, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate: empty bin. Prefer opening a new bin only when current
    // placement would leave large waste or this bin is a poor fit.
    if bin_residual == bin_capacity {
