pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: waste-aware quadratic in post-residual (favor small leftover),
    // slightly smoothed so zero-residual is strongly preferred.
    let mut score = 2.0 * x * x - 1.2 * x + 0.6;

    // Non-linear coupling with stream progress: early in the stream,
    // tolerate larger residuals (bins can be topped up later); late in
    // the stream, punish residual waste more aggressively.
    let progress_coupling = (0.9 * progress + 0.1) * (x * x) * (1.0 - x + 0.05);
    score += 2.5 * progress_coupling;

    // Interaction with mean residual: if the fleet of open bins is loose,
    // prefer tightening this one (small post_residual) even more.
    let mean_norm = mean_residual / cap;
    score += 0.8 * mean_norm * (x * x);

    // Lookahead: reward if next item could use the post-residual,
    // punish if post-residual is "almost enough" for the next item
    // (dead space trap).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 1.5 * fit_quality * fit_quality;
        } else {
            let gap = (nxt - pr) / cap;
            score += 1.0 * gap * (1.0 - gap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // New-bin candidate: make it attractive only when no open bin is a
    // good fit — penalize it otherwise, scaled by how many bins fit.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        // Early stream: opening bins is cheap; late: prefer consolidation.
        score = 1.8 + 1.5 * scarcity - 1.2 * (1.0 - progress);
        // If next item is huge, a fresh bin is valuable.
        if next_item_size > 60 {
            score -= 0.8;
        }
    }

    score
}

