    // 30..=70 dead band so large-but-reusable leftovers lose to tight fits
    // even when all tier bonuses are zero.
    if post_residual > 30 && post_residual <= 70 {
        score += 0.45 * (post_residual as f64 - 30.0);
    }

    // NEW (gen 32): pair-closure precision — when current+next leaves a
    // residual of exactly 0..=3, this is a near-perfect two-step plan;
    // sharpen the existing pair bonus with a scarcity multiplier.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let after_pair = bin_residual - item_size - next_item_size;
        if after_pair <= 3 {
            let scarcity = if fitting_bins_count <= 3 { 1.4 } else { 1.0 };
            score -= 60.0 * scarcity;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover is.
    // Residuals that are multiples of common item sizes (10, 20, 25, 50) are valuable.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fill
    } else if pr % 50 == 0 {
        -35.0
    } else if pr % 25 == 0 {
        -22.0
    } else if pr % 20 == 0 {
        -18.0
    } else if pr % 10 == 0 {
        -12.0
    } else if pr < 10 {
        25.0 // dead space below minimum item size
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division thresholds: penalize leaving a residual in a "hard to fill" band
    let band = pr / 10; // 0..10 bands
    let band_penalty: f64 = match band {
        0 => 20.0,
        1 => 8.0,
        2 | 3 => -4.0,
        4 | 5 => -8.0,
        _ => 0.0,
    };
    score += band_penalty as f64;

    // Lookahead coupling: reward residuals that can exactly host the next item,
    // penalize residuals that just barely fail to host it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
        // Harmonic: residual divisible by next item size is reusable
        if next_item_size > 0 && pr % next_item_size == 0 && pr > 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Congestion: many open bins with slack -> prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let congestion = (open_bins_count as f64).ln() + 1.0;
    score -= congestion * (mean_residual / cap) * 5.0;

    // Slight preference for tighter fits as stream progresses (first-fit-decreasing flavor)
    score += progress * (item_size as f64 / cap) * 4.0;

    // New-bin candidate: make it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if mean_residual / cap < 0.15 {
            score -= 30.0; // open bins nearly full anyway
        }
    }

    score
}

