        // so we don't push ourselves into opening a bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Reward placements that leave a gap exactly (or nearly) fitting the next item.
        let tight_fit = (post_residual as f64 - next_item_size as f64).abs();
        score -= 6.0 / (1.0 + tight_fit);
    }

    // Perfect fit bonus: leaving nothing behind is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Penalize very small residual gaps (< 10) that are likely dead space forever.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (avoid spreading); with few open bins, new bins are cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.3 + 0.4 * progress);
    score += bin_pressure * (bin_residual as f64 / bin_capacity as f64) * 0.5;

    // Mean residual coupling: if average residual across open bins is small,
    // bins are nearly full -> strongly prefer existing bins over opening new.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin unless existing bins
        // have large residuals (poor fits) or many bins are already open.
        let mean_r = mean_residual.max(0.0);
        let new_bin_penalty = 25.0 - 0.15 * mean_r - 1.2 * open_bins_count as f64;
        score += new_bin_penalty.max(2.0);
    }

    // Slight preference for bins whose residual is close to item size (tight fit).
    let fit_tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= 3.0 / (1.0 + fit_tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
            score -= 32.0;
        }
    }

    // Pair exactness — residual exactly equals current+next is a jackpot.
    if pair > 0 && bin_residual == pair {
        score -= 266.0;
    }

    // Multi-fill potential.
    if next_item_size > 0 && post_residual >= next_item_size {
        let multi = post_residual / next_item_size;
        if multi >= 2 {
            score -= 22.0 * (multi.min(4) as f64);
        }
    }

    // Reusability shaping.
    if post_residual > 0 {
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 30.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
    }

    // Exact-complement chain.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 68.0;
        }
    }

    // Avoid leaving residuals just below the next item size (dead pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
    }

    // Harmonic-fit bonus.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0) {
        score -= 35.0;
    }

    // Mid-band residual shaping — reward exactly-fillable remainders,
    // punish near-miss remainders just above the next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
    }

    // Fit-quality gradient among competing bins.
    if fitting_bins_count > 1 && post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size as f64).max(1.0);
        if waste_ratio < 0.15 {
            score -= 58.0;
        } else if waste_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Three-item chain check — current + next + a small filler (1..=10)
    // exactly fills this bin's residual.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let chain = bin_residual - item_size - next_item_size;
        if chain >= 1 && chain <= 10 {
            score -= 88.0;
