    if post_residual > 0 && post_residual < next_item_size && progress > 0.6 && next_item_size > 20 {
        score -= 14.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post_residual (tight fit), with diminishing returns.
    let mut score = (post_residual as f64).powf(1.35);

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain bonus: next item exactly consumes the leftover.
        if post_residual == next_item_size {
            score -= 60.0 * (1.0 + progress);
        } else if next_item_size <= post_residual {
            // Next item fits: bonus scaled by how close the match is.
            let closeness = 1.0 - gap / (bin_capacity as f64);
            score -= 25.0 * closeness * closeness;
        } else {
            // Next item cannot fit in the leftover: penalize dead space creation.
            score += 8.0 + 0.35 * gap;
        }
    } else {
        // Last item: any residual is pure waste; penalize proportionally more.
        score += post_residual as f64 * 0.5;
    }

    // Coupling with mean residual: bins far below mean residual are "precious" space;
    // penalize wasting them on loose fits, reward using them when fit is tight.
    let residual_deficit = mean_residual - bin_residual as f64;
    if residual_deficit > 0.0 {
        // This bin has less space than average -> scarce capacity.
        score += residual_deficit * (post_residual as f64 / bin_capacity as f64) * 0.9;
    } else {
        // Roomier than average bin: slight reward for consuming its slack.
        score += residual_deficit * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate (empty bin): penalize so we only open when fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.8 * open_bins_count as f64;
        // But if next item also large, opening fresh may be wise: soften penalty.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0;
        }
    }

    // Early-stream: be slightly more willing to open bins (build diverse residuals).
    score -= (1.0 - progress) * 6.0;

    // Mild preference for keeping number of open bins low.
    score += open_bins_count as f64 * 0.4;

    score
}

