    // fragmentation of near-full bins.
    if fitting_bins_count <= 3 && post_residual > 0 && post_residual <= 4 {
        score -= 24.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose leftover is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if the next item fits into the post-residual,
    // penalize if this placement strands space the next item could use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size && post_residual > 0 {
            score += 4.0 * (post_residual as f64) / (bin_residual as f64);
        }
        // Penalize leaving a gap slightly larger than next item (classic trap).
        if post_residual > 0 && post_residual < next_item_size + 3 {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 + 15.0 * progress;
    }

    // New-bin candidate: make it attractive only when open bins would leave
    // lots of dead space or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let dead_elsewhere = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).max(0.0)
        } else {
            0.0
        };
        score -= 5.0;
        // Late stream: prefer filling existing bins, penalize opening new ones.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If existing bins waste a lot, opening fresh is fine.
        score -= dead_elsewhere * 0.3;
        // Many open bins with slack: discourage yet another bin.
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    // Penalize placing small items into nearly-full bins (waste of a scarce slot),
    // but only mid-stream when many items remain.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if item_size < 20 && bin_residual < 40 && progress < 0.7 {
        score += 6.0;
    }

    // Mild preference for balancing residuals against the mean.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

