    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: waste minimization with non-linear penalty on small residuals
    let mut score = pr as f64;

    // Non-linear coupling of post residual with stream progress:
    // later in the stream, tight fits (small post_residual) are more valuable,
    // large leftover space becomes more penalizing.
    let tightness = (-x * x).exp(); // high when post_residual small
    let progress_weight = t * (1.0 - t) * 4.0; // smooth bump peaking mid-stream
    score -= tightness * (1.0 + 3.0 * t) * 8.0;
    score += x * x * (1.0 + 2.0 * t) * 10.0;

    // Smooth interaction: residual vs mean residual deviation
    let dev = (mean_residual - pr) / cap;
    score += 4.0 * dev * dev * cap * (0.5 + t);

    // Last-chance bonus (only fitting bin): reward strongly, scaled by progress
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * t;
    }

    // Lookahead coupling: if next item fits the post residual, reward smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_slack = pr - nx;
        if fit_slack >= 0.0 {
            let s = fit_slack / cap;
            score -= 12.0 * (-s * s * 4.0).exp();
        } else {
            let s = (-fit_slack) / cap;
            score += 6.0 * (1.0 - (-s * s * 4.0).exp()) * (0.5 + t);
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless existing
    // bins fit poorly; smooth decay of new-bin attractiveness over stream.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln() + 1.0;
        score += 30.0 * (1.0 - t) + 10.0 * crowding;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild congestion term: many open bins with slack -> favor filling them
    let congestion = open_bins_count as f64 * mean_residual / cap;
    score -= 2.0 * congestion / (1.0 + congestion);

    // Smooth polynomial progress coupling as final modulation
    score *= 1.0 + 0.15 * (t - 0.5) * (t - 0.5);

    score
}

