    }

    // NEW: two-step dead-space sweep — if the residual after placing the
    // next item would still be an awkward mid-pocket (11..=24) that few
    // future items can split, tax it so tighter two-step plans win.
    if next_item_size > 0 && post_residual > next_item_size && fitting_bins_count > 1 {
        let after_next = post_residual - next_item_size;
        if after_next >= 11 && after_next <= 24 {
            score += 10.0 + (after_next as f64 - 10.0) * 0.9;
        }
    }

