    // close to the end we are.
    if progress > 0.6 && post_residual > 0 && post_residual <= 30
        && (post_residual % 5 == 0) && fitting_bins_count > 1 {
        score -= 24.0 * progress;
    }

    // NEW: fragment-anchor preference — when open bins are numerous and the
    // mean residual is small (fragments everywhere), prefer the bin whose
    // post-residual lands within ±3 of the mean so future medium items can
    // sweep many bins uniformly.
    if open_bins_count > 4 && mean_residual > 4.0 && post_residual > 0 {
        let d = ((post_residual as f64) - mean_residual).abs();
        if d <= 3.0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact or near-exact match with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step match: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards: reward, scaled by tightness of match
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
            // Bonus if next item fills bin completely after two placements
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // Next item won't fit after this placement: penalize leftover dead space
            score += 10.0 + diff * 0.15;
        }
        // Small chained-fill reward: item + next item nearly fill the bin
        let two_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        if two_fill > 0.9 && bin_residual >= item_size + next_item_size {
            score -= 15.0 * (two_fill - 0.9) * 10.0;
        }
    }

    // Penalize large unusable residuals (dead space nothing typical can use)
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny residual = near-perfect fill
    }
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.3;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = bin_capacity as f64 * 0.85;
        // If item would leave a perfectly reusable residual for the next item,
        // opening a new bin becomes attractive
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 70.0;
        }
        if fitting_bins_count == 0 {
            score -= 90.0; // no alternative: new bin is fine
        } else if fitting_bins_count == 1 {
            score += 10.0; // an existing last-chance bin exists; prefer it
        }
        // Late in stream, slightly discourage spreading into new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for compacting among many open bins
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

