pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Normalized post-residual
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    // Early stream: mild quadratic; late stream: strong cubic penalty on large residuals
    let poly = x * x * (0.6 + 1.4 * progress) + x.powi(3) * (0.4 + 2.2 * progress);

    // Tight fits reward: small post_residual gets a smooth subtractive term
    let tight_bonus = -(1.0 - x).powi(4) * (2.0 + 3.0 * progress);

    // Last-chance bin: strong reward to use it rather than open a new bin
    let last_chance = if fitting_bins_count == 1 { -3.5 } else { 0.0 };

    // Lookahead: reward if next item fits into post_residual (smooth coupling)
    let lookahead = if next_item_size > 0 {
        let fits = (next_item_size as f64 <= pr) as i32 as f64;
        let slack = (pr - next_item_size as f64).max(0.0) / cap;
        -fits * (1.5 - slack * 1.2)
    } else {
        0.0
    };

    // Penalize bins whose residual is far from mean residual (fragmentation smoothing)
    let spread = (pr - mean_residual) / cap;
    let spread_pen = spread * spread * 0.8;

    // New-bin candidate: baseline cost that grows with stream progress so late
    // stream prefers filling existing bins unless fit is very poor
    let new_bin_cost = if bin_residual == bin_capacity {
        2.0 + 3.0 * progress + poly
    } else {
        0.0
    };

    let mut score = pr as f64 * (0.5 + progress) + poly + tight_bonus + last_chance + lookahead + spread_pen + new_bin_cost;
    score
}

