    if open_bins_count > 5 && fitting_bins_count > 2 && post_residual > 0 && post_residual <= 20 {
        score += (post_residual as f64) * 0.9;
    }

    // Next-item large rescue — if the next item is large (> capacity/3) and
    // this placement leaves a residual that cannot hold it, tax mildly so
    // bins preserving room for it win, but only when alternatives exist.
    if next_item_size > 0 && next_item_size > bin_capacity / 3 && post_residual > 0
        && post_residual < next_item_size && fitting_bins_count > 1 {
        score += 18.0 * (1.0 - progress).max(0.3);
    }

    // NEW: mid-band waste sharpening — residuals in 21..35 are the most
    // common dead-space band; tax them progressively unless they exactly
    // tile with the next item size, in which case reward instead.
    if post_residual >= 21 && post_residual <= 35 {
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 20.0;
        } else {
            score += 10.0 + (post_residual - 21) as f64 * 0.8;
        }
    }

    // NEW: scarcity-weighted exact-fill — when few bins can fit the item,
    // an exact zero-residual placement is doubly valuable because it
    // prevents a new bin from ever being opened for this item.
    if post_residual == 0 && fitting_bins_count <= 2 && open_bins_count > 2 {
        score -= 35.0 * (1.0 - progress).max(0.4);
    }

    // NEW: smooth tie-breaker toward the fullest usable bin — a mild
    // linear gradient on bin_residual that breaks ties among near-equal
    // post-residual candidates in favor of consuming the largest slack.
    if bin_residual < bin_capacity {
        score += (bin_residual as f64) * 0.06;
    }

    // NEW: late-stream three-item chain — when the stream is late, reward
    // placements whose residual can hold next plus any small filler
    // (1..=12) exactly, converting fragments into closed bins.
    if progress > 0.6 && next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 12 {
            score -= 30.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual is an exact divisor class of capacity (perfect packing zones)
    if post_residual == 0 {
        score -= 60.0; // perfect fit, strongly favored
    } else {
        // Residual harmonic bucket: which fifth of the capacity does it fall in?
        let bucket = (pr / (cap / 5.0)).floor() as i64; // 0..4
        score += bucket as f64 * 6.0; // prefer bins whose leftover falls in the lowest bucket

        // Modular penalty: residuals that are "awkward" modulo common item classes.
        // Items in 1..100; common small classes: <=10, <=20, <=50.
        let mod10 = post_residual % 10;
        if mod10 != 0 && mod10 < 3 {
            score += 8.0; // tiny unusable sliver (1-2 units) is dead space
        }
        let mod20 = post_residual % 20;
        if mod20 != 0 && mod20 < 5 && post_residual < 20 {
            score += 6.0; // small bin with non-harmonic leftover
        }

        // Integer-division thresholds: can a "typical" next item fit?
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // Lookahead fits: reward, especially if it exactly fills (harmonic pair)
                score -= 10.0;
                if next_item_size == post_residual {
                    score -= 25.0; // chain of perfect fits
                }
                // Reward proportional fit quality (fraction of residual consumed)
                let frac = next_item_size as f64 / pr;
                score -= 12.0 * frac;
            } else {
                // Lookahead does NOT fit: penalize creating a bin the next item can't use
                score += 5.0 + 0.1 * (next_item_size - post_residual) as f64;
            }
        } else {
            // Last item: just minimize leftover
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        if post_residual <= 5 {
            score -= 20.0; // near-perfect last-chance fit
        }
    }

    // New-bin candidate handling: empty bin gets a baseline so it only wins
    // when open bins have bad (large, non-harmonic) residuals.
    if bin_residual == bin_capacity {
        // Neutral-ish starting point: slightly above a good fit, below a bad one.
        score = cap * 0.55;
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
        // Many open bins with slack: discourage new bins.
        score += 3.0 * open_bins_count as f64 * (mean_residual / cap).max(0.0);
    } else {
        // Prefer filling fuller bins (small residual before placement).
        score += 0.15 * (bin_residual as f64 - item_size as f64).max(0.0);
        // Slight preference when bin residual is below mean (this bin is tighter).
        score += 0.2 * (mean_residual - bin_residual as f64);
    }

    score
}

