    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin
    // offers a decent fit (item much smaller than best residual).
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64;
