        // fresh bin preserves a big residual for the next item.
        if next_item_size > 0 && next_item_size > item_size + 20 {
            new_bin_penalty -= 35.0;
        }
        // Late in the stream, avoid opening bins with tiny leftover utility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty += progress * 10.0;
        score += new_bin_penalty;
    }

    // Mild penalty for very small post_residual that is still nonzero
    // (fragmentation), but less than the reward for tight matches.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
