pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for leaving little waste.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness) * (1.0 - tightness) * item_size as f64;

    // Penalize dead space that no plausible future item can use.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    } else {
        // Last item: fill any bin as tightly as possible.
        score -= 30.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Too many open bins with large mean residual: prefer consolidating.
    let mean_res = mean_residual;
    if mean_res > 20.0 && open_bins_count > 2 {
        score += 0.35 * mean_res * (open_bins_count as f64).ln();
    }

    // Early stream: be slightly conservative about opening new bins;
    // late stream: allow new bins to preserve flexibility.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let horizon = 1.0 - progress;
        score += 8.0 + 14.0 * progress - 4.0 * horizon;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin pairs well with upcoming large item
        }
    }

    // Prefer filling bins whose residual is close to item size (exact-ish match).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score -= 10.0 / (1.0 + gap * gap * 0.02);

    // Mild preference for bins with smaller residual overall (best-fit flavor).
    score += 0.08 * bin_residual as f64;

    // Open-bin count pressure: with many open bins, discourage new bins more.
    if new_bin && open_bins_count > 4 {
        score += 2.0 * open_bins_count as f64;
    }

    score
}

