    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residuals that cannot hold typical small items are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic class: post_residual divisible by common item sizes (10,20,25,50)
    // means the leftover is reusable -> reward.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 12.0; }
        if post_residual % 25 == 0 { score -= 8.0; }
        if post_residual % 50 == 0 { score -= 6.0; }
