    // Mild pressure to prefer fuller bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post / cap);

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the mean (placing into below-average-residual bins consolidates).
    score += 0.10 * (post - mean_residual);

    score
}

