pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever be useful
    // (below the minimum item size 1 is fine, but gaps below a usable
    // threshold that cannot fit the NEXT item are pure waste).
    let dead_threshold = if next_item_size > 0 { next_item_size.min(40) } else { 10 };
    if post_residual < dead_threshold {
        // Small gap that likely becomes dead space -> heavy penalty.
        score += 60.0 + (dead_threshold - post_residual) as f64 * 2.0;
    } else if post_residual == 0 {
        // Perfect fill -> strong reward.
        score -= 80.0;
    } else if post_residual >= dead_threshold && post_residual <= 30 {
        // Tight-but-usable gap -> mild reward for compact packing.
        score -= 15.0;
    }

    // Coupling with lookahead: a gap exactly matching the next item is valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 8.0; // still usable for the lookahead item
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 20.0; // gap blocks the lookahead item
    }

    // Open-bin pressure: prefer consolidating into fewer bins when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).powf(1.3) * (0.15 + 0.35 * progress);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: make opening a new bin unattractive unless
    // the current fit is terrible (huge post_residual relative to capacity).
    if bin_residual == bin_capacity {
        // Empty candidate bin: neutral baseline plus a mild bias toward reuse.
        score = 55.0 + 0.5 * open_bins_count as f64;
        // Allow opening a new bin if every fit would waste a lot.
        if post_residual > 60 {
            score -= 70.0;
        }
    }

    // Alignment with mean residual: bins with residual near mean are "typical";
    // slight preference for bins with less residual (tighter bins first).
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    score
}

