pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if next_item_size > 0 {
        let next = next_item_size as f64;
        // Perfect 2-step lookahead: post_residual exactly matches next item
        let gap = (post_residual as f64 - next).abs();
        score += gap * 1.5;
        // Reward if next item fits exactly after this placement
        if post_residual as f64 == next {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // next item still fits here: mild reward proportional to snugness
            score -= (post_residual as f64 - next).min(30.0) * 0.5;
        } else {
            // next item won't fit: penalize dead space, worse when post_residual tiny
            let dead = post_residual as f64;
            score += (15.0 - dead.min(15.0)) * 2.0;
        }
    }

    // Penalize very small unusable leftovers
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit_penalty = (mean_residual - item_size as f64).max(0.0);
        score += 60.0 - poor_fit_penalty * 2.0 - progress * 10.0;
    } else {
        // Favor bins tighter than the mean residual (best-fit flavor)
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    score
}

