    // several fit, extra weight on the tightest fit compounds consolidation.
    if open_bins_count > 5 && fitting_bins_count > 2 && post_residual > 0 && post_residual <= 20 {
        score += (post_residual as f64) * 0.9;
    }

    // Next-item large rescue — if the next item is large (> capacity/3) and
    // this placement leaves a residual that cannot hold it, tax mildly so
    // bins preserving room for it win, but only when alternatives exist.
    if next_item_size > 0 && next_item_size > bin_capacity / 3 && post_residual > 0
        && post_residual < next_item_size && fitting_bins_count > 1 {
        score += 18.0 * (1.0 - progress).max(0.3);
    }

    // NEW: mid-band dead-space refinement — extend the smooth quadratic
    // gradient into the 31..=60 band with a gentler slope so mid-size
    // leftovers are also ranked continuously rather than flat.
    if post_residual > 30 && post_residual <= 60 {
        score += 1.1 * (post_residual as f64 - 30.0);
    }

    // NEW: harvest-match gradient — when several bins fit, prefer the one
    // whose post-residual exactly equals a plausible future item (any size
    // 1..=100 that is a multiple of 10 or matches next_item_size), turning
    // leftovers into planned future homes instead of dead space.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual <= 100 {
        let matched = (post_residual == next_item_size && next_item_size > 0)
            || post_residual % 10 == 0;
        if matched {
            score -= 20.0 + (1.0 - progress) * 14.0;
        }
    }

    // NEW: two-fit lookahead tiebreak — with exactly two candidate bins,
    // sharpen the comparison between their post-residuals so the tighter
    // one wins decisively, reducing residual variance across the stream.
    if fitting_bins_count == 2 && post_residual > 0 {
        score += (post_residual as f64) * 0.6;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit core with slight superlinear penalty on wasted space.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_frac * waste_frac * (bin_capacity as f64);

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving residual too small to be useful for the next item.
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; make the empty
    // bin attractive only when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if fitting_bins_count > 0 {
            // Compare best possible fit against this item: if mean residual is
            // much larger than item, open bins are loose; still prefer them.
            ((mean_residual - item_size as f64) / bin_capacity as f64).abs()
        } else {
            1.0
        };
        // Cost of a new bin grows with number of open bins and stream progress.
        score += 30.0 + 2.5 * openness + 15.0 * progress;
        // If open bins fit poorly (mean residual close to item => tight fit), a
        // new bin becomes more attractive: reduce its score.
        score -= 20.0 * (1.0 - poor_fit);
    } else {
        // Mild bonus for using bins whose residual is close to the item (tight fit).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 5.0 * tightness;
    }

    // Global state: when many bins are open with large mean residual, prefer
    // consolidating into them (penalize spreading).
    score += 0.05 * mean_residual * (open_bins_count as f64).ln().max(1.0) * 0.1;

    score
}

