}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, but with non-linear saturation
    let mut score = 60.0 * norm_pr + 40.0 * norm_pr * norm_pr;

    // Smooth stream-progress coupling: later in stream, penalize waste more strongly
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits with smooth exponential term
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness * tightness;

    // Last-chance bonus: strongly favor the only fitting bin (smooth logistic-like)
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 30.0 * last_chance;

    // Lookahead: reward bins whose post_residual fits next item (smooth gaussian affinity)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        let sigma = 12.0;
        score -= 18.0 * (-gap * gap / (2.0 * sigma * sigma)).exp();
    }

    // Mild penalty for spreading across many bins vs mean residual alignment
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: neutral-to-slightly-high baseline unless waste is unavoidable
    if bin_residual == bin_capacity {
        score += 10.0 - 10.0 * progress;
    }

    score
}

