pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // Next item fits exactly-ish: strong reward scaled by tightness
            score -= (30.0 / (1.0 + diff)) - 0.5 * diff;
        } else {
            // Next item won't fit: penalize proportional dead space
            score += 0.3 * diff;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin before opening a new one: strong reward
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins fit, more so early in stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - 20.0 * progress;
    }

    // Slight preference for fuller bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

