    }

    // Residual-efficiency gradient — smooth secondary term breaking ties
    // toward the tightest fit; directly reduces dead space.
    if fitting_bins_count > 1 && post_residual > 0 && post_residual <= 40 {
        score += (post_residual as f64) * 1.8;
    }

    // Next-item dead-space guard.
    if next_item_size > 0 && next_item_size <= 20 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.5;
    }

    // Crowded-state exact-close emphasis.
    if post_residual == 0 && open_bins_count > 3 {
        score -= 30.0 + (open_bins_count.min(12) as f64) * 4.0;
    }

    // Total-waste budget coupling.
    if post_residual > 0 && open_bins_count > 1 {
        let projected = (post_residual as f64 + mean_residual * (open_bins_count as f64 - 1.0)) / open_bins_count as f64;
        if projected > 12.0 {
            score += (projected - 12.0).min(25.0) * 0.9;
        } else if projected < 6.0 {
            score -= 12.0;
        }
    }

    // Complement-tile lookahead.
    if next_item_size > 0 && next_item_size < bin_capacity && fitting_bins_count > 1 && post_residual > 0 {
        let next_complement = bin_capacity - next_item_size;
        let diff = next_complement as i32 - post_residual as i32;
        if diff >= 0 && diff <= 4 {
            score -= 48.0 - diff as f64 * 6.0;
        }
    }

    // Residual-harvest sequencing.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
        && mean_residual < next_item_size as f64 && fitting_bins_count > 1 {
        score += (next_item_size - post_residual) as f64 * 1.4;
    }

    // Dead-space budget coupling (sharpened variant).
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 4.0 + 0.35 * (post_residual as f64 - mean_residual).min(18.0);
    }

    // Continuous dead-space gradient — smooth quadratic ramp so near-tight
    // fits are ranked continuously, cutting residual variance.
    // (refined: extended to 40 and slightly steeper to attack dead space)
    if post_residual > 5 && post_residual <= 40 {
        let d = post_residual as f64 - 5.0;
        score += 0.62 * d * d / 25.0;
    }

    // Late-stream exact-close multiplier.
    if post_residual == 0 && progress > 0.75 {
        score -= 55.0 * progress;
    }

    // Fresh-bin last-resort tightening.
    if bin_residual == bin_capacity && progress > 0.7 && item_size < bin_capacity / 3 && post_residual > 20 && fitting_bins_count > 0 {
        score += 45.0 * progress;
    }

    // Dual-chain tileability — residual after placement splits into
    // next_item_size plus a small filler (<= 6) with zero waste.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 6 {
            let urgency = if progress > 0.5 { 1.5 } else { 1.0 };
            score -= 46.0 * urgency;
        }
    }

    // Crowding-aware tight-fit amplifier.
    if open_bins_count > 5 && fitting_bins_count > 2 && post_residual > 0 && post_residual <= 20 {
        score += (post_residual as f64) * 0.9;
    }

    // Next-item large rescue.
    if next_item_size > 0 && next_item_size > bin_capacity / 3 && post_residual > 0
        && post_residual < next_item_size && fitting_bins_count > 1 {
        score += 18.0 * (1.0 - progress).max(0.3);
    }

    // NEW: mid-band dead-space compaction — residuals in the 26..=48 band
    // are the largest untapped waste source; tax them progressively so
    // placements leaving such pockets lose against tighter alternatives,
    // unless the pocket is exactly tileable by the next item.
    if post_residual >= 26 && post_residual <= 48 {
        let tileable = next_item_size > 0 && post_residual % next_item_size == 0;
        if !tileable {
            let center = 37.0;
            let d = (post_residual as f64 - center).abs();
            score += 20.0 + 0.8 * (48.0 - d).max(0.0);
        }
    }

    // NEW: perfect-closure sweep — when the current item plus the next item
    // exactly consumes the bin's remaining residual, this is a guaranteed
    // zero-waste two-step plan; reward decisively, scaled by stream phase.
    if next_item_size > 0 && bin_residual > item_size && bin_residual - item_size == next_item_size {
        score -= 130.0 + 60.0 * progress;
    }

    // NEW: fragmentation sink — when many bins are open, residuals just
    // above a common item scale (multiples of 10) are harvestable; mildly
    // prefer leaving such harvestable pockets over awkward odd remainders.
    if open_bins_count > 5 && post_residual > 20 && post_residual % 10 != 0 {
        let m = post_residual % 10;
        score += m as f64 * 1.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: reward tight fits (small post_residual) with mild non-linearity.
    let mut score = 2.0 * x - 1.2 * x * x;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, larger residuals are tolerable; late in the stream, penalize them harder.
    let progress_coupling = (0.6 + 1.8 * t) * x * x * x - (0.9 * t) * x * x;
    score += progress_coupling * cap * 0.05;

    // Dead-space penalty: residuals too small to be useful later are punished
    // via a smooth bump around very small x.
    let dead = (1.0 - x).powi(6);
    score += 1.5 * dead * (1.0 - t);

    // Lookahead: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = x - nx;
        if gap >= 0.0 {
            score -= 0.8 * (1.0 - gap) * (1.0 - 0.5 * t);
        } else {
            score += 0.3 * (-gap);
        }
    }

    // Scarcity: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 2.0;
    } else if fitting_bins_count > 1 {
        score += 0.1 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Prefer bins below mean residual (consolidating space) with smooth term.
    score += 0.3 * (mean_residual - bin_residual as f64) / cap;

    // New-bin candidate: opening a fresh bin should only win when no open bin
    // offers a genuinely good fit; make the empty bin slightly unattractive,
    // more so early in the stream when consolidation matters most.
    if bin_residual == bin_capacity {
        score += 1.2 + 1.5 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
