pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: capacity fractions (1/4, 1/3, 1/2)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    }

    // Dead-space penalty for awkward residual classes
    if post_residual < 10 {
        score += 60.0; // tiny sliver is nearly unusable
    }

    // Harmonic bonus: residual that is an integer-division-friendly class
    let post = post_residual as f64;
    if post_residual >= quarter && post_residual < quarter + 5 {
        score -= 25.0;
    }
    if post_residual >= third && post_residual < third + 5 {
        score -= 20.0;
    }
    if post_residual >= half && post_residual < half + 5 {
        score -= 15.0;
    }

    // Lookahead coupling: can next item fit into post-residual exactly?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            // prefer leaving residuals that match harmonic classes of next item
            let ratio = nxt / post;
            if (ratio - 0.5).abs() < 0.08 {
                score -= 40.0;
            }
            if (ratio - 0.25).abs() < 0.05 {
                score -= 30.0;
            }
            // penalize leaving residual much larger than next item (waste)
            if nxt * 2.0 < post {
                score += (post - nxt * 2.0) * 0.5;
            }
        } else {
            // next item won't fit here: residual becomes dead space for lookahead
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive if current fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.1;
        if post_residual >= half {
            score -= 20.0;
        }
    }

    // Progress modulation: be pickier late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    // Prefer denser bins when many bins open
    score -= mean_residual.min(post) * 0.05;

    score
}

