    if fitting_bins_count == 1 && post_residual > 10 {
        score += (post_residual as f64) * 0.6;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Strong reward for perfect 2-step chain (post_residual == next_item_size)
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Gradient penalty: closer post_residual to next item is better
            score += diff * 0.35;
            // Extra penalty if next item cannot fit in the residual at all
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
        // Bonus if chain fits: item + next item both consumed tightly
        if post_residual >= next_item_size && post_residual <= next_item_size + 10 {
            score -= 15.0;
        }
    } else {
        // Last item: strongly prefer minimal post_residual
        score -= 40.0;
    }

    // Relative-to-mean coupling: bins tighter than mean are preferred targets
    score += (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating small unusable dead space (below typical minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Mild preference for filling nearly-full bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.05 * (0.5 + 0.5 * progress);

    // Discard new-bin option unless current open bins are all poor fits
    if bin_residual == bin_capacity {
        // New bin: base score = full residual, add opening cost
        score += 45.0 - (open_bins_count as f64 * 2.0);
        // If lookahead chains well into a fresh bin, soften the cost
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    score
}

