pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits with a strong non-linear bonus.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio * fill_ratio;
    score += 25.0 * waste_ratio * waste_ratio;

    // Lookahead coupling: if the next item fits the post-residual, reward;
    // if post-residual is too small for the next item, penalize dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 8.0 + 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer the fullest bin (small residual before placement).
        score += 0.35 * bin_residual as f64;
    }

    // Global state: penalize opening new bins when many bins are already open;
    // encourage consolidation when mean residual is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: cost grows with open bins count and stream progress.
        score += 15.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
        // But if mean residual across open bins is too small for typical items,
        // opening a new bin becomes attractive.
        if mean_residual < item_size as f64 {
            score -= 18.0;
        }
    } else {
        score -= 0.1 * mean_residual;
    }

    score
}

