    if remaining_frac < 0.15 && post_residual > 15 && post_residual < next_item_size.max(20) {
        score += 26.0 * (1.0 - remaining_frac * 6.0).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward near-perfect packing classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 200.0; // perfect fit
    } else if pr <= 5 {
        score -= 100.0;
    } else if pr <= 15 {
        score -= 40.0;
    } else if pr <= 30 {
        score -= 10.0;
    } else if pr > 50 {
        score += 30.0; // large dead space penalty
    }

    // Modulo classes: residuals divisible by common item sizes are more reusable.
    if pr > 0 {
        for m in [10u32, 20, 25, 50] {
            if pr % m == 0 {
                score -= 12.0;
            }
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 150.0;
        } else if next_item_size < pr && pr - next_item_size <= 10 {
            score -= 60.0;
        } else if next_item_size > pr {
            score += 25.0; // next item won't fit here; keep residual flexible
        }
        // harmonic class match between next item and residual
        let cls = |x: u32| x / 10;
        if next_item_size > 0 && cls(next_item_size) == cls(pr) && pr >= next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0 + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // big items pair well in a fresh bin
        }
    }

    // Tightness ratio coupling with stream progression.
    let fill = 1.0 - (post_residual as f64) / cap;
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * fill * (0.5 + progress);

    // Relative residual vs mean residual: prefer bins below-average residual (tighter bins).
    if mean_residual > 0.0 {
        score += 10.0 * (post_residual as f64 - mean_residual) / cap;
    }

    score
}

