    // several fit, extra weight on the tightest fit compounds consolidation
    // and closes fragments early.
    if open_bins_count > 5 && fitting_bins_count > 2 && post_residual > 0 && post_residual <= 20 {
        score += (post_residual as f64) * 0.9;
    }

    // Next-item large rescue — if the next item is large (> capacity/3) and
    // this placement leaves a residual that cannot hold it, tax mildly so
    // bins preserving room for it win, but only when alternatives exist.
    if next_item_size > 0 && next_item_size > bin_capacity / 3 && post_residual > 0
        && post_residual < next_item_size && fitting_bins_count > 1 {
        score += 18.0 * (1.0 - progress).max(0.3);
    }

    // NEW (gen 44 mutation): zero-waste sweep — a residual exactly equal to a
    // small multiple (2 or 3) of the next item is a guaranteed future fill;
    // deepen the existing divisibility reward with a progress-scaled kicker
    // so late-stream fragments are closed into perfect tiles.
    if next_item_size > 0 && post_residual > 0 && post_residual >= 2 * next_item_size {
        let k = post_residual / next_item_size;
        if (k == 2 || k == 3) && post_residual % next_item_size == 0 {
            score -= (22.0 + 30.0 * progress) * (k as f64 - 1.0);
        }
    }

    // NEW (gen 44 mutation): mean-anchored dead-space slope — placements
    // leaving residuals meaningfully ABOVE the fleet mean residual are the
    // primary source of accumulated dead space; apply a smooth progressive
    // tax so the tightest fits are preferred even among mid-band residuals.
    if post_residual > 0 && fitting_bins_count > 1 {
        let excess = post_residual as f64 - mean_residual;
        if excess > 0.0 {
            score += (excess * 0.45).min(18.0);
        } else if excess < -8.0 {
            score -= 10.0;
        }
    }

    // NEW (gen 44 mutation): fresh-bin exact-triple gate — open a new bin
    // only when current + 2x next tiles it exactly or leaves <= 2 slack;
    // this converts otherwise-wasted capacity into planned perfect fills.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let t3 = bin_capacity as i64 - (item_size as i64 + 2 * next_item_size as i64);
        if t3 >= 0 && t3 <= 2 {
            score -= 96.0 * (1.0 - progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any future
    // item (min item size 1, but practically small gaps < ~15) are wasted space.
    // Penalize unusable gaps quadratically.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, discourage opening another one;
    // the new-bin candidate has bin_residual == bin_capacity, so shift its score.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        // But if existing fits are terrible (large post_residual), new bin wins.
        if post_residual >= bin_capacity - item_size {
            score -= 0.0; // new bin residual is full capacity anyway
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; penalize leaving a gap that blocks the lookahead.
        score += 4.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (tighter bins get priority, keeping loose bins flexible).
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.15;

    // Slight early-stream preference for filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

