        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item exactly fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how tightly it fills
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 150.0 * tight;
        } else {
            // next item does NOT fit here: penalize wasted residual that next item can't use
            let waste = (next_item_size - post_residual).min(next_item_size) as f64;
            score += 0.5 * waste;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable targets
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev;

    // Penalize leaving awkward small residuals (dead space) unless next item matches
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 80.0;
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate: mildly discourage opening a new bin unless residuals are all poor
    if bin_residual == bin_capacity {
        let avg_poor = mean_residual < (item_size as f64);
        if !avg_poor {
            score += 120.0;
        } else {
            score += 20.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * post_residual as f64;

    // Prefer bins with small residuals overall (tight packing)
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

