        score += (next_item_size - post_residual) as f64 * 1.4;
    }

    // Dead-space budget coupling (sharpened variant).
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 4.0 + 0.35 * (post_residual as f64 - mean_residual).min(18.0);
    }

    // Continuous dead-space gradient — smooth quadratic ramp so near-tight
    // fits are ranked continuously, cutting residual variance.
    if post_residual > 5 && post_residual <= 30 {
        score += 0.55 * (post_residual as f64 - 5.0) * (post_residual as f64 - 5.0) / 25.0;
    }

    // Late-stream exact-close multiplier.
    if post_residual == 0 && progress > 0.75 {
        score -= 55.0 * progress;
    }

    // Fresh-bin last-resort tightening.
    if bin_residual == bin_capacity && progress > 0.7 && item_size < bin_capacity / 3 && post_residual > 20 && fitting_bins_count > 0 {
        score += 45.0 * progress;
    }

    // Dual-chain tileability — when the residual after this placement can be
    // split into next_item_size plus a small filler (<= 6) with zero waste,
    // this is a decisive two-step plan; reward strongest when late.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 6 {
            let urgency = if progress > 0.5 { 1.5 } else { 1.0 };
            score -= 46.0 * urgency;
        }
    }

    // Crowding-aware tight-fit amplifier — when many bins are open AND
    // several fit, extra weight on the tightest fit compounds consolidation.
    if open_bins_count > 5 && fitting_bins_count > 2 && post_residual > 0 && post_residual <= 20 {
        score += (post_residual as f64) * 0.9;
    }

    // Next-item large rescue — if the next item is large (> capacity/3) and
    // this placement leaves a residual that cannot hold it, tax mildly so
    // bins preserving room for it win, but only when alternatives exist.
    if next_item_size > 0 && next_item_size > bin_capacity / 3 && post_residual > 0
        && post_residual < next_item_size && fitting_bins_count > 1 {
        score += 18.0 * (1.0 - progress).max(0.3);
    }

    // NEW: mid-residual waste ramp — extend the continuous dead-space
    // gradient into the 31..60 band with a gentler slope, so mid-size
    // leftovers are also ranked against each other instead of being
    // treated as equivalent, further cutting residual variance.
    if post_residual > 30 && post_residual <= 60 {
        score += 5.0 + 0.22 * (post_residual as f64 - 30.0);
    }

    // NEW: perfect-pair-vs-fresh arbitration — when this placement leaves
    // exactly room for the next item (zero waste two-step plan), it should
    // dominate even a fresh-bin opening; sharpen the existing exact-match
    // bonus with a late-stream multiplier.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 0 {
        score -= 24.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here anyway; slight penalty for wasting capacity.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // New-bin candidate logic: empty bin should only win when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by global state.
        let mut open_cost = 18.0;
        // Early in the stream, opening bins is cheaper (build a portfolio).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        open_cost *= 0.6 + 0.8 * progress;
        // Many open bins with slack => discourage opening another.
        if open_bins_count > 2 && mean_residual > 30.0 {
            open_cost += 10.0;
        }
        // If item is small and mean residual is large, opening is wasteful.
        if (item_size as f64) < mean_residual * 0.5 {
            open_cost += 15.0;
        }
        score += open_cost;
    } else {
        // Slight preference for bins with residuals near item size (best-fit flavor).
        score += 0.05 * (bin_residual as f64 - item_size as f64);
        // Prefer bins whose residual deviates below the mean (consolidate slack).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Time-horizon coupling: late in the stream, be greedier about tight fits.
    if total_items > 0 {
        let late = step_index as f64 / total_items as f64;
        score -= 10.0 * late * fit_ratio;
    }

    // Mild penalty when many bins are open, to encourage closing bins out.
    score += 0.3 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
