    }

    // Residual-harvest sequencing.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
        && mean_residual < next_item_size as f64 && fitting_bins_count > 1 {
        score += (next_item_size - post_residual) as f64 * 1.4;
    }

    // Dead-space budget coupling (sharpened variant).
    if open_bins_count > 2 && post_residual >= 10 && post_residual <= 29 && (post_residual as f64) > mean_residual {
        score += 4.0 + 0.35 * (post_residual as f64 - mean_residual).min(18.0);
    }

    // Continuous dead-space gradient — smooth quadratic ramp so near-tight
    // fits are ranked continuously, cutting residual variance.
    if post_residual > 5 && post_residual <= 30 {
        score += 0.55 * (post_residual as f64 - 5.0) * (post_residual as f64 - 5.0) / 25.0;
    }

    // Late-stream exact-close multiplier.
    if post_residual == 0 && progress > 0.75 {
        score -= 55.0 * progress;
    }

    // Fresh-bin last-resort tightening.
    if bin_residual == bin_capacity && progress > 0.7 && item_size < bin_capacity / 3 && post_residual > 20 && fitting_bins_count > 0 {
        score += 45.0 * progress;
    }

    // Dual-chain tileability — when the residual after this placement can be
    // split into next_item_size plus a small filler (<= 6) with zero waste,
    // this is a decisive two-step plan; reward strongest when late.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 6 {
            let urgency = if progress > 0.5 { 1.5 } else { 1.0 };
            score -= 46.0 * urgency;
        }
    }

    // Crowding-aware tight-fit amplifier — when many bins are open AND
    // several fit, extra weight on the tightest fit compounds consolidation.
    if open_bins_count > 5 && fitting_bins_count > 2 && post_residual > 0 && post_residual <= 20 {
        score += (post_residual as f64) * 0.9;
    }

    // Next-item large rescue — if the next item is large (> capacity/3) and
    // this placement leaves a residual that cannot hold it, tax mildly so
    // bins preserving room for it win, but only when alternatives exist.
    if next_item_size > 0 && next_item_size > bin_capacity / 3 && post_residual > 0
        && post_residual < next_item_size && fitting_bins_count > 1 {
        score += 18.0 * (1.0 - progress).max(0.3);
    }

    // Mid-residual waste ramp — extend the continuous dead-space
    // gradient into the 31..60 band with a gentler slope, so mid-size
    // leftovers are also ranked against each other instead of being
    // treated as equivalent, further cutting residual variance.
    if post_residual > 30 && post_residual <= 60 {
        score += 5.0 + 0.22 * (post_residual as f64 - 30.0);
    }

    // Perfect-pair-vs-fresh arbitration — when this placement leaves
    // exactly room for the next item (zero waste two-step plan), it should
    // dominate even a fresh-bin opening; sharpen the existing exact-match
    // bonus with a late-stream multiplier.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 0 {
        score -= 24.0 + 30.0 * progress;
    }

    // NEW: near-exact tie-break — smooth cubic tie-breaker among near-tight
    // fits (1..=12) so the tightest placements win continuously, refined by
    // a scarcity multiplier when few bins can host the item.
    if post_residual >= 1 && post_residual <= 12 {
        let scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
        score += 0.9 * (post_residual as f64).powi(2) * scarcity;
    }

    // NEW: mid-residual mean-anchored tax — placements leaving a residual
    // well above the fleet's mean residual (i.e. hoarding space) are taxed
    // proportionally, pushing the packing toward uniform low-waste bins.
    if post_residual > 0 && open_bins_count > 2 && (post_residual as f64) > mean_residual * 1.6 {
        score += ((post_residual as f64) - mean_residual * 1.6).min(30.0) * 0.8;
    }

    // NEW: next-item triple-tile sweep — if after placing the next item the
    // leftover is an exact multiple of the item class (10s), the placement
    // sets up a clean chain; reward scaled by remaining stream.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after % 10 == 0 && after <= 40 {
            score -= 20.0 * (1.0 - progress).max(0.4);
        }
    }

    // NEW: late-stream fresh-bin suppression for tiny items — opening a new
    // bin for a very small item late in the stream is almost always waste;
    // penalize harder than the existing progress>0.85 gate.
    if bin_residual == bin_capacity && progress > 0.6 && item_size <= 15 && fitting_bins_count > 0 {
        score += 65.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 12.0 * poly;

    // Penalize residuals that are small relative to mean (fragmented bins)
    let mr = if mean_residual.is_finite() { mean_residual } else { cap };
    let ratio = if mr > 0.0 { pr / mr } else { 1.0 };
    score += 4.0 * (ratio - 1.0) * (ratio - 1.0) * (1.0 - progress);

    // Reward tight fits: quadratic bonus for small post_residual
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let fits = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 8.0 * fits * (1.0 - gap / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Slight penalty for many open bins (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

