    // bins preserving room for it win, but only when alternatives exist.
    if next_item_size > 0 && next_item_size > bin_capacity / 3 && post_residual > 0
        && post_residual < next_item_size && fitting_bins_count > 1 {
        score += 18.0 * (1.0 - progress).max(0.3);
    }

    // Mid-residual waste ramp — extend the continuous dead-space
    // gradient into the 31..60 band with a gentler slope, so mid-size
    // leftovers are also ranked against each other instead of being
    // treated as equivalent, further cutting residual variance.
    if post_residual > 30 && post_residual <= 60 {
        score += 5.0 + 0.22 * (post_residual as f64 - 30.0);
    }

    // Perfect-pair-vs-fresh arbitration — when this placement leaves
    // exactly room for the next item (zero waste two-step plan), it should
    // dominate even a fresh-bin opening; sharpen the existing exact-match
    // bonus with a late-stream multiplier.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 0 {
        score -= 24.0 + 30.0 * progress;
    }

    // NEW: global residual-gradient refinement — a smooth cubic-lite ramp
    // across the full 1..=100 residual range that continuously ranks bins
    // by leftover size, sharpening the 61..100 band which was previously
    // unshaped and letting mid-band waste compete fairly against it.
    if post_residual > 0 {
        let r = post_residual as f64;
        if r <= 100.0 {
            score += 0.045 * r * r / (1.0 + 0.02 * r);
        }
    }

    // NEW: two-step zero-waste chain plan — when placing the next item in
    // the post-residual would leave a residual exactly equal to a plausible
    // small filler (1..=12) that the stream commonly carries, reward the
    // placement as a guaranteed three-item fill, strongest mid-stream.
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= 60 {
        let after2 = post_residual - next_item_size;
        if after2 >= 1 && after2 <= 12 {
            score -= 30.0 + 20.0 * (1.0 - progress);
        }
    }

    // NEW: fresh-bin pair-waste floor — when opening a fresh bin, penalize
    // if the fresh residual after this item cannot accommodate the next
    // item at all AND every existing fitting bin could (fragmentation
    // avoidance: never strand a fresh bin with an unfittable pocket).
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let fresh_after = bin_capacity - item_size;
        if fresh_after < next_item_size {
            let any_bin_holds_next = mean_residual >= next_item_size as f64;
            if any_bin_holds_next {
                score += 65.0 * (1.0 - progress).max(0.3);
            }
        }
    }

    // NEW: late-stream residual-sweep bonus — near the end of the stream,
    // prefer the bin whose post-residual best matches the smallest plausible
    // remaining demand (mean_residual as proxy), driving final-bin closure.
    if progress > 0.6 && post_residual > 0 {
        let target = mean_residual.max(1.0);
        let dist = (post_residual as f64 - target).abs();
        if dist <= 10.0 {
            score -= 26.0 * (1.0 - dist / 10.0) * (progress - 0.6) / 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
            score -= 32.0;
        }
    }

    // Pair exactness — residual exactly equals current+next is a jackpot.
    if pair > 0 && bin_residual == pair {
        score -= 266.0;
    }

    // Multi-fill potential.
    if next_item_size > 0 && post_residual >= next_item_size {
        let multi = post_residual / next_item_size;
        if multi >= 2 {
            score -= 22.0 * (multi.min(4) as f64);
        }
    }

    // Reusability shaping.
    if post_residual > 0 {
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 30.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
    }

    // Exact-complement chain.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 68.0;
        }
    }

    // Avoid leaving residuals just below the next item size (dead pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
    }

    // Harmonic-fit bonus.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0) {
        score -= 35.0;
    }

    // Mid-band residual shaping — reward exactly-fillable remainders,
    // punish near-miss remainders just above the next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 2 {
            score -= 95.0;
        } else if rem <= 9 {
            score += 62.0;
        }
