        if progress > 0.8 && item_size <= bin_capacity / 2 && fitting_bins_count > 0 && post_residual > 12 {
            score += 30.0 * progress;
        }
        // Fresh-bin exact-triple sharpening.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let slack3 = bin_capacity as i64 - (item_size as i64 + 2 * next_item_size as i64);
            if slack3 >= 0 && slack3 <= 3 {
