        if fitting_bins_count > 0 && next_item_size > 0 && progress < 0.7 {
            let best_projected_waste = mean_residual.min(item_size as f64) - item_size as f64;
            if best_projected_waste > 12.0 && (bin_capacity as f64 - item_size as f64) >= next_item_size as f64 {
