    if post_residual > 30 && post_residual <= 60 {
        score += 5.0 + 0.22 * (post_residual as f64 - 30.0);
    }

    // Perfect-pair-vs-fresh arbitration — exact two-step plan dominates
    // fresh-bin opening; sharpened with a late-stream multiplier.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 0 {
        score -= 24.0 + 30.0 * progress;
    }

    // GEN 41 MUTATION: variance-crushing tight-fit ladder — fine-grained
    // continuous descent in the 1..=12 dead-space band.
    if post_residual > 0 && post_residual <= 12 && fitting_bins_count >= 1 {
        let ladder = 12.0 - post_residual as f64;
        score -= ladder * ladder * 0.85;
    }

    // GEN 41 MUTATION: perfect-closure urgency — near stream end, exact
    // closure is decisive because fragments can never be harvested again.
    if post_residual == 0 && remaining_frac < 0.12 && open_bins_count > 2 {
        score -= 90.0 * (1.0 - remaining_frac * 8.0).max(0.0);
    }

    // GEN 41 MUTATION: harvest-window reservation — scarce pockets should
    // be spent exactly, not stranded.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after == 0 {
            score -= 120.0;
        } else if after <= 4 {
            score -= 70.0;
        }
    }

    // GEN 41 MUTATION: mid-band waste smoothing — penalize the awkward
    // 13..=18 zone with a linear ramp tied to stream position.
    if post_residual >= 13 && post_residual <= 18 {
        score += 9.0 + (18 - post_residual as i32) as f64 * 2.2 * (0.5 + progress);
    }

    // GEN 46 MUTATION: dual-residual compaction — when the placement leaves
    // a residual that the NEXT item can consume exactly, and the bin after
    // that would close exactly too, reward the double-closure plan. This
    // combines fine-grained residual fitting with lookahead anticipation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next == 0 {
            score -= 34.0 * (1.0 - progress * 0.5);
        } else if after_next >= 1 && after_next <= 3 && progress > 0.5 {
