    if post_residual >= 19 && post_residual <= 29 && open_bins_count > 2 {
        score += 6.0 + 0.9 * (open_bins_count.min(10) as f64);
    }

    // GEN 46 MUTATION: fresh-bin exact-closure dominance — opening a new
    // bin only pays off if its eventual leftover is tiny; when the fresh
    // bin's post_residual exceeds the next item plus a small slack, tax
