    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let fresh_left = bin_capacity - item_size;
        if fresh_left > next_item_size {
            let over = fresh_left - next_item_size;
            if over > 10 {
                score += 8.0 + 0.55 * (over.min(40) as f64);
            } else {
                score -= 20.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
