        }
    }

    // Crowding-aware tight-fit amplifier.
    if open_bins_count > 5 && fitting_bins_count > 2 && post_residual > 0 && post_residual <= 20 {
        score += (post_residual as f64) * 0.9;
    }

    // Next-item large rescue.
    if next_item_size > 0 && next_item_size > bin_capacity / 3 && post_residual > 0
        && post_residual < next_item_size && fitting_bins_count > 1 {
        score += 18.0 * (1.0 - progress).max(0.3);
    }

    // Perfect-pair-vs-fresh arbitration — zero-waste two-step plan should
    // dominate even a fresh-bin opening; sharpen with a late-stream multiplier.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 0 {
        score -= 24.0 + 30.0 * progress;
    }

    // GEN 41: variance-crushing tight-fit ladder — fine-grained continuous
    // descent distinguishing near-tight fits in the 1..=12 dead-space band.
    if post_residual > 0 && post_residual <= 12 && fitting_bins_count >= 1 {
        let ladder = 12.0 - post_residual as f64;
        score -= ladder * ladder * 0.85;
    }

    // GEN 41: perfect-closure urgency — near stream end, exact closure is
    // worth far more because leftover fragments can never be harvested again.
    if post_residual == 0 && remaining_frac < 0.12 && open_bins_count > 2 {
        score -= 90.0 * (1.0 - remaining_frac * 8.0).max(0.0);
    }

    // GEN 41: harvest-window reservation — scarce fitting bins should leave
    // residuals exactly consumable by the next item.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after == 0 {
            score -= 120.0;
        } else if after <= 4 {
            score -= 70.0;
        }
    }

    // GEN 41: mid-band waste smoothing — penalize the awkward 13..=18 zone
    // with a linear ramp tied to stream position.
    if post_residual >= 13 && post_residual <= 18 {
        score += 9.0 + (18 - post_residual as i32) as f64 * 2.2 * (0.5 + progress);
    }

    // GEN 46 MUTATION: two-step compaction ladder — combine fine-grained
    // residual fitting with lookahead anticipation. When the residual left
    // after placing the next item is tiny (1..=9), rank placements
    // continuously so the smallest surviving fragment wins, sharpened late
    // in the stream when fragments can no longer be harvested.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next <= 9 {
            let urgency = 1.0 + progress;
            score -= (10.0 - after_next as f64) * (10.0 - after_next as f64) * 1.1 * urgency;
        }
    }

    // GEN 46 MUTATION: fragment-starvation gate — when few bins can host the
    // next item, tax placements that strand a residual just below it
    // (unharvestable pocket) proportionally to how close the gap is.
    if fitting_bins_count <= 3 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 10 {
            score += (11.0 - gap as f64) * 3.2 * (0.6 + 0.8 * progress);
        }
    }

    // GEN 46 MUTATION: fresh-bin exact-closure demand — only open a fresh bin
    // when its remaining space after this item is either exactly tileable by
    // the next item or large enough to remain useful; otherwise prefer
    // squeezing into existing bins.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let fresh_left = bin_capacity - item_size;
        if fresh_left < next_item_size {
            let stranded = next_item_size - fresh_left;
            if stranded <= 8 {
                score += 70.0 * (0.5 + progress);
            }
        }
    }

    // GEN 46 MUTATION: exact-triple sweep — reward placements where current +
    // next + next again exactly closes the bin (three-item zero-waste plan),
    // a strong consolidation signal the parent only partially covers.
    if next_item_size > 0 && bin_residual >= item_size + 2 * next_item_size {
        let t3 = bin_residual - item_size - 2 * next_item_size;
        if t3 == 0 {
            score -= 96.0 + 60.0 * progress;
        } else if t3 <= 3 {
            score -= 48.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward near-perfect fits (refined tiering, sharpened top tier).
    if post_residual == 0 {
        score -= 1250.0;
    } else if post_residual <= 3 {
        score -= 382.0;
    } else if post_residual <= 5 {
        score -= 332.0;
    } else if post_residual <= 15 {
        score -= 95.0;
    } else if post_residual <= 25 {
        score -= 32.0;
    }

    // Penalize dead space that no plausible item can fill (smooth version).
    if post_residual > 0 && post_residual < 4 {
        score += 70.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 135.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 592.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 186.0;
            } else {
                score -= 150.0 - (slack as f64).min(150.0);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 2.3;
        }
        let next_class = ((next_item_size / 10) as f64).max(1.0);
        if post_residual > 0 && (post_residual as f64) % next_class == 0.0 {
            score -= 27.0;
        }
    }

    // Triple lookahead: current + next-item chain via residual divisibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 12 {
            score -= 55.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // Class-matching reward.
    let complement = (bin_capacity - item_size) / 10;
    if post_class == complement {
        score -= 42.0;
    }

    // Prefer filling fuller bins (tight packing).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 60.0;

    // Two-item lookahead.
    let pair = item_size.saturating_add(next_item_size);
    if pair > 0 && bin_residual >= pair {
        let pair_slack = bin_residual - pair;
        if pair_slack <= 8 {
            score -= 105.0;
        } else {
            score -= 32.0;
        }
