    // Pair exactness — residual exactly equals current+next is a jackpot.
    if pair > 0 && bin_residual == pair {
        score -= 266.0;
    }

    // Multi-fill potential.
    if next_item_size > 0 && post_residual >= next_item_size {
        let multi = post_residual / next_item_size;
        if multi >= 2 {
            score -= 22.0 * (multi.min(4) as f64);
        }
    }

    // Reusability shaping.
    if post_residual > 0 {
        let reusability = post_residual as f64 / bin_capacity as f64;
        if reusability >= 0.15 && reusability <= 0.45 {
            score -= 30.0;
        } else if reusability > 0.45 && reusability < 0.60 {
            score += 13.0;
        }
    }

    // Exact-complement chain.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 68.0;
        }
    }

    // Avoid leaving residuals just below the next item size (dead pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 50.0;
        }
    }

    // Dead-pocket depth tax.
    if post_residual > 0 && post_residual <= 9 {
        score += 18.0 * (10 - post_residual as i32) as f64;
